INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba35eb27-da3d-4065-b0bc-5221951b43ed', '醒起獨酌懷友', '醒起独酌懷友', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["西風靜夜吹蓮塘，芙蓉破紅金粉香。","摘花把酒弄秋芳，吳雲楚水愁茫茫。","美人此夕不入夢，獨宿高樓明月涼。"]', '["西风静夜吹蓮塘，芙蓉破紅金粉香。","摘花把酒弄秋芳，吳云楚水愁茫茫。","美人此夕不入梦，独宿高楼明月涼。"]', '诗', 'shi', '', NULL, '醒起獨酌懷友 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51f105d6-4a07-4476-a2c6-09fb4207cab1', '競渡時在湖外偶爲成章', '競渡时在湖外偶爲成章', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["雷奔電逝三千兒，彩舟畫檝射初暉。","喧江雷鼓鱗甲動，三十六龍銜浪飛。","靈均昔日投湘死，千古沈魂在湘水。","綠草斜煙日暮時，笛聲幽遠愁江鬼。"]', '["雷奔電逝三千兒，彩舟畫檝射初暉。","喧江雷鼓鱗甲动，三十六龙銜浪飞。","靈均昔日投湘死，千古沈魂在湘水。","綠草斜煙日暮时，笛声幽远愁江鬼。"]', '诗', 'shi', '', NULL, '競渡時在湖外偶爲成章 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac5d0eeb-5cf7-4d43-a65d-a7a2b4b5d9e5', '新荷', '新荷', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["田田八九葉，散點綠池初。","嫩碧纔平水，圓陰已蔽魚。","浮萍遮不合，弱荇繞猶疎。","半在春波底，芳心卷未舒。"]', '["田田八九葉，散点綠池初。","嫩碧纔平水，圓陰已蔽鱼。","浮萍遮不合，弱荇繞猶疎。","半在春波底，芳心卷未舒。"]', '诗', 'shi', '', NULL, '新荷 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85d5849f-c09a-4cf9-91b2-a795803e65ab', '初月二首 一', '初月二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["灩灩流光淺，娟娟汎露輕。","雲間龍爪落，簾上玉鉤明。","桂樹枝猶小，仙人影未成。","欲爲千里別，倚幌獨含情。"]', '["灩灩流光淺，娟娟汎露轻。","云间龙爪落，簾上玉鉤明。","桂樹枝猶小，仙人影未成。","欲爲千里別，倚幌独含情。"]', '诗', 'shi', '', NULL, '初月二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb04f64e-5473-4dc9-b800-c48fddf7f2b9', '初月二首 二', '初月二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["凝顰立戶前，細魄向娟娟。","破鏡徒相問，刀頭恐隔年。","輕輕搖遠水，脉脉下春煙。"]', '["凝顰立戶前，細魄向娟娟。","破镜徒相问，刀头恐隔年。","轻轻搖远水，脉脉下春煙。"]', '诗', 'shi', '', NULL, '初月二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0bc403a-eba8-4a13-869a-5e729e1391aa', '石瀦', '石瀦', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["古岸陶爲器，高林盡一焚。","燄紅湘浦口，煙濁洞庭雲。","迥野煤飛亂，遙空爆響聞。","地形穿鑿勢，恐到祝融墳。"]', '["古岸陶爲器，高林尽一焚。","燄紅湘浦口，煙濁洞庭云。","迥野煤飞亂，遙空爆响闻。","地形穿鑿勢，恐到祝融墳。"]', '诗', 'shi', '', NULL, '石瀦 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4725ac5-87e9-4734-aadb-60bb63e4e28a', '雲安', '云安', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["灘惡黃牛吼，城孤白帝秋。","水寒巴字急，歌迥竹枝愁。","樹暗荆王館，雲昏蜀客舟。","瑤姬不可見，行雨在高丘。"]', '["灘惡黄牛吼，城孤白帝秋。","水寒巴字急，歌迥竹枝愁。","樹暗荆王館，云昏蜀客舟。","瑤姬不可见，行雨在高丘。"]', '诗', 'shi', '', NULL, '雲安 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c5ec95b-442c-4e6a-922b-4feb5956575b', '石頭城', '石头城', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["伯業隨流水，寒蕪上古城。","長空橫海色，斷岸落潮聲。","八極悲扶拄，五湖來止傾。","東南天子氣，掃地入函京。"]', '["伯業隨流水，寒蕪上古城。","长空橫海色，斷岸落潮声。","八極悲扶拄，五湖来止傾。","东南天子氣，掃地入函京。"]', '诗', 'shi', '', NULL, '石頭城 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84d35096-b9f6-424b-bc43-bd88defa5748', '湖闊', '湖闊', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["楚色籠青草，秋風洗洞庭。","夕霏生水寺，初月盡雲汀。","櫂響來空闊，漁歌發杳冥。","欲浮闌下艇，一到斗牛星。"]', '["楚色籠青草，秋风洗洞庭。","夕霏生水寺，初月尽云汀。","櫂响来空闊，漁歌發杳冥。","欲浮闌下艇，一到斗牛星。"]', '诗', 'shi', '', NULL, '湖闊 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b02711f-9cd0-413a-9f39-60a0a20624a1', '失鶴', '失鹤', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["瑤臺煙霧外，一去不迴心。","清海蓬壺遠，秋風碧落深。","墮翎留片雪，雅操入孤琴。","豈是籠中物，雲蘿莫更尋。"]', '["瑤台煙霧外，一去不迴心。","清海蓬壺远，秋风碧落深。","墮翎留片雪，雅操入孤琴。","豈是籠中物，云蘿莫更尋。"]', '诗', 'shi', '', NULL, '失鶴 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac03417d-e395-4f6c-8cf3-640dde55d0bf', '臘夜雪霽月彩交光開閣臨軒竟睡不得命家僕吹笙數曲獨引一壺奉寄江陵副使杜中丞', '臘夜雪霽月彩交光开閣臨軒竟睡不得命家僕吹笙數曲独引一壺奉寄江陵副使杜中丞', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["月華臨霽雪，皓彩射貂裘。","桂酒寒無醉，銀笙凍不流。","懷哉梁苑客，思作剡溪遊。","竟夕吟瓊樹，川途恨阻修。"]', '["月华臨霽雪，皓彩射貂裘。","桂酒寒無醉，銀笙凍不流。","懷哉梁苑客，思作剡溪游。","竟夕吟瓊樹，川途恨阻修。"]', '诗', 'shi', '', NULL, '臘夜雪霽月彩交光開閣臨軒竟睡不得命家僕吹笙數曲獨引一壺奉寄江陵副使杜中丞 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6477ca8-4805-4126-a70a-70de90f97074', '長沙陪裴大夫登北樓', '长沙陪裴大夫登北楼', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["巖嶂隨高步，琴尊奉勝遊。","金風吹綠簟，湘水入朱樓。","朗抱雲開月，高情鶴見秋。","登臨多暇日，非爲賦消憂。"]', '["巖嶂隨高步，琴尊奉勝游。","金风吹綠簟，湘水入朱楼。","朗抱云开月，高情鹤见秋。","登臨多暇日，非爲賦消憂。"]', '诗', 'shi', '', NULL, '長沙陪裴大夫登北樓 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aae3bbd2-151b-48df-9b2c-748fc9b36f58', '登蒲澗寺後二巖三首 一', '登蒲澗寺後二巖三首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["五仙騎五羊，何代降茲鄉。","澗有堯年韭，山餘禹日糧。","樓臺籠海色，草樹發天香。","浩嘯波光裏，浮溟興甚長。"]', '["五仙騎五羊，何代降茲乡。","澗有堯年韭，山餘禹日糧。","楼台籠海色，草樹發天香。","浩嘯波光裏，浮溟兴甚长。"]', '诗', 'shi', '', NULL, '登蒲澗寺後二巖三首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70785904-72d3-4220-8cfa-2bd3c9a77997', '登蒲澗寺後二巖三首 二', '登蒲澗寺後二巖三首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["行盡崎嶇路，驚從汗漫遊。","青天豁眼快，碧海醒心秋。","便欲尋河漢，因之犯斗牛。","九霄身自致，何必遇浮丘。"]', '["行尽崎嶇路，驚從汗漫游。","青天豁眼快，碧海醒心秋。","便欲尋河漢，因之犯斗牛。","九霄身自致，何必遇浮丘。"]', '诗', 'shi', '', NULL, '登蒲澗寺後二巖三首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('006a303a-707a-441d-a518-21a602bdcb03', '登蒲澗寺後二巖三首 三', '登蒲澗寺後二巖三首 三', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["南溟吞越絕，極望碧鴻濛。","龍渡潮聲裏，雷喧雨氣中。","趙佗丘壠滅，馬援鼓鼙空。","遐想魚鵬化，開襟九萬風。"]', '["南溟吞越絕，極望碧鴻濛。","龙渡潮声裏，雷喧雨氣中。","趙佗丘壠滅，马援鼓鼙空。","遐想鱼鵬化，开襟九万风。"]', '诗', 'shi', '', NULL, '登蒲澗寺後二巖三首 三 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe6fd13-9ca6-4eb3-bd2d-ce57b1e4d7af', '早鴻', '早鴻', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["木落波浪動，南飛聞夜鴻。","參差天漢霧，嘹唳月明風。","野水蓮莖折，寒泥稻穗空。","無令一行侶，相失五湖中。"]', '["木落波浪动，南飞闻夜鴻。","參差天漢霧，嘹唳月明风。","野水蓮莖折，寒泥稻穗空。","無令一行侶，相失五湖中。"]', '诗', 'shi', '', NULL, '早鴻 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76a3a9b7-dc04-4d49-9fa0-3787cf29edbe', '旅泊', '旅泊', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["搖落江天裏，飄零倚客舟。","短篇纔遣悶，小釀不供愁。","沙雨潮痕細，林風月影稠。","書空閑度日，深擁破貂裘。"]', '["搖落江天裏，飄零倚客舟。","短篇纔遣悶，小釀不供愁。","沙雨潮痕細，林风月影稠。","书空闲度日，深擁破貂裘。"]', '诗', 'shi', '', NULL, '旅泊 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1057eda6-000f-4488-8e02-6f17d05206cf', '半醉', '半醉', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["處俗常如病，看花亦似秋。","若無時復酒，寧遣鎮長愁。","漸覺身非我，都迷蝶與周。","何煩五色藥，尊下即丹丘。"]', '["处俗常如病，看花亦似秋。","若無时复酒，寧遣鎮长愁。","漸覺身非我，都迷蝶與周。","何煩五色藥，尊下即丹丘。"]', '诗', 'shi', '', NULL, '半醉 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a25ff7-c79b-490b-b98c-32bfcb65999f', '晝寐', '晝寐', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["筠桂晚蕭疎，任人嘲宰予。","鳥驚林下夢，風展枕前書。","正作莊生蝶，誰知惠子魚。","人間無樂事，直擬到華胥。"]', '["筠桂晚蕭疎，任人嘲宰予。","鸟驚林下梦，风展枕前书。","正作莊生蝶，誰知惠子鱼。","人间無乐事，直擬到华胥。"]', '诗', 'shi', '', NULL, '晝寐 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dd0a401-48b9-46a6-a407-191a9f45d974', '晚蓮', '晚蓮', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["露冷芳意盡，稀疎空碧荷。","殘香隨暮雨，枯蘂墮寒波。","楚客罷奇服，吳姬停櫂歌。","涉江無可寄，幽恨竟如何。"]', '["露冷芳意尽，稀疎空碧荷。","殘香隨暮雨，枯蘂墮寒波。","楚客罷奇服，吳姬停櫂歌。","涉江無可寄，幽恨竟如何。"]', '诗', 'shi', '', NULL, '晚蓮 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a5c3d8-1b8b-4cf5-bc40-fd37df62c1ff', '將之番禺留別湖南府幕', '將之番禺留別湖南府幕', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["本乏煙霞志，那隨鴛鷺遊。","一枝仍未定，數粒欲何求。","溟漲道途遠，荆吳雲雪愁。","會登梅嶺翠，南翥入炎洲。"]', '["本乏煙霞志，那隨鴛鷺游。","一枝仍未定，數粒欲何求。","溟漲道途远，荆吳云雪愁。","會登梅嶺翠，南翥入炎洲。"]', '诗', 'shi', '', NULL, '將之番禺留別湖南府幕 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7fd18c1-183f-49b7-8bb2-d61bac37c1fe', '宵民', '宵民', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["大雅無憂怨，宵民有愛憎。","魯侯天不遇，臧氏爾何能。","慘慘心如虺，營營舌似蠅。","誰於銷骨地，一鑒玉壺冰。"]', '["大雅無憂怨，宵民有愛憎。","魯侯天不遇，臧氏爾何能。","慘慘心如虺，營營舌似蠅。","誰於銷骨地，一鑒玉壺冰。"]', '诗', 'shi', '', NULL, '宵民 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('351b0052-533b-40d3-a321-bcbba6c8dd2b', '吾道', '吾道', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["吾道成微哂，時情付絕言。","鳳兮衰已盡，犬也吠何繁。","輕重憂衡曲，妍媸慮鏡昏。","方忻耳目淨，誰到翟公門。"]', '["吾道成微哂，时情付絕言。","鳳兮衰已尽，犬也吠何繁。","轻重憂衡曲，妍媸慮镜昏。","方忻耳目淨，誰到翟公门。"]', '诗', 'shi', '', NULL, '吾道 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72d4cb05-629b-4a9e-baee-6c46c3bdb37f', '與三山人夜話', '與三山人夜話', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["靜談雲鶴趣，高會兩三賢。","酒思彈琴夜，茶芳向火天。","兔裘堆膝暖，鳩杖倚牀偏。","各厭池籠窄，相看意浩然。"]', '["静談云鹤趣，高會兩三賢。","酒思彈琴夜，茶芳向火天。","兔裘堆膝暖，鳩杖倚牀偏。","各厭池籠窄，相看意浩然。"]', '诗', 'shi', '', NULL, '與三山人夜話 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39622c84-f360-45e2-abb9-3a45bba5c28e', '春寒', '春寒', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["撥火垂簾夕，將暄向冷天。","悶斟壺酒暖，愁聽雨聲眠。","處世心悠爾，干時思索然。","春光看已半，明日又藏煙。"]', '["撥火垂簾夕，將暄向冷天。","悶斟壺酒暖，愁听雨声眠。","处世心悠爾，干时思索然。","春光看已半，明日又藏煙。"]', '诗', 'shi', '', NULL, '春寒 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44be7020-65f8-4887-b142-f276103aab2a', '廣江驛餞筵留別', '廣江驛餞筵留別', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["別筵欲盡秋，一醉海西樓。","夜雨寒潮水，孤燈萬里舟。","酒飛鸚鵡重，歌送鷓鴣愁。","惆悵三年客，難期此處遊。"]', '["別筵欲尽秋，一醉海西楼。","夜雨寒潮水，孤灯万里舟。","酒飞鸚鵡重，歌送鷓鴣愁。","惆悵三年客，难期此处游。"]', '诗', 'shi', '', NULL, '廣江驛餞筵留別 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5260b2b8-0e1d-4949-97f0-59e3a7ee567a', '桑落洲', '桑落洲', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["九江寒露夕，微浪北風生。","浦嶼漁人火，蒹葭鳧鴈聲。","頹雲晦廬岳，微鼓辨湓城。","遠憶天邊弟，曾從此路行。"]', '["九江寒露夕，微浪北风生。","浦嶼漁人火，蒹葭鳧鴈声。","頹云晦廬岳，微鼓辨湓城。","远憶天邊弟，曾從此路行。"]', '诗', 'shi', '', NULL, '桑落洲 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad533ef4-17d9-4dcb-8ddc-1243c1073ef0', '杜門', '杜门', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["且詠閑居賦，飛翔去未能。","春風花嶼酒，秋雨竹溪燈。","世路變陵谷，時情驗友朋。","達生書一卷，名利付春冰。"]', '["且詠闲居賦，飞翔去未能。","春风花嶼酒，秋雨竹溪灯。","世路变陵谷，时情驗友朋。","達生书一卷，名利付春冰。"]', '诗', 'shi', '', NULL, '杜門 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('296bb418-d75a-4e0b-b659-ae6b0620668d', '池州封員外郡齋雙鶴丹頂霜翎仙態浮曠罷政之日因呈此章', '池州封員外郡斋雙鹤丹頂霜翎仙態浮曠罷政之日因呈此章', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["瀟灑二白鶴，對之高興清。","寒溪侶雲水，朱閣伴琴笙。","顧慕稻粱惠，超遙江海情。","應攜帝鄉去，仙闕看飛鳴。"]', '["瀟灑二白鹤，对之高兴清。","寒溪侶云水，朱閣伴琴笙。","顧慕稻粱惠，超遙江海情。","應携帝乡去，仙闕看飞鳴。"]', '诗', 'shi', '', NULL, '池州封員外郡齋雙鶴丹頂霜翎仙態浮曠罷政之日因呈此章 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d440b1f-0f4d-4c6c-8d57-308d35313799', '經費拾遺所居呈封員外', '經費拾遺所居呈封員外', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["雲臥竟不起，少微空隕光。","唯應孔北海，爲立鄭公鄉。","舊館苔蘚合，幽齋松菊荒。","空餘書帶草，日日上階長。"]', '["云臥竟不起，少微空隕光。","唯應孔北海，爲立鄭公乡。","旧館苔蘚合，幽斋松菊荒。","空餘书带草，日日上階长。"]', '诗', 'shi', '', NULL, '經費拾遺所居呈封員外 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18729cec-3cb8-4d8b-857f-6e0f1d51743c', '送秦鍊師', '送秦鍊師', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["紫府靜沈沈，松軒思別琴。","水流寧有意，雲汎本無心。","錦洞桃花遠，青山竹葉深。","不因時賣藥，何路更相尋。"]', '["紫府静沈沈，松軒思別琴。","水流寧有意，云汎本無心。","錦洞桃花远，青山竹葉深。","不因时賣藥，何路更相尋。"]', '诗', 'shi', '', NULL, '送秦鍊師 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcbb8b88-b714-4455-a08b-676173439020', '湘陰縣送遷客北歸', '湘陰縣送遷客北归', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["不須留薏苡，重遣世人疑。","瘴染面如蘗，愁熏頭似絲。","黃梅住雨外，青草過湖時。","今日開湯網，冥飛亦未遲。"]', '["不須留薏苡，重遣世人疑。","瘴染面如蘗，愁熏头似絲。","黄梅住雨外，青草過湖时。","今日开湯網，冥飞亦未遲。"]', '诗', 'shi', '', NULL, '湘陰縣送遷客北歸 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df712798-3819-492a-b794-2b9f8ef93bf1', '九日陪崔大夫讌清河亭', '九日陪崔大夫讌清河亭', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["玉醴浮金菊，雲亭敞玳筵。","晴山低畫浦，斜雁遠書天。","謝朓離都日，殷公出守年。","不知瑤水讌，誰和白雲篇。"]', '["玉醴浮金菊，云亭敞玳筵。","晴山低畫浦，斜雁远书天。","謝朓離都日，殷公出守年。","不知瑤水讌，誰和白云篇。"]', '诗', 'shi', '', NULL, '九日陪崔大夫讌清河亭 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96901202-1995-48b6-812b-c8c6bb0ebb54', '送房處士閑遊', '送房处士闲游', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["採藥陶貞白，尋山許遠遊。","刀圭藏妙用，巖洞契冥搜。","花月三江水，琴尊一葉舟。","羨君隨野鶴，長揖稻粱愁。"]', '["採藥陶貞白，尋山許远游。","刀圭藏妙用，巖洞契冥搜。","花月三江水，琴尊一葉舟。","羨君隨野鹤，长揖稻粱愁。"]', '诗', 'shi', '', NULL, '送房處士閑遊 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55d31c7b-1137-48c0-ad9d-6103ae1e4a04', '贈花', '贈花', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["酒爲看花醞，花須趁酒紅。","莫令芳樹晚，使我綠尊空。","金谷園無主，桃源路不通。","縱非乘露折，長短盡隨風。"]', '["酒爲看花醞，花須趁酒紅。","莫令芳樹晚，使我綠尊空。","金谷园無主，桃源路不通。","縱非乘露折，长短尽隨风。"]', '诗', 'shi', '', NULL, '贈花 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5729608-776b-4123-b626-c5262834fa9e', '洞庭風雨二首 一', '洞庭风雨二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["面南一片黑，俄起北風顛。","浪潑巴陵樹，雷燒鹿角田。","魚龍方簸蕩，雲雨正喧闐。","想赭君山日，秦皇怒赫然。"]', '["面南一片黑，俄起北风顛。","浪潑巴陵樹，雷燒鹿角田。","鱼龙方簸蕩，云雨正喧闐。","想赭君山日，秦皇怒赫然。"]', '诗', 'shi', '', NULL, '洞庭風雨二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c1dc03f-300a-4398-ba67-e09763ad1b5d', '洞庭風雨二首 二', '洞庭风雨二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["巨浸吞湘澧，西風忽怒號。","水將天共黑，雲與浪爭高。","羽化思乘鯉，山漂欲抃鼇。","陽烏猶曝翅，真恐濕蟠桃。"]', '["巨浸吞湘澧，西风忽怒號。","水將天共黑，云與浪爭高。","羽化思乘鯉，山漂欲抃鼇。","陽烏猶曝翅，真恐濕蟠桃。"]', '诗', 'shi', '', NULL, '洞庭風雨二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25beae78-14ac-46b9-a7e0-f163678d0b2d', '臨水薔薇', '臨水薔薇', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["堪愛復堪傷，無情不久長。","浪搖千臉笑，風舞一叢芳。","似濯文君錦，如窺漢女妝。"]', '["堪愛复堪傷，無情不久长。","浪搖千臉笑，风舞一叢芳。","似濯文君錦，如窺漢女妝。"]', '诗', 'shi', '', NULL, '臨水薔薇 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f5252d2-a84e-4f69-948d-d823672433cc', '中秋維舟君山看月二首 一', '中秋維舟君山看月二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["汗漫鋪澄碧，朦朧吐玉盤。","雨師清滓穢，川后掃波瀾。","氣射繁星滅，光籠八表寒。","來從雲漲迥，路上碧霄寬。"]', '["汗漫鋪澄碧，朦朧吐玉盤。","雨師清滓穢，川后掃波瀾。","氣射繁星滅，光籠八表寒。","来從云漲迥，路上碧霄寬。"]', '诗', 'shi', '', NULL, '中秋維舟君山看月二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64d0ffb7-437c-462a-ac97-fa1659a996c8', '中秋維舟君山看月二首 二', '中秋維舟君山看月二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["熠燿遊何處，蟾蜍食漸殘。","櫂翻銀浪急，林映白虹攢。","練彩連河曉，冰暉壓樹乾。","夜深高不動，天下仰頭看。"]', '["熠燿游何处，蟾蜍食漸殘。","櫂翻銀浪急，林映白虹攢。","練彩連河晓，冰暉壓樹乾。","夜深高不动，天下仰头看。"]', '诗', 'shi', '', NULL, '中秋維舟君山看月二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2259ff3f-30e6-47e1-befa-bd6478b7b24d', '桂州經佳人故居琪樹', '桂州經佳人故居琪樹', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["種樹人何在，攀枝空歎嗟。","人無重見日，樹有每年花。","滿院雀聲莫，半庭春景斜。","東風不知恨，徧地落餘霞。"]', '["種樹人何在，攀枝空歎嗟。","人無重见日，樹有每年花。","满院雀声莫，半庭春景斜。","东风不知恨，徧地落餘霞。"]', '诗', 'shi', '', NULL, '桂州經佳人故居琪樹 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22eea315-a2bc-455d-890a-8cf9834412d4', '贈元紱', '贈元紱', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["相逢在總角，與子即同心。","隱石那知玉，披沙始遇金。","蘭秋香不死，松晚翠方深。","各保芳堅性，寧憂霜霰侵。"]', '["相逢在總角，與子即同心。","隐石那知玉，披沙始遇金。","蘭秋香不死，松晚翠方深。","各保芳堅性，寧憂霜霰侵。"]', '诗', 'shi', '', NULL, '贈元紱 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ce4ac4-1f05-4fca-b78c-6f3b77470110', '中秋廣江驛示韋益', '中秋廣江驛示韋益', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["莫惜三更坐，難消萬里情。","同看一片月，俱在廣州城。","淚逐金波滿，魂隨夜鵲驚。","支頤鄉思斷，無語到雞鳴。"]', '["莫惜三更坐，难消万里情。","同看一片月，俱在廣州城。","泪逐金波满，魂隨夜鵲驚。","支頤乡思斷，無語到雞鳴。"]', '诗', 'shi', '', NULL, '中秋廣江驛示韋益 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6617a865-a0cb-4c37-94cb-8407f6205104', '九日越臺', '九日越台', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["旭日高山上，秋天大海隅。","黃花羅粔籹，絳實簇茱萸。","病久歡情薄，鄉遙客思孤。","無心同落帽，天際望歸途。"]', '["旭日高山上，秋天大海隅。","黄花羅粔籹，絳實簇茱萸。","病久歡情薄，乡遙客思孤。","無心同落帽，天際望归途。"]', '诗', 'shi', '', NULL, '九日越臺 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5761f729-fba0-4a0f-9443-62be1e40288d', '中秋越臺看月', '中秋越台看月', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["海雨洗塵埃，月從空碧來。","水光籠草樹，練影挂樓臺。","皓曜迷鯨目，晶熒失蚌胎。","宵分凭檻望，應合見蓬萊。"]', '["海雨洗塵埃，月從空碧来。","水光籠草樹，練影挂楼台。","皓曜迷鯨目，晶熒失蚌胎。","宵分凭檻望，應合见蓬萊。"]', '诗', 'shi', '', NULL, '中秋越臺看月 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b484cb04-a647-420d-b690-2b7ecacc88c8', '長沙開元寺昔與故長林許侍御題松竹聯句', '长沙开元寺昔與故长林許侍御題松竹聯句', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["墻陰數行字，懷舊慘傷情。","薜荔侵年月，莓苔壓姓名。","逝川前後水，浮世短長生。","獨立秋風暮，凝顰隔郢城。"]', '["墻陰數行字，懷旧慘傷情。","薜荔侵年月，莓苔壓姓名。","逝川前後水，浮世短长生。","独立秋风暮，凝顰隔郢城。"]', '诗', 'shi', '', NULL, '長沙開元寺昔與故長林許侍御題松竹聯句 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7845167-8968-45a8-aa20-4265a08353d8', '傷友', '傷友', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["玉棺來九天，鳧舃掩窮泉。","蕪沒池塘嶼，淒涼翰墨筵。","短期存大夢，舊好委浮煙。","我有幽蘭曲，因君遂絕弦。"]', '["玉棺来九天，鳧舃掩窮泉。","蕪沒池塘嶼，淒涼翰墨筵。","短期存大梦，旧好委浮煙。","我有幽蘭曲，因君遂絕弦。"]', '诗', 'shi', '', NULL, '傷友 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee4eaff-0fa8-421e-8c79-beb50fcba2d9', '法性寺六祖戒壇', '法性寺六祖戒壇', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["初地無階級，餘基數尺低。","天香開茉莉，梵樹落菩提。","驚俗生真性，青蓮出淤泥。","何人得心法，衣鉢在曹溪。"]', '["初地無階級，餘基數尺低。","天香开茉莉，梵樹落菩提。","驚俗生真性，青蓮出淤泥。","何人得心法，衣鉢在曹溪。"]', '诗', 'shi', '', NULL, '法性寺六祖戒壇 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e86c6d6-5988-47f3-bd99-16f6e8125749', '東湖二首 一', '东湖二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["晚景微雨歇，逍遙湖上亭。","波閑魚弄餌，樹靜鳥遺翎。","性野難依俗，詩玄自入冥。","何繇遂瀟灑，高枕對雲汀。"]', '["晚景微雨歇，逍遙湖上亭。","波闲鱼弄餌，樹静鸟遺翎。","性野难依俗，诗玄自入冥。","何繇遂瀟灑，高枕对云汀。"]', '诗', 'shi', '', NULL, '東湖二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6fb3c9-8c96-4466-98de-fb6cfdd75ed5', '東湖二首 二', '东湖二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["雨氣消殘暑，蒼蒼月欲升。","林間風捲簟，欄下水搖燈。","迥野垂銀鏡，層巒挂玉繩。","重期浮小檝，來摘半湖菱。"]', '["雨氣消殘暑，蒼蒼月欲升。","林间风捲簟，欄下水搖灯。","迥野垂銀镜，層巒挂玉繩。","重期浮小檝，来摘半湖菱。"]', '诗', 'shi', '', NULL, '東湖二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b43bb9bd-1791-42a1-bcda-1c0be2b43677', '湖閣曉晴寄呈從翁二首 一', '湖閣晓晴寄呈從翁二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["嶺日開寒霧，湖光蕩霽華。","風烏搖逕柳，水蝶戀幽花。","蜀國地西極，吳門天一涯。","輕舟欄下去，點點入湘霞。"]', '["嶺日开寒霧，湖光蕩霽华。","风烏搖逕柳，水蝶戀幽花。","蜀国地西極，吳门天一涯。","轻舟欄下去，点点入湘霞。"]', '诗', 'shi', '', NULL, '湖閣曉晴寄呈從翁二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3b203b-0741-47ce-b926-153941ff07ad', '湖閣曉晴寄呈從翁二首 二', '湖閣晓晴寄呈從翁二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["高秋憑遠檻，萬里看新晴。","重霧披天急，千雲觸石輕。","湖山四五點，湘雁兩三聲。","遙想潘園裏，琴尊興轉清。"]', '["高秋憑远檻，万里看新晴。","重霧披天急，千云觸石轻。","湖山四五点，湘雁兩三声。","遙想潘园裏，琴尊兴轉清。"]', '诗', 'shi', '', NULL, '湖閣曉晴寄呈從翁二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad3579b2-b079-4e15-a661-9228916601aa', '同張明府遊漊水亭', '同張明府游漊水亭', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["草色綠溪晚，梅香生縠文。","雲天斂餘霽，水木籠微曛。","垂釣坐方嶼，幽禽時一聞。","何當五柳下，酌醴吟庭筠。"]', '["草色綠溪晚，梅香生縠文。","云天斂餘霽，水木籠微曛。","垂釣坐方嶼，幽禽时一闻。","何當五柳下，酌醴吟庭筠。"]', '诗', 'shi', '', NULL, '同張明府遊漊水亭 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97c21e8e-0753-4981-9eb1-ff3dceba6251', '七月十五夜看月', '七月十五夜看月', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["朦朧南溟月，汹湧出雲濤。","下射長鯨眼，遙分玉兔毫。","勢來星斗動，路越青冥高。","竟夕瞻光彩，昂頭把白醪。"]', '["朦朧南溟月，汹湧出云濤。","下射长鯨眼，遙分玉兔毫。","勢来星斗动，路越青冥高。","竟夕瞻光彩，昂头把白醪。"]', '诗', 'shi', '', NULL, '七月十五夜看月 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ead059e1-1db7-4b16-8459-d4279af71de8', '北風', '北风', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["病髮乾垂枕，臨風強起梳。","蝶飛魂尚弱，蟻鬬體猶虛。","瘦骨呻吟後，羸容几杖初。","庭幽行藥靜，涼暑翠筠疎。"]', '["病髮乾垂枕，臨风強起梳。","蝶飞魂尚弱，蟻鬬體猶虛。","瘦骨呻吟後，羸容几杖初。","庭幽行藥静，涼暑翠筠疎。"]', '诗', 'shi', '', NULL, '北風 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a59d1fc2-2703-4ce6-b58b-e0466b0aec48', '遊玉芝觀', '游玉芝观', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["尋仙向玉清，獨倚雪初晴。","木落寒郊迥，煙開疊嶂明。","片雲盤鶴影，孤磬雜松聲。","且共探玄理，歸途月未生。"]', '["尋仙向玉清，独倚雪初晴。","木落寒郊迥，煙开叠嶂明。","片云盤鹤影，孤磬杂松声。","且共探玄理，归途月未生。"]', '诗', 'shi', '', NULL, '遊玉芝觀 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5997d689-ef60-4b20-837d-f75949653230', '中秋夜南樓寄友人', '中秋夜南楼寄友人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["海月出銀浪，湖光射高樓。","朗吟無淥酒，賤價買清秋。","氣冷魚龍寂，輪高星漢幽。","他鄉此夜客，對景餞多愁。"]', '["海月出銀浪，湖光射高楼。","朗吟無淥酒，賤價買清秋。","氣冷鱼龙寂，輪高星漢幽。","他乡此夜客，对景餞多愁。"]', '诗', 'shi', '', NULL, '中秋夜南樓寄友人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cff0192-56be-437c-a408-6dc780b99d97', '三月五日陪裴大夫汎長沙東湖', '三月五日陪裴大夫汎长沙东湖', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["上巳餘風景，芳辰集遠坰。","綵舟浮滉蕩，繡轂下娉婷。","林榭回蔥蒨，笙歌轉杳冥。","湖光迷翡翠，草色醉蜻蜓。","鳥弄桐花日，魚翻穀雨萍。","從今留勝會，誰肯畫蘭亭。"]', '["上巳餘风景，芳辰集远坰。","綵舟浮滉蕩，繡轂下娉婷。","林榭回蔥蒨，笙歌轉杳冥。","湖光迷翡翠，草色醉蜻蜓。","鸟弄桐花日，鱼翻穀雨萍。","從今留勝會，誰肯畫蘭亭。"]', '诗', 'shi', '', NULL, '三月五日陪裴大夫汎長沙東湖 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3bc2d3-3f57-4b59-bec7-5da00f35d0bc', '龜', '龟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["靜養千年壽，重泉自隱居。","不應隨跛鼈，寧肯滯凡魚。","靈腹唯玄露，芳巢必翠蕖。","揚花輸蚌蛤，犇月恨蟾蜍。","曳尾辭泥後，支牀得水初。","冠山期不小，鑄印事寧虛。","有志酬毛寶，無心畏豫且。","他時清洛汭，會薦帝堯書。"]', '["静養千年壽，重泉自隐居。","不應隨跛鼈，寧肯滯凡鱼。","靈腹唯玄露，芳巢必翠蕖。","揚花輸蚌蛤，犇月恨蟾蜍。","曳尾辞泥後，支牀得水初。","冠山期不小，鑄印事寧虛。","有志酬毛寶，無心畏豫且。","他时清洛汭，會薦帝堯书。"]', '诗', 'shi', '', NULL, '龜 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb952cd6-744b-4ba9-a38a-d149929b52e3', '長沙春望寄涔陽故人', '长沙春望寄涔陽故人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["清明別後雨晴時，極浦空顰一望眉。","湖畔春山煙黯黯，雲中遠樹黑離離。","依微水戍聞疎鼓，掩映河橋見酒旗。","風暖草長愁自醉，行吟無處寄相思。"]', '["清明別後雨晴时，極浦空顰一望眉。","湖畔春山煙黯黯，云中远樹黑離離。","依微水戍闻疎鼓，掩映河橋见酒旗。","风暖草长愁自醉，行吟無处寄相思。"]', '诗', 'shi', '', NULL, '長沙春望寄涔陽故人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5bb15b9-1a39-42ee-bf20-810ce56f4e2d', '金塘路中', '金塘路中', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["山連楚越復吳秦，蓬梗何年是住身。","黃葉黃花古城路，秋風秋雨別家人。","冰霜想度商於凍，桂玉愁居帝里貧。","十口繫心拋不得，每回回首即長顰。"]', '["山連楚越复吳秦，蓬梗何年是住身。","黄葉黄花古城路，秋风秋雨別家人。","冰霜想度商於凍，桂玉愁居帝里貧。","十口繫心拋不得，每回回首即长顰。"]', '诗', 'shi', '', NULL, '金塘路中 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e1a656c-fab9-4ebd-9a6b-38b58234aaa9', '自遣', '自遣', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["翻覆升沈百歲中，前途一半已成空。","浮生暫寄夢中夢，世事如聞風裏風。","修竹萬竿資闃寂，古書千卷要窮通。","一壺濁酒暄和景，誰會陶然失馬翁。"]', '["翻覆升沈百歲中，前途一半已成空。","浮生暫寄梦中梦，世事如闻风裏风。","修竹万竿資闃寂，古书千卷要窮通。","一壺濁酒暄和景，誰會陶然失马翁。"]', '诗', 'shi', '', NULL, '自遣 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e77066b-d350-48fb-a3d3-d5edd0c51555', '送于少監自廣州還紫邏', '送于少監自廣州還紫邏', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["鳴臯山水似麻源，謝監東還憶故園。","海嶠煙霞輕逸翰，洛川花木待回軒。","宦情薄去詩千首，世事閑來酒一尊。","明日中書見顏范，始應通籍入金門。"]', '["鳴臯山水似麻源，謝監东還憶故园。","海嶠煙霞轻逸翰，洛川花木待回軒。","宦情薄去诗千首，世事闲来酒一尊。","明日中书见顏范，始應通籍入金门。"]', '诗', 'shi', '', NULL, '送于少監自廣州還紫邏 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67075277-91a3-48a9-817c-f6f9e81b6498', '石門韋明府爲致東陽潭石鯽鱠', '石门韋明府爲致东陽潭石鯽鱠', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["錦鱗銜餌出清漣，暖日江亭動鱠筵。","疊雪亂飛消箸底，散絲繁灑拂刀前。","太湖浪說朱衣鮒，漢浦休誇縮項鳊。","雋味品流知第一，更勞霜橘助芳鮮。"]', '["錦鱗銜餌出清漣，暖日江亭动鱠筵。","叠雪亂飞消箸底，散絲繁灑拂刀前。","太湖浪说朱衣鮒，漢浦休誇縮項鳊。","雋味品流知第一，更勞霜橘助芳鲜。"]', '诗', 'shi', '', NULL, '石門韋明府爲致東陽潭石鯽鱠 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ca2812b-a3a9-413e-8616-0eef0765111b', '規公業在淨名得甚深義僕近獲顧長康月宮真影對戴安道所畫文殊走筆此篇以屈瞻禮', '規公業在淨名得甚深義僕近獲顧长康月宮真影对戴安道所畫文殊走笔此篇以屈瞻禮', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["五濁之世塵冥冥，達觀棲心于此經。","但用須彌藏芥子，安知牛跡笑東溟。","生公吐辯真無敵，顧氏傳神實有靈。","今日淨開方丈室，一飛白足到茅亭。"]', '["五濁之世塵冥冥，達观棲心于此經。","但用須彌藏芥子，安知牛跡笑东溟。","生公吐辯真無敵，顧氏傳神實有靈。","今日淨开方丈室，一飞白足到茅亭。"]', '诗', 'shi', '', NULL, '規公業在淨名得甚深義僕近獲顧長康月宮真影對戴安道所畫文殊走筆此篇以屈瞻禮 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('350f5dec-de1f-4507-9610-7d0acbac2051', '玉真觀', '玉真观', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["高情帝女慕乘鸞，紺髮初簪玉葉冠。","秋月無雲生碧落，素蕖寒露出清瀾。","層城煙霧將歸遠，浮世塵埃久住難。","一自簫聲飛去後，洞宮深掩碧瑤壇。"]', '["高情帝女慕乘鸾，紺髮初簪玉葉冠。","秋月無云生碧落，素蕖寒露出清瀾。","層城煙霧將归远，浮世塵埃久住难。","一自簫声飞去後，洞宮深掩碧瑤壇。"]', '诗', 'shi', '', NULL, '玉真觀 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c8cb28a-4317-4f34-a566-86eb346a0079', '辱綿州于中丞書信', '辱綿州于中丞书信', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一緘垂露到雲林，中有孫陽念驥心。","萬木自凋山不動，百川皆旱海長深。","風標想見瑤臺鶴，詩韻如聞淥水琴。","他日縱陪池上酌，已應難到暝猨吟。"]', '["一緘垂露到云林，中有孫陽念驥心。","万木自凋山不动，百川皆旱海长深。","风標想见瑤台鹤，诗韻如闻淥水琴。","他日縱陪池上酌，已應难到暝猨吟。"]', '诗', 'shi', '', NULL, '辱綿州于中丞書信 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdd47f1-8510-4ac1-916f-752a6c4642c4', '送崔使君蕭山禱雨甘澤遽降', '送崔使君蕭山禱雨甘澤遽降', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["謝公一拜敬亭祠，五馬旋歸下散絲。","不假土龍呈夭矯，自然石燕起參差。","預聽禾稼如雲語，應有空濛似霧時。","已向爲霖報消息，潁川徵詔是前期。"]', '["謝公一拜敬亭祠，五马旋归下散絲。","不假土龙呈夭矯，自然石燕起參差。","預听禾稼如云語，應有空濛似霧时。","已向爲霖報消息，潁川徵詔是前期。"]', '诗', 'shi', '', NULL, '送崔使君蕭山禱雨甘澤遽降 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0e4542-8324-4e24-80b8-f1e7c0c34749', '重經巴丘追感', '重經巴丘追感', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["昔年高接李膺歡，日汎仙舟醉碧瀾。","詩句亂隨青草發，酒腸俱逐洞庭寬。","浮生聚散雲相似，往事微茫夢一般。","今日片帆城下去，秋風回首淚闌干。"]', '["昔年高接李膺歡，日汎仙舟醉碧瀾。","诗句亂隨青草發，酒腸俱逐洞庭寬。","浮生聚散云相似，往事微茫梦一般。","今日片帆城下去，秋风回首泪闌干。"]', '诗', 'shi', '', NULL, '重經巴丘追感 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cec5e03-f673-44f0-821d-07d0f479136b', '湘陰江亭却寄友人', '湘陰江亭却寄友人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["湘岸初晴淑景遲，風光正是客愁時。","幽花暮落騷人浦，芳草春深帝子祠。","往事隔年如過夢，舊遊回首謾勞思。","煙波自此扁舟去，小酌文園杳未期。"]', '["湘岸初晴淑景遲，风光正是客愁时。","幽花暮落騷人浦，芳草春深帝子祠。","往事隔年如過梦，旧游回首謾勞思。","煙波自此扁舟去，小酌文园杳未期。"]', '诗', 'shi', '', NULL, '湘陰江亭却寄友人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('989f733e-683d-4e77-9045-0ad22155ed95', '哭郴州王使君', '哭郴州王使君', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["銀章朱紱照雲驄，六換魚書惠化崇。","瑤樹忽傾滄海裏，醉鄉翻在夜臺中。","東山妓逐飛花散，北海尊隨逝水空。","曾是綺羅筵上客，一來長慟向春風。"]', '["銀章朱紱照云驄，六換鱼书惠化崇。","瑤樹忽傾滄海裏，醉乡翻在夜台中。","东山妓逐飞花散，北海尊隨逝水空。","曾是綺羅筵上客，一来长慟向春风。"]', '诗', 'shi', '', NULL, '哭郴州王使君 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('255a6e05-bb84-447f-943f-5cb02538a04d', '九日巴丘楊公臺上讌集', '九日巴丘楊公台上讌集', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["淒淒霜日上高臺，水國秋深客思哀。","萬疊銀山寒浪起，一行斜字早鴻來。","誰家擣練孤城暮，何處題衣遠信回？","江漢路長身不定，菊花三笑旅萍開。"]', '["淒淒霜日上高台，水国秋深客思哀。","万叠銀山寒浪起，一行斜字早鴻来。","誰家擣練孤城暮，何处題衣远信回？","江漢路长身不定，菊花三笑旅萍开。"]', '诗', 'shi', '', NULL, '九日巴丘楊公臺上讌集 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73e27159-4cc9-4e88-85da-4aa6eadfe2dc', '奉和張舍人送秦鍊師歸岑公山', '奉和張舍人送秦鍊師归岑公山', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["仙翁歸臥翠微岑，一夜西風月峽深。","松逕定知芳草合，玉書應念素塵侵。","閑雲不繫東西影，野鶴寧知去住心。","蘭浦蒼蒼春欲暮，落花流水怨離琴。"]', '["仙翁归臥翠微岑，一夜西风月峽深。","松逕定知芳草合，玉书應念素塵侵。","闲云不繫东西影，野鹤寧知去住心。","蘭浦蒼蒼春欲暮，落花流水怨離琴。"]', '诗', 'shi', '', NULL, '奉和張舍人送秦鍊師歸岑公山 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f8f727-f4c9-4f9d-9235-3d1315206ac7', '送陶少府赴選', '送陶少府赴選', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["陶君官興本蕭疎，長傍青山碧水居。","久向三茅窮藝術，仍傳五柳舊琴書。","迹同飛鳥棲高樹，心似閑雲在太虛。","自是葛洪求藥價，不關梅福戀簪裾。"]', '["陶君官兴本蕭疎，长傍青山碧水居。","久向三茅窮藝術，仍傳五柳旧琴书。","迹同飞鸟棲高樹，心似闲云在太虛。","自是葛洪求藥價，不关梅福戀簪裾。"]', '诗', 'shi', '', NULL, '送陶少府赴選 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef992371-a867-4a65-81d9-3fbb24233610', '寄張祜', '寄張祜', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["越水吳山任興行，五湖雲月挂高情。","不遊都邑稱平子，只向江東作步兵。","昔歲芳聲到童稚，老來佳句徧公卿。","如君氣力波瀾地，留取陰何沈范名。"]', '["越水吳山任兴行，五湖云月挂高情。","不游都邑稱平子，只向江东作步兵。","昔歲芳声到童稚，老来佳句徧公卿。","如君氣力波瀾地，留取陰何沈范名。"]', '诗', 'shi', '', NULL, '寄張祜 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8d8412a-86ea-469b-96be-5030ebe3139f', '寄長沙許侍御', '寄长沙許侍御', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["三年文會許追隨，和徧南朝雜體詩。","未把彩毫還郭璞，乞留殘錦與丘遲。","竹齋琴酒歡成夢，水寺煙霞賞對誰。","今日秋風滿湘浦，秪應搔首詠瓊枝。"]', '["三年文會許追隨，和徧南朝杂體诗。","未把彩毫還郭璞，乞留殘錦與丘遲。","竹斋琴酒歡成梦，水寺煙霞賞对誰。","今日秋风满湘浦，秪應搔首詠瓊枝。"]', '诗', 'shi', '', NULL, '寄長沙許侍御 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdb6b7c6-8a6e-4eb6-a13e-19eada8ce02f', '望月懷友', '望月懷友', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["浮雲卷盡看朣朧，直出滄溟上碧空。","盈手水光寒不濕，流天素彩靜無風。","酒花蕩漾金尊裏，櫂影飄颻玉浪中。","川路正長難可越，美人千里思何窮。"]', '["浮云卷尽看朣朧，直出滄溟上碧空。","盈手水光寒不濕，流天素彩静無风。","酒花蕩漾金尊裏，櫂影飄颻玉浪中。","川路正长难可越，美人千里思何窮。"]', '诗', 'shi', '', NULL, '望月懷友 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997b631a-bfdd-40d0-9142-69a887e1092e', '和吳中丞悼笙妓', '和吳中丞悼笙妓', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["麗質仙姿煙逐風，鳳皇聲斷吹臺空。","多情草色怨還綠，無主杏花春自紅。","墮珥尚存芳樹下，餘香漸減玉堂中。","唯應去抱雲和管，從此長歸阿母宮。"]', '["丽質仙姿煙逐风，鳳皇声斷吹台空。","多情草色怨還綠，無主杏花春自紅。","墮珥尚存芳樹下，餘香漸減玉堂中。","唯應去抱云和管，從此长归阿母宮。"]', '诗', 'shi', '', NULL, '和吳中丞悼笙妓 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('052653a6-b5e5-4109-9cd8-7bc2d73c2b76', '薛侍御處乞鞾', '薛侍御处乞鞾', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["越客南來誇桂麖，良工用意巧縫成。","看時共說茱萸皺，著處嫌無鸜鵒鳴。","百里奚身悲甚似，五羊皮價敢全輕。","日於文苑陪高步，贏得芳塵接武名。"]', '["越客南来誇桂麖，良工用意巧縫成。","看时共说茱萸皺，著处嫌無鸜鵒鳴。","百里奚身悲甚似，五羊皮價敢全轻。","日於文苑陪高步，贏得芳塵接武名。"]', '诗', 'shi', '', NULL, '薛侍御處乞鞾 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab6830c-bf2b-4d08-b8a4-df3c701b7ace', '九子坡聞鷓鴣', '九子坡闻鷓鴣', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["落照蒼茫秋草明，鷓鴣啼處遠人行。","正穿詰曲崎嶇路，更聽鉤輈格磔聲。","曾泊桂江深岸雨，亦于梅嶺阻歸程。","此時爲爾腸千斷，乞放今宵白髮生。"]', '["落照蒼茫秋草明，鷓鴣啼处远人行。","正穿詰曲崎嶇路，更听鉤輈格磔声。","曾泊桂江深岸雨，亦于梅嶺阻归程。","此时爲爾腸千斷，乞放今宵白髮生。"]', '诗', 'shi', '', NULL, '九子坡聞鷓鴣 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85081336-b211-4f05-87b8-eb4e587d8195', '涼公從叔春祭廣利王廟', '涼公從叔春祭廣利王廟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["龍驤伐鼓下長川，直濟雲濤古廟前。","海客斂威驚火斾，天吳收浪避樓船。","陰靈向作南溟主，祀典高齊五岳肩。","從此華夷封域靜，潛熏玉燭奉堯年。"]', '["龙驤伐鼓下长川，直濟云濤古廟前。","海客斂威驚火斾，天吳收浪避楼船。","陰靈向作南溟主，祀典高齊五岳肩。","從此华夷封域静，潛熏玉燭奉堯年。"]', '诗', 'shi', '', NULL, '涼公從叔春祭廣利王廟 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c95f671-62cc-4228-8270-91bdfb3dab51', '長沙紫極宮雨夜愁坐', '长沙紫極宮雨夜愁坐', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["獨坐高齋寒擁衾，洞宮臺殿窅沈沈。","春燈含思靜相伴，夜雨滴愁更向深。","窮達未知他日事，是非皆到此時心。","羈棲摧剪平生志，抱膝時爲梁甫吟。"]', '["独坐高斋寒擁衾，洞宮台殿窅沈沈。","春灯含思静相伴，夜雨滴愁更向深。","窮達未知他日事，是非皆到此时心。","羈棲摧剪平生志，抱膝时爲梁甫吟。"]', '诗', 'shi', '', NULL, '長沙紫極宮雨夜愁坐 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d381b2a7-e535-41b8-8f2b-4aa347d117d8', '送人隱居', '送人隐居', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["碁局茅亭幽澗濱，竹寒江靜遠無人。","邨梅尚斂風前笑，沙草初偷雪後春。","鵬鷃喻中消日月，滄浪歌裏放心神。","平生自有煙霞志，久欲拋身狎隱淪。"]', '["碁局茅亭幽澗濱，竹寒江静远無人。","邨梅尚斂风前笑，沙草初偷雪後春。","鵬鷃喻中消日月，滄浪歌裏放心神。","平生自有煙霞志，久欲拋身狎隐淪。"]', '诗', 'shi', '', NULL, '送人隱居 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c42c4dd8-02da-4a33-802f-782409305b07', '江樓閑望懷關中親故', '江楼闲望懷关中親故', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["搖落江天欲盡秋，遠鴻高送一行愁。","音書寂絕秦雲外，身世蹉跎楚水頭。","年貌暗隨黃葉去，時情深付碧波流。","風淒日冷江湖晚，駐目寒空獨倚樓。"]', '["搖落江天欲尽秋，远鴻高送一行愁。","音书寂絕秦云外，身世蹉跎楚水头。","年貌暗隨黄葉去，时情深付碧波流。","风淒日冷江湖晚，駐目寒空独倚楼。"]', '诗', 'shi', '', NULL, '江樓閑望懷關中親故 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0335e1e-2432-4cf3-aff3-840c87f92ec5', '請告南歸留別同館', '請告南归留別同館', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一點燈前獨坐身，西風初動帝城砧。","不勝庾信鄉關思，遂作陶潛歸去吟。","書閤乍離情黯黯，彤庭迴望肅沈沈。","應憐一別瀛洲侶，萬里單飛雲外深。"]', '["一点灯前独坐身，西风初动帝城砧。","不勝庾信乡关思，遂作陶潛归去吟。","书閤乍離情黯黯，彤庭迴望肅沈沈。","應怜一別瀛洲侶，万里單飞云外深。"]', '诗', 'shi', '', NULL, '請告南歸留別同館 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('586988ec-0168-499f-8610-1238deeceae0', '仙明洲口號', '仙明洲口號', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["長愛沙洲水竹居，暮江春樹綠陰初。","浪翻新月金波淺，風損輕雲玉葉疎。","半浦夜歌聞盪槳，一星幽火照叉魚。","二年此處尋佳句，景物常輸楚客書。"]', '["长愛沙洲水竹居，暮江春樹綠陰初。","浪翻新月金波淺，风損轻云玉葉疎。","半浦夜歌闻盪槳，一星幽火照叉鱼。","二年此处尋佳句，景物常輸楚客书。"]', '诗', 'shi', '', NULL, '仙明洲口號 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e664e78a-8709-4823-9ddc-0a8b3e7a7be9', '送蕭十二校書赴郢州婚姻', '送蕭十二校书赴郢州婚姻', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["蓬萊才子即蕭郎，綵服青書卜鳳皇。","玉珮定催紅粉色，錦衾應惹翠雲香。","馬穿暮雨荆山遠，人宿寒燈郢夢長。","領取和鳴好風景，石城花月送歸鄉。"]', '["蓬萊才子即蕭郎，綵服青书卜鳳皇。","玉珮定催紅粉色，錦衾應惹翠云香。","马穿暮雨荆山远，人宿寒灯郢梦长。","領取和鳴好风景，石城花月送归乡。"]', '诗', 'shi', '', NULL, '送蕭十二校書赴郢州婚姻 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24853263-11cd-4422-8da7-15c2f5ae654c', '送隱者歸羅浮', '送隐者归羅浮', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["春山杳杳日遲遲，路入雲峰白犬隨。","兩卷素書留貰酒，一柯樵斧坐看棋。","蓬萊道士飛霞履，清遠仙人寄好詩。","自此塵寰音信斷，山川風月永相思。"]', '["春山杳杳日遲遲，路入云峰白犬隨。","兩卷素书留貰酒，一柯樵斧坐看棋。","蓬萊道士飞霞履，清远仙人寄好诗。","自此塵寰音信斷，山川风月永相思。"]', '诗', 'shi', '', NULL, '送隱者歸羅浮 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58191d6-06f3-458e-8af5-3b54a2e4b24b', '獻王中丞', '獻王中丞', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["登仙望絕李膺舟，從此青蠅點遂稠。","半夜劒吹牛斗動，二年門掩雀羅愁。","張儀會展平生舌，韓信那慙跨下羞。","他日圖勳畫麟閣，定呈肝膽始應休。"]', '["登仙望絕李膺舟，從此青蠅点遂稠。","半夜劒吹牛斗动，二年门掩雀羅愁。","張儀會展平生舌，韓信那慙跨下羞。","他日圖勳畫麟閣，定呈肝膽始應休。"]', '诗', 'shi', '', NULL, '獻王中丞 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5720833-8fbe-4f86-aef3-d0236052cbed', '哭小女癡兒', '哭小女癡兒', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["平生未省夢熊羆，稚女如花墜曉枝。","條蔓縱橫輸葛藟，子孫蕃育羨螽斯。","方同王衍鍾情切，猶念商瞿有慶遲。","負爾五年恩愛淚，眼中惟有涸泉知。"]', '["平生未省梦熊羆，稚女如花墜晓枝。","條蔓縱橫輸葛藟，子孫蕃育羨螽斯。","方同王衍鍾情切，猶念商瞿有慶遲。","負爾五年恩愛泪，眼中惟有涸泉知。"]', '诗', 'shi', '', NULL, '哭小女癡兒 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bcd69a1-0bb5-4eb6-893a-2ae159b546e3', '醉後贈馮姬', '醉後贈馮姬', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["黃昏歌舞促瓊筵，銀燭臺西見小蓮。","二寸橫波回慢水，一雙纖手語香弦。","桂形淺拂梁家黛，瓜字初分碧玉年。","願託襄王雲雨夢，陽臺今夜降神仙。"]', '["黄昏歌舞促瓊筵，銀燭台西见小蓮。","二寸橫波回慢水，一雙纖手語香弦。","桂形淺拂梁家黛，瓜字初分碧玉年。","願託襄王云雨梦，陽台今夜降神仙。"]', '诗', 'shi', '', NULL, '醉後贈馮姬 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02188e9-d326-4874-bde7-a6536567cef0', '廣州陪涼公從叔越臺讌集', '廣州陪涼公從叔越台讌集', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一逕松梢踏石梯，步窮身在白雲西。","日銜赤浪金車沒，天拂滄波翠幕低。","高鳥散飛驚大斾，長風萬里卷秋鼙。","玉鉤挂海笙歌合，珠履三千半似泥。"]', '["一逕松梢踏石梯，步窮身在白云西。","日銜赤浪金车沒，天拂滄波翠幕低。","高鸟散飞驚大斾，长风万里卷秋鼙。","玉鉤挂海笙歌合，珠履三千半似泥。"]', '诗', 'shi', '', NULL, '廣州陪涼公從叔越臺讌集 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c23ad6d-3bc7-4655-be03-70cd7a85ce7f', '留別馬使君', '留別马使君', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["俱來海上歎煙波，君佩銀魚我觸羅。","蜀國才微甘放蕩，專城年少豈蹉跎。","應憐旅夢千重思，共愴離心一曲歌。","唯有管弦知客意，分明吹出感恩多。"]', '["俱来海上歎煙波，君佩銀鱼我觸羅。","蜀国才微甘放蕩，專城年少豈蹉跎。","應怜旅梦千重思，共愴離心一曲歌。","唯有管弦知客意，分明吹出感恩多。"]', '诗', 'shi', '', NULL, '留別馬使君 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8325578-f3f1-43dc-9474-c3eb3fcbfdda', '將欲南行陪崔八讌海榴亭', '將欲南行陪崔八讌海榴亭', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["朝讌華堂暮未休，幾人偏得謝公留。","風傳鼓角霜侵戟，雲卷笙歌月上樓。","賓館盡開徐孺榻，客帆空戀李膺舟。","謾誇書劒無歸處，水遠山長步步愁。"]', '["朝讌华堂暮未休，幾人偏得謝公留。","风傳鼓角霜侵戟，云卷笙歌月上楼。","賓館尽开徐孺榻，客帆空戀李膺舟。","謾誇书劒無归处，水远山长步步愁。"]', '诗', 'shi', '', NULL, '將欲南行陪崔八讌海榴亭 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('710bdbb7-6c31-4d84-9e80-81fd5aad669f', '湖寺清明夜遣懷', '湖寺清明夜遣懷', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["柳暗花香愁不眠，獨凭危檻思淒然。","野雲將雨渡微月，沙鳥帶聲飛遠天。","久向飢寒拋弟妹，每因時節憶團圓。"]', '["柳暗花香愁不眠，独凭危檻思淒然。","野云將雨渡微月，沙鸟带声飞远天。","久向飢寒拋弟妹，每因时節憶團圓。"]', '诗', 'shi', '', NULL, '湖寺清明夜遣懷 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fcff4ed-d5ca-4906-aa85-6981b77860c6', '九日', '九日', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["年年羞見菊花開，十度悲秋上楚臺。","半嶺殘陽銜樹落，一行斜雁向人來。","行雲永絕襄王夢，野水偏傷宋玉懷。","絲管闌珊歸客盡，黃昏獨自詠詩迴。"]', '["年年羞见菊花开，十度悲秋上楚台。","半嶺殘陽銜樹落，一行斜雁向人来。","行云永絕襄王梦，野水偏傷宋玉懷。","絲管闌珊归客尽，黄昏独自詠诗迴。"]', '诗', 'shi', '', NULL, '九日 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b508aa7e-f960-4c3f-90b5-0bcacc4ef81b', '同鄭相幷歌姬小飲戲贈', '同鄭相幷歌姬小饮戲贈', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["裙拖六幅湘江水，鬢聳巫山一段雲。","風格只應天上有，歌聲豈合世間聞。","胸前瑞雪燈斜照，眼底桃花酒半醺。","不是相如憐賦客，爭敎容易見文君。"]', '["裙拖六幅湘江水，鬢聳巫山一段云。","风格只應天上有，歌声豈合世间闻。","胸前瑞雪灯斜照，眼底桃花酒半醺。","不是相如怜賦客，爭敎容易见文君。"]', '诗', 'shi', '', NULL, '同鄭相幷歌姬小飲戲贈 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4c7d3f-486d-4cce-9228-52190da0fa68', '秣陵懷古', '秣陵懷古', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["野花黃葉舊吳宮，六代豪華燭散風。","龍虎勢衰佳氣歇，鳳皇名在故臺空。","市朝遷變秋蕪綠，墳塚高低落照紅。","霸業鼎圖人去盡，獨來惆悵水雲中。"]', '["野花黄葉旧吳宮，六代豪华燭散风。","龙虎勢衰佳氣歇，鳳皇名在故台空。","市朝遷变秋蕪綠，墳塚高低落照紅。","霸業鼎圖人去尽，独来惆悵水云中。"]', '诗', 'shi', '', NULL, '秣陵懷古 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae649af7-5266-4dbf-8cf9-3625b2a3711d', '黃陵廟', '黄陵廟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["小姑洲北浦雲邊，二女容華自儼然。","野廟向江春寂寂，古碑無字草芊芊。","風迴日暮吹芳芷，月落山深哭杜鵑。","猶似含顰望巡狩，九疑愁斷隔湘川。"]', '["小姑洲北浦云邊，二女容华自儼然。","野廟向江春寂寂，古碑無字草芊芊。","风迴日暮吹芳芷，月落山深哭杜鵑。","猶似含顰望巡狩，九疑愁斷隔湘川。"]', '诗', 'shi', '', NULL, '黃陵廟 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da9b1ce-a15f-407d-9d3b-3787b771d1ea', '送唐侍御福建省兄', '送唐侍御福建省兄', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["桂枝攀盡賈家才，霄漢春風棣萼開。","世掌綸言傳大筆，官分鴻序壓霜臺。","閩山翠卉迎飛斾，越水清紋散落梅。","到日池塘春草綠，謝公應夢惠連來。"]', '["桂枝攀尽賈家才，霄漢春风棣萼开。","世掌綸言傳大笔，官分鴻序壓霜台。","閩山翠卉迎飞斾，越水清紋散落梅。","到日池塘春草綠，謝公應梦惠連来。"]', '诗', 'shi', '', NULL, '送唐侍御福建省兄 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd937294-eecd-48b6-8227-5b08a6cd7e26', '送秦鍊師歸岑公山', '送秦鍊師归岑公山', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["紫泥飛詔下金鑾，列象分明世仰觀。","北省諫書藏舊草，南宮郎署握新蘭。","春歸鳳沼恩波暖，曉入鴛行瑞氣寒。","偏是此生棲息者，滿衣零淚一時乾。"]', '["紫泥飞詔下金鑾，列象分明世仰观。","北省諫书藏旧草，南宮郎署握新蘭。","春归鳳沼恩波暖，晓入鴛行瑞氣寒。","偏是此生棲息者，满衣零泪一时乾。"]', '诗', 'shi', '', NULL, '送秦鍊師歸岑公山 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4baf12f7-1ea4-4604-a08d-11fd7d2839cc', '潯陽觀水', '潯陽观水', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["朝宗漢水接陽臺，唅呀填坑吼作雷。","莫見九江平穩去，還從三峽嶮巇來。","南經夢澤寬浮日，西出岷山劣泛盃。","直至滄溟涵貯盡，深沈不動浸昭回。"]', '["朝宗漢水接陽台，唅呀填坑吼作雷。","莫见九江平穩去，還從三峽嶮巇来。","南經梦澤寬浮日，西出岷山劣泛盃。","直至滄溟涵貯尽，深沈不动浸昭回。"]', '诗', 'shi', '', NULL, '潯陽觀水 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a222a87-220e-4be0-881b-dd2695fcba14', '謫仙吟贈趙道士', '謫仙吟贈趙道士', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["汗漫東遊黃鶴雛，縉雲仙子住清都。","三元麟鳳推高座，六甲風雷閟小壺。","日月暗資靈壽藥，山河直擬化生符。","若爲失意居蓬島，鼇足塵飛桑樹枯。"]', '["汗漫东游黄鹤雛，縉云仙子住清都。","三元麟鳳推高座，六甲风雷閟小壺。","日月暗資靈壽藥，山河直擬化生符。","若爲失意居蓬島，鼇足塵飞桑樹枯。"]', '诗', 'shi', '', NULL, '謫仙吟贈趙道士 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6824739f-7e79-4d97-a371-8f29efe5b481', '長沙陪裴大夫夜讌', '长沙陪裴大夫夜讌', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["東山夜讌酒成河，銀燭熒煌照綺羅。","四面雨聲籠笑語，滿堂香氣泛笙歌。","泠泠玉漏初三滴，灩灩金觴已半酡。","共向柏臺窺雅量，澄陂萬頃見天和。"]', '["东山夜讌酒成河，銀燭熒煌照綺羅。","四面雨声籠笑語，满堂香氣泛笙歌。","泠泠玉漏初三滴，灩灩金觴已半酡。","共向柏台窺雅量，澄陂万頃见天和。"]', '诗', 'shi', '', NULL, '長沙陪裴大夫夜讌 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c87eb3-db03-4964-a90e-409d03f19031', '寶劍', '寶劍', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["雷煥豐城掘劍池，年深事遠跡依稀。","泥沙難掩衝天氣，風雨終思發匣時。","夜電尚搖池底影，秋蓮空吐鍔邊輝。","自從星坼中台後，化作雙龍去不歸。"]', '["雷煥豐城掘劍池，年深事远跡依稀。","泥沙难掩衝天氣，风雨終思發匣时。","夜電尚搖池底影，秋蓮空吐鍔邊輝。","自從星坼中台後，化作雙龙去不归。"]', '诗', 'shi', '', NULL, '寶劍 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7411d647-6070-4373-a7fb-2939d83d830e', '人日梅花病中作', '人日梅花病中作', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["去年今日湘南寺，獨把寒梅愁斷腸。","今年此日江邊宅，臥見瓊枝低壓墻。","半落半開臨野岸，團情團思醉韶光。","玉鱗寂寂飛斜月，素豔亭亭對夕陽。","已被兒童苦攀折，更遭風雨損馨香。","洛陽桃李漸撩亂，回首行宮春景長。"]', '["去年今日湘南寺，独把寒梅愁斷腸。","今年此日江邊宅，臥见瓊枝低壓墻。","半落半开臨野岸，團情團思醉韶光。","玉鱗寂寂飞斜月，素豔亭亭对夕陽。","已被兒童苦攀折，更遭风雨損馨香。","洛陽桃李漸撩亂，回首行宮春景长。"]', '诗', 'shi', '', NULL, '人日梅花病中作 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('739004c3-d104-42d6-8880-df4b1e06846f', '靜夜相思', '静夜相思', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["山空天籟寂，水榭延輕涼。","浪定一浦月，藕花閑自香。"]', '["山空天籟寂，水榭延轻涼。","浪定一浦月，藕花闲自香。"]', '诗', 'shi', '', NULL, '靜夜相思 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5d16486-05b0-4e9b-8720-278020308c16', '桂州經佳人故居', '桂州經佳人故居', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["桂水依舊綠，佳人本不還。","秖應隨暮雨，飛入九疑山。"]', '["桂水依旧綠，佳人本不還。","秖應隨暮雨，飞入九疑山。"]', '诗', 'shi', '', NULL, '桂州經佳人故居 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9913da-8d22-4c4c-960a-f7aaad7b5876', '放魚', '放鱼', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["早覓爲龍去，江湖莫漫遊。","須知香餌下，觸口是銛鉤。"]', '["早覓爲龙去，江湖莫漫游。","須知香餌下，觸口是銛鉤。"]', '诗', 'shi', '', NULL, '放魚 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72cbfe88-6a41-4893-b31a-7c10562da7cb', '蓮葉', '蓮葉', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["根是泥中玉，心承露下珠。","在君塘下種，埋沒任春蒲。"]', '["根是泥中玉，心承露下珠。","在君塘下種，埋沒任春蒲。"]', '诗', 'shi', '', NULL, '蓮葉 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d99fa5d6-52e1-4439-a71b-0996478b330d', '客愁二首 一', '客愁二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["客愁看柳色，日日逐春深。","蕩漾春風起，誰知歷亂心。"]', '["客愁看柳色，日日逐春深。","蕩漾春风起，誰知歷亂心。"]', '诗', 'shi', '', NULL, '客愁二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f3599b-d26e-4302-acfd-9207b1cbdd14', '客愁二首 二', '客愁二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["客愁看柳色，日日逐春長。","憑送湘流水，綿綿入帝鄉。"]', '["客愁看柳色，日日逐春长。","憑送湘流水，綿綿入帝乡。"]', '诗', 'shi', '', NULL, '客愁二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b1b9de-b8e3-4496-8df0-15d420a79b14', '洞庭乾二首 一', '洞庭乾二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["借問蓬萊水，誰逢清淺年。","傷心雲夢澤，歲歲作桑田。"]', '["借问蓬萊水，誰逢清淺年。","傷心云梦澤，歲歲作桑田。"]', '诗', 'shi', '', NULL, '洞庭乾二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f04d2d4-19e8-4852-b15e-aa22b75cbbd2', '洞庭乾二首 二', '洞庭乾二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["朱宮紫貝闕，一旦作沙洲。","八月還平在，魚蝦不用愁。"]', '["朱宮紫貝闕，一旦作沙洲。","八月還平在，鱼蝦不用愁。"]', '诗', 'shi', '', NULL, '洞庭乾二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac15f80b-4920-42b5-a2c3-75b3b5f151ac', '病起別主人', '病起別主人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["益媿千金少，情將一飯殊。","恨無泉客淚，盡泣感恩珠。"]', '["益媿千金少，情將一飯殊。","恨無泉客泪，尽泣感恩珠。"]', '诗', 'shi', '', NULL, '病起別主人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7afa4e-f2b4-4640-9508-a6047cd9722a', '火爐前坐', '火爐前坐', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["孤燈照不寐，風雨滿西林。","多少關心事，書灰到夜深。"]', '["孤灯照不寐，风雨满西林。","多少关心事，书灰到夜深。"]', '诗', 'shi', '', NULL, '火爐前坐 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10a04c72-d56f-49cf-93c6-0e2c12bb1889', '古詞', '古词', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一合相思淚，臨江灑素秋。","碧波如會意，却與向西流。"]', '["一合相思泪，臨江灑素秋。","碧波如會意，却與向西流。"]', '诗', 'shi', '', NULL, '古詞 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5214178-272b-46ae-8be6-ffc3d97a4b7d', '嘲賣藥翁', '嘲賣藥翁', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["斸盡春山土，辛勤賣藥翁。","莫拋破笠子，留作敗天公。"]', '["斸尽春山土，辛勤賣藥翁。","莫拋破笠子，留作敗天公。"]', '诗', 'shi', '', NULL, '嘲賣藥翁 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e385e12e-2e03-4a79-aa76-9d5e2f11d87d', '傷小女癡兒', '傷小女癡兒', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["哭爾春日短，支頤長歎嗟。","不如半死樹，猶吐一枝花。"]', '["哭爾春日短，支頤长歎嗟。","不如半死樹，猶吐一枝花。"]', '诗', 'shi', '', NULL, '傷小女癡兒 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b87bce-9f05-43e0-8d63-acd775ee20b7', '青鷁', '青鷁', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["獨立蒹葭雨，低飛浦嶼風。","須知毛色下，莫入鷺鷥叢。"]', '["独立蒹葭雨，低飞浦嶼风。","須知毛色下，莫入鷺鷥叢。"]', '诗', 'shi', '', NULL, '青鷁 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee747055-e56d-4714-be0e-6331269f8b19', '池塘晚景', '池塘晚景', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["風荷珠露傾，驚起睡鵁鶄。","月落池塘靜，金刀剪一聲。"]', '["风荷珠露傾，驚起睡鵁鶄。","月落池塘静，金刀剪一声。"]', '诗', 'shi', '', NULL, '池塘晚景 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fb9b5bd-ed67-462a-aede-f214dc819589', '投從叔', '投從叔', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["可惜出羣蹄，毛焦久臥泥。","孫陽如不顧，騏驥向誰嘶。"]', '["可惜出羣蹄，毛焦久臥泥。","孫陽如不顧，騏驥向誰嘶。"]', '诗', 'shi', '', NULL, '投從叔 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0771d642-80c9-4362-9bf3-e59cd9324ea0', '惱自澄', '惱自澄', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["常聞天女會，玉指散天花。","莫遣春風裏，紅芳點袈裟。"]', '["常闻天女會，玉指散天花。","莫遣春风裏，紅芳点袈裟。"]', '诗', 'shi', '', NULL, '惱自澄 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2d3b1a-46ce-498c-a63d-7fd672448a5b', '讀賈誼傳', '读賈誼傳', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["卑濕長沙地，空拋出世才。","已齊生死理，服鳥莫爲災。"]', '["卑濕长沙地，空拋出世才。","已齊生死理，服鸟莫爲災。"]', '诗', 'shi', '', NULL, '讀賈誼傳 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f57ac36-5458-49cc-8d9d-f1597e0c7f37', '寄人', '寄人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["寄語雙蓮子，須知用意深。","莫嫌一點苦，便擬棄蓮心。"]', '["寄語雙蓮子，須知用意深。","莫嫌一点苦，便擬棄蓮心。"]', '诗', 'shi', '', NULL, '寄人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c1fba5-be51-4ef5-949a-c1712bd712be', '寄韋秀才', '寄韋秀才', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["荆臺蘭渚客，寥落共含情。","空館相思夜，孤燈照雨聲。"]', '["荆台蘭渚客，寥落共含情。","空館相思夜，孤灯照雨声。"]', '诗', 'shi', '', NULL, '寄韋秀才 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('766708a2-fc55-49f3-8cc5-9f8ef730b74a', '春日寄友', '春日寄友', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["晴氣熏櫻蘂，丰濛雪滿林。","請君三斗酒，醉臥白羅岑。"]', '["晴氣熏櫻蘂，丰濛雪满林。","請君三斗酒，醉臥白羅岑。"]', '诗', 'shi', '', NULL, '春日寄友 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa3fdac-02c3-4b6f-8718-a400e27cbe7c', '題竹', '題竹', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一頃含秋綠，森風十萬竿。","氣吹朱夏轉，聲掃碧霄寒。"]', '["一頃含秋綠，森风十万竿。","氣吹朱夏轉，声掃碧霄寒。"]', '诗', 'shi', '', NULL, '題竹 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0936193-9114-4045-96e0-08db30333b89', '懷初公', '懷初公', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["不見休上人，空傷碧雲思。","何處開寶書，秋風海光寺。"]', '["不见休上人，空傷碧云思。","何处开寶书，秋风海光寺。"]', '诗', 'shi', '', NULL, '懷初公 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28bb464f-138f-4a2f-a9cf-880500a87b8f', '龍安寺佳人阿最歌八首 一', '龙安寺佳人阿最歌八首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["團團明月面，冉冉柳枝腰。","未入鴛鴦被，心長似火燒。"]', '["團團明月面，冉冉柳枝腰。","未入鴛鴦被，心长似火燒。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bca7f346-2676-471e-8cbf-54ebd1e5bc69', '龍安寺佳人阿最歌八首 二', '龙安寺佳人阿最歌八首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["見面知何益，聞名憶轉深。","拳攣荷葉子，未得展蓮心。"]', '["见面知何益，闻名憶轉深。","拳攣荷葉子，未得展蓮心。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d870d6a-5c6d-4d69-8d2f-2185d27d7823', '龍安寺佳人阿最歌八首 三', '龙安寺佳人阿最歌八首 三', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["欲摘不得摘，如看波上花。","若敎親玉樹，情願作蒹葭。"]', '["欲摘不得摘，如看波上花。","若敎親玉樹，情願作蒹葭。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 三 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d0e691d-fa6a-405d-97b3-b2df98d97781', '龍安寺佳人阿最歌八首 四', '龙安寺佳人阿最歌八首 四', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["門路穿茶焙，房門映竹煙。","會須隨鹿女，乞火到窗前。"]', '["门路穿茶焙，房门映竹煙。","會須隨鹿女，乞火到窗前。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 四 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fa773e5-b506-488f-9af3-a44fa661548e', '龍安寺佳人阿最歌八首 五', '龙安寺佳人阿最歌八首 五', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["不是求心印，都緣愛綠珠。","何須同泰寺，然後始爲奴。"]', '["不是求心印，都緣愛綠珠。","何須同泰寺，然後始爲奴。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 五 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fb103e2-ffc8-46cf-abce-7c01b1914995', '龍安寺佳人阿最歌八首 六', '龙安寺佳人阿最歌八首 六', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["既爲金界客，任改淨人名。","願掃琉璃地，燒香過一生。"]', '["既爲金界客，任改淨人名。","願掃琉璃地，燒香過一生。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 六 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5af8d80-5f6d-4102-af34-a2a35c04a4d7', '龍安寺佳人阿最歌八首 七', '龙安寺佳人阿最歌八首 七', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["素腕撩金索，輕紅約翠紗。","不如欄下水，終日見桃花。"]', '["素腕撩金索，轻紅約翠紗。","不如欄下水，終日见桃花。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 七 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f17d75-b14d-4add-9665-f131f3b92360', '龍安寺佳人阿最歌八首 八', '龙安寺佳人阿最歌八首 八', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["第一龍宮女，相憐是阿誰。","好魚輸獺盡，白鷺鎮長飢。"]', '["第一龙宮女，相怜是阿誰。","好鱼輸獺尽，白鷺鎮长飢。"]', '诗', 'shi', '', NULL, '龍安寺佳人阿最歌八首 八 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1e68a1e-2c93-44d9-bad8-bdc890570384', '野鴨', '野鴨', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["鸂鶒借毛衣，喧呼鷹隼稀。","雲披菱藻地，任汝作羣飛。"]', '["鸂鶒借毛衣，喧呼鷹隼稀。","云披菱藻地，任汝作羣飞。"]', '诗', 'shi', '', NULL, '野鴨 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44eedc5c-b0c5-4759-a3d4-58fa27af680c', '題二妃廟', '題二妃廟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["黃陵廟前春已空，子規啼血滴松風。","不知精爽歸何處，疑是行雲秋色中。"]', '["黄陵廟前春已空，子規啼血滴松风。","不知精爽归何处，疑是行云秋色中。"]', '诗', 'shi', '', NULL, '題二妃廟 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adbaedb4-8f65-468c-9547-4bfa518e00ab', '寄友二首 一', '寄友二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["野水晴山雪後時，獨行邨落更相思。","無因一向溪頭醉，處處寒梅映酒旗。"]', '["野水晴山雪後时，独行邨落更相思。","無因一向溪头醉，处处寒梅映酒旗。"]', '诗', 'shi', '', NULL, '寄友二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fea210a9-5e66-40e3-bbe4-8f9ad61ecad9', '寄友二首 二', '寄友二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["花落輕寒酒熟遲，醉眠不及落花期。","愁人相憶春山暮，煙樹蒼蒼播穀時。"]', '["花落轻寒酒熟遲，醉眠不及落花期。","愁人相憶春山暮，煙樹蒼蒼播穀时。"]', '诗', 'shi', '', NULL, '寄友二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cead8470-e404-4ef4-83b3-363b5a09d97d', '桃源', '桃源', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["我到瞿真上升處，山川四望使人愁。","紫雲白鶴去不返，唯有桃花溪水流。"]', '["我到瞿真上升处，山川四望使人愁。","紫云白鹤去不返，唯有桃花溪水流。"]', '诗', 'shi', '', NULL, '桃源 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8d0264-c581-4c1e-a36a-1b400f2c8b96', '題王侍御宅', '題王侍御宅', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["門向滄江碧岫開，地多鷗鷺少塵埃。","綠陰十里灘聲裏，閑自王家看竹來。"]', '["门向滄江碧岫开，地多鷗鷺少塵埃。","綠陰十里灘声裏，闲自王家看竹来。"]', '诗', 'shi', '', NULL, '題王侍御宅 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f789edfc-d0c8-4fc6-8ce2-303634a41b2b', '聞湘南從叔朝覲', '闻湘南從叔朝覲', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["長沙地窄卻回時，舟檝駸駸向鳳池。","爲報湘川神女道，莫敎雲雨濕旌旗。"]', '["长沙地窄卻回时，舟檝駸駸向鳳池。","爲報湘川神女道，莫敎云雨濕旌旗。"]', '诗', 'shi', '', NULL, '聞湘南從叔朝覲 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4d3006b-209d-4b08-81ab-6b0d1fe78356', '漢陽太白樓', '漢陽太白楼', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["江上層樓翠靄間，滿簾春水滿窗山。","青楓綠草將愁去，遠入吳雲暝不還。"]', '["江上層楼翠靄间，满簾春水满窗山。","青楓綠草將愁去，远入吳云暝不還。"]', '诗', 'shi', '', NULL, '漢陽太白樓 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19e1d2fe-25f0-468c-a99d-3676b0e85b7b', '送客', '送客', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["沅水羅文海燕回，柳條牽恨到荆臺。","定知行路春愁裏，故郢城邊見落梅。"]', '["沅水羅文海燕回，柳條牽恨到荆台。","定知行路春愁裏，故郢城邊见落梅。"]', '诗', 'shi', '', NULL, '送客 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c617ef23-009a-4afd-93af-9cfb04a308bc', '醴陵道中', '醴陵道中', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["別酒離亭十里強，半醒半醉引愁長。","無端寂寂春山路，雪打溪梅狼籍香。"]', '["別酒離亭十里強，半醒半醉引愁长。","無端寂寂春山路，雪打溪梅狼籍香。"]', '诗', 'shi', '', NULL, '醴陵道中 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ba6e44a-1e34-4636-96c2-7811995f33c8', '校書叔遺暑服', '校书叔遺暑服', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["翠雲箱裏疊樬櫳，楚葛湘紗淨似空。","便著清江明月夜，輕涼與挂一身風。"]', '["翠云箱裏叠樬櫳，楚葛湘紗淨似空。","便著清江明月夜，轻涼與挂一身风。"]', '诗', 'shi', '', NULL, '校書叔遺暑服 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20e051b4-1ebd-4c23-9226-bac05ccee90e', '贈魏三十七', '贈魏三十七', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["名珪字玉淨無瑕，美譽芳聲有數車。","莫放燄光高二丈，來年燒殺杏園花。"]', '["名珪字玉淨無瑕，美譽芳声有數车。","莫放燄光高二丈，来年燒殺杏园花。"]', '诗', 'shi', '', NULL, '贈魏三十七 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f95f327-10e9-4f8a-ac97-6f7868c8601f', '酬崔表仁', '酬崔表仁', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["昨日朱門一見君，忽驚野鶴在雞羣。","不應長啄潢汙水，早晚歸飛碧落雲。"]', '["昨日朱门一见君，忽驚野鹤在雞羣。","不應长啄潢汙水，早晚归飞碧落云。"]', '诗', 'shi', '', NULL, '酬崔表仁 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ad3fcce-ea41-4de7-a39c-848854da14d6', '旅遊番禺獻涼公', '旅游番禺獻涼公', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["帝鄉羣侶杳難尋，獨立滄洲歲暮心。","野鶴棲飛無遠近，稻粱多處是恩深。"]', '["帝乡羣侶杳难尋，独立滄洲歲暮心。","野鹤棲飞無远近，稻粱多处是恩深。"]', '诗', 'shi', '', NULL, '旅遊番禺獻涼公 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fbaf59f-700e-4822-881e-8cd84799c8d1', '長沙元門寺張璪員外壁畫', '长沙元门寺張璪員外壁畫', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["片石長松倚素楹，翛然雲壑見高情。","世人只愛凡花鳥，無處不知粱廣名。"]', '["片石长松倚素楹，翛然云壑见高情。","世人只愛凡花鸟，無处不知粱廣名。"]', '诗', 'shi', '', NULL, '長沙元門寺張璪員外壁畫 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71eb3383-2ef5-43d2-ba21-d4bbfbfe3620', '請告出春明門', '請告出春明门', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["本不將心挂名利，亦無情意在樊籠。","鹿裘藜杖且歸去，富貴榮華春夢中。"]', '["本不將心挂名利，亦無情意在樊籠。","鹿裘藜杖且归去，富貴榮华春梦中。"]', '诗', 'shi', '', NULL, '請告出春明門 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd371c68-602b-407d-a2c7-5b37fae56154', '引水行', '引水行', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一條寒玉走秋泉，引出深蘿洞口煙。","十里暗流聲不斷，行人頭上過潺湲。"]', '["一條寒玉走秋泉，引出深蘿洞口煙。","十里暗流声不斷，行人头上過潺湲。"]', '诗', 'shi', '', NULL, '引水行 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c82d131-12c4-4604-b378-6feab351b8e2', '移松竹', '移松竹', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["龍髯鳳尾亂颼颼，帶霧停風一畝秋。","待取滿庭蒼翠合，酒尊書案閉門休。"]', '["龙髯鳳尾亂颼颼，带霧停风一畝秋。","待取满庭蒼翠合，酒尊书案閉门休。"]', '诗', 'shi', '', NULL, '移松竹 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15b06bcc-0dc9-4f30-a0eb-3992ad4cecd0', '歎靈鷲寺山榴', '歎靈鷲寺山榴', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["水蝶巖蜂俱不知，露紅凝豔數千枝。","山深春晚無人賞，即是杜鵑催落時。"]', '["水蝶巖蜂俱不知，露紅凝豔數千枝。","山深春晚無人賞，即是杜鵑催落时。"]', '诗', 'shi', '', NULL, '歎靈鷲寺山榴 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f8db1a7-d933-409f-ac8e-9fc07e7f6d5b', '黃陵廟', '黄陵廟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["黃陵廟前莎草春，黃陵女兒茜裙新。","輕舟短櫂唱歌去，水遠山長愁殺人。"]', '["黄陵廟前莎草春，黄陵女兒茜裙新。","轻舟短櫂唱歌去，水远山长愁殺人。"]', '诗', 'shi', '', NULL, '黃陵廟 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a327cc3-eb54-4300-adfe-6b6c664489cc', '北亭', '北亭', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["斜雨飛絲織曉空，疎簾半捲野亭風。","荷花向盡秋光晚，零落殘紅綠沼中。"]', '["斜雨飞絲织晓空，疎簾半捲野亭风。","荷花向尽秋光晚，零落殘紅綠沼中。"]', '诗', 'shi', '', NULL, '北亭 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6f5cd60-4486-44bf-b0ec-0ae09e3eb7cd', '送客往涔陽', '送客往涔陽', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["春與春愁逐日長，遠人天畔遠思鄉。","蘋生水綠不歸去，孤負東溪七里莊。"]', '["春與春愁逐日长，远人天畔远思乡。","蘋生水綠不归去，孤負东溪七里莊。"]', '诗', 'shi', '', NULL, '送客往涔陽 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93be8f9a-d62b-4ad2-a895-5670f675385f', '寄友人鹿胎冠子', '寄友人鹿胎冠子', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["數點疎星紫錦斑，仙家新樣剪三山。","宜與謝公松下戴，淨簪雲髮翠微間。"]', '["數点疎星紫錦斑，仙家新樣剪三山。","宜與謝公松下戴，淨簪云髮翠微间。"]', '诗', 'shi', '', NULL, '寄友人鹿胎冠子 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e98d6657-827e-4403-992b-4d5b17c7b362', '江南', '江南', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["鱗鱗別浦起微波，汎汎輕舟桃葉歌。","斜雪北風何處宿，江南一路酒旗多。"]', '["鱗鱗別浦起微波，汎汎轻舟桃葉歌。","斜雪北风何处宿，江南一路酒旗多。"]', '诗', 'shi', '', NULL, '江南 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71cd9908-9167-4099-8fef-fe6d27fca4b5', '荅友人寄新茗', '荅友人寄新茗', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["滿火芳香碾麴塵，吳甌湘水綠花新。","媿君千里分滋味，寄與春風酒渴人。"]', '["满火芳香碾麴塵，吳甌湘水綠花新。","媿君千里分滋味，寄與春风酒渴人。"]', '诗', 'shi', '', NULL, '荅友人寄新茗 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a6a9856-5db7-491a-bad0-72b7f7de03f7', '峽山寺上方', '峽山寺上方', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["滿院泉聲水殿涼，疎簾微雨野松香。","東峰下視南溟月，笑踏金波看海光。"]', '["满院泉声水殿涼，疎簾微雨野松香。","东峰下視南溟月，笑踏金波看海光。"]', '诗', 'shi', '', NULL, '峽山寺上方 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66590dab-b8c3-46c6-953a-d48231aa2cb2', '秋登涔陽城二首 一', '秋登涔陽城二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["萬戶砧聲水國秋，涼風吹起故鄉愁。","行人望遠偏傷思，白浪青楓滿北樓。"]', '["万戶砧声水国秋，涼风吹起故乡愁。","行人望远偏傷思，白浪青楓满北楼。"]', '诗', 'shi', '', NULL, '秋登涔陽城二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91fb4be8-7e52-4b8b-b460-d30a1fd6cee4', '秋登涔陽城二首 二', '秋登涔陽城二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["穿針樓上閉秋煙，織女佳期又隔年。","斜笛夜深吹不落，一條銀漢挂秋天。"]', '["穿針楼上閉秋煙，织女佳期又隔年。","斜笛夜深吹不落，一條銀漢挂秋天。"]', '诗', 'shi', '', NULL, '秋登涔陽城二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43e8a053-e8cf-4aed-b7f7-eda7f2c0446a', '釣魚', '釣鱼', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["七尺青竿一丈絲，菰蒲葉裏逐風吹。","幾回舉手拋芳餌，驚起沙灘水鴨兒。"]', '["七尺青竿一丈絲，菰蒲葉裏逐风吹。","幾回舉手拋芳餌，驚起沙灘水鴨兒。"]', '诗', 'shi', '', NULL, '釣魚 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0324f6-8485-43ee-a9fd-aa9bb46041e2', '酬魏三十七', '酬魏三十七', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["靜裏寒香觸思初，開緘忽見二瓊琚。","一吟麗句風流極，沒得弘文李校書。"]', '["静裏寒香觸思初，开緘忽见二瓊琚。","一吟丽句风流極，沒得弘文李校书。"]', '诗', 'shi', '', NULL, '酬魏三十七 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d98bac-41dc-4edb-bb2b-fd144c82113f', '贈琵琶妓', '贈琵琶妓', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["我見鴛鴦飛水上，君還望月苦相思。","一雙裙帶同心結，早寄黃鸝孤鴈兒。"]', '["我见鴛鴦飞水上，君還望月苦相思。","一雙裙带同心結，早寄黄鸝孤鴈兒。"]', '诗', 'shi', '', NULL, '贈琵琶妓 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2c89dbc-ac8b-4545-aa65-33e2fc4bf796', '落帆後賦得二絕 一', '落帆後賦得二絕 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["平湖茫茫春日落，危檣獨映沙洲泊。","上岸閑尋細草行，古查飛起黃金鶚。"]', '["平湖茫茫春日落，危檣独映沙洲泊。","上岸闲尋細草行，古查飞起黄金鶚。"]', '诗', 'shi', '', NULL, '落帆後賦得二絕 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('142e847a-7a85-484c-9c69-463c39a5d73f', '落帆後賦得二絕 二', '落帆後賦得二絕 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["水浮秋煙沙曉雪，皎潔無風燈影徹。","海客雲帆未挂時，相與緣江拾明月。"]', '["水浮秋煙沙晓雪，皎潔無风灯影徹。","海客云帆未挂时，相與緣江拾明月。"]', '诗', 'shi', '', NULL, '落帆後賦得二絕 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01bd5008-9ff6-4ec0-b291-514e41ebfa78', '贈人', '贈人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["曾留宋玉舊衣裳，惹得巫山夢裏香。","雲雨無情難管領，任他別嫁楚襄王。"]', '["曾留宋玉旧衣裳，惹得巫山梦裏香。","云雨無情难管領，任他別嫁楚襄王。"]', '诗', 'shi', '', NULL, '贈人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3c69dc5-24b4-4488-b68f-2f295c1bfd86', '贈妓人', '贈妓人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["誰家少女字千金，省向人間逐處尋。","今日分明花裏見，一雙紅臉動春心。"]', '["誰家少女字千金，省向人间逐处尋。","今日分明花裏见，一雙紅臉动春心。"]', '诗', 'shi', '', NULL, '贈妓人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd0b713-c8e7-4b36-a688-e2142d92a87f', '山榴', '山榴', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["洞中春氣蒙籠暄，尚有紅英千樹繁。","可憐夾水錦步障，羞數石家金谷園。"]', '["洞中春氣蒙籠暄，尚有紅英千樹繁。","可怜夾水錦步障，羞數石家金谷园。"]', '诗', 'shi', '', NULL, '山榴 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f034da2-c0a3-4af9-98e7-5d8b7c4d98bd', '鸂鶒', '鸂鶒', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["錦羽相呼暮沙曲，波上雙聲戛哀玉。","霞明川靜極望中，一時飛滅青山綠。"]', '["錦羽相呼暮沙曲，波上雙声戛哀玉。","霞明川静極望中，一时飞滅青山綠。"]', '诗', 'shi', '', NULL, '鸂鶒 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ce07659-4354-4f69-89f2-848199029944', '沅江漁者', '沅江漁者', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["倚櫂汀洲沙日晚，江鮮野菜桃花飯。","長歌一曲煙靄深，歸去滄江綠波遠。"]', '["倚櫂汀洲沙日晚，江鲜野菜桃花飯。","长歌一曲煙靄深，归去滄江綠波远。"]', '诗', 'shi', '', NULL, '沅江漁者 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67a9178a-a67b-4edc-83c3-37c5448d738f', '題金山寺石堂', '題金山寺石堂', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["白波四面照樓臺，日夜潮聲繞寺迴。","千葉紅蓮高會處，幾曾龍女獻珠來。"]', '["白波四面照楼台，日夜潮声繞寺迴。","千葉紅蓮高會处，幾曾龙女獻珠来。"]', '诗', 'shi', '', NULL, '題金山寺石堂 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e298b27-614e-4719-b3b5-b70312b08e50', '戲贈魏十四', '戲贈魏十四', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["蘭浦秋來煙雨深，幾多情思在琴心。","知君調得東家子，早晚和鳴入錦衾。"]', '["蘭浦秋来煙雨深，幾多情思在琴心。","知君調得东家子，早晚和鳴入錦衾。"]', '诗', 'shi', '', NULL, '戲贈魏十四 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25bdf64d-4da1-4c5d-b5e1-09d32696c14d', '和人贈別', '和人贈別', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["嚬黛低紅別怨多，深亭芳恨滿橫波。","聲中唱出纏綿意，淚落燈前一曲歌。"]', '["嚬黛低紅別怨多，深亭芳恨满橫波。","声中唱出纏綿意，泪落灯前一曲歌。"]', '诗', 'shi', '', NULL, '和人贈別 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9812cb0e-1f4c-42c7-920b-8a8ef58886de', '宿巫山廟二首 一', '宿巫山廟二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["寂寞高堂別楚君，玉人天上逐行雲。","停舟十二峰巒下，幽佩仙香半夜聞。"]', '["寂寞高堂別楚君，玉人天上逐行云。","停舟十二峰巒下，幽佩仙香半夜闻。"]', '诗', 'shi', '', NULL, '宿巫山廟二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48226930-a2ea-4258-9e35-58fb572211cc', '宿巫山廟二首 二', '宿巫山廟二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["廟閉春山曉月光，波聲回合樹蒼蒼。","自從一別襄王夢，雲雨空飛巫峽長。"]', '["廟閉春山晓月光，波声回合樹蒼蒼。","自從一別襄王梦，云雨空飞巫峽长。"]', '诗', 'shi', '', NULL, '宿巫山廟二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05bcfc19-9877-4af9-a4b0-c9e71a3cc113', '傷柘枝妓', '傷柘枝妓', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["曾見雙鸞舞鏡中，聯飛接影對春風。","今來獨在花筵散，月滿秋天一半空。"]', '["曾见雙鸾舞镜中，聯飞接影对春风。","今来独在花筵散，月满秋天一半空。"]', '诗', 'shi', '', NULL, '傷柘枝妓 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('328c78d5-2194-4e01-812d-27150b67ec86', '題櫻桃', '題櫻桃', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["春初攜酒此花間，幾度臨風倒玉山。","今日葉深黃滿樹，再來惆悵不能攀。"]', '["春初携酒此花间，幾度臨风倒玉山。","今日葉深黄满樹，再来惆悵不能攀。"]', '诗', 'shi', '', NULL, '題櫻桃 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f71d2bad-6e33-4834-a772-f194d63a564f', '惱從兄', '惱從兄', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["芳草萋萋新燕飛，芷汀南望鴈書稀。","武陵洞裏尋春客，已被桃花迷不歸。"]', '["芳草萋萋新燕飞，芷汀南望鴈书稀。","武陵洞裏尋春客，已被桃花迷不归。"]', '诗', 'shi', '', NULL, '惱從兄 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('311d2167-ca16-457d-a53f-79e1fe425175', '紫極宮齋後', '紫極宮斋後', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["紫府空歌碧落寒，曉星寥亮月光殘。","一羣白鶴高飛上，唯有松風吹石壇。"]', '["紫府空歌碧落寒，晓星寥亮月光殘。","一羣白鹤高飞上，唯有松风吹石壇。"]', '诗', 'shi', '', NULL, '紫極宮齋後 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9e7e700-e2ce-4bbe-946e-6d2b26254b36', '春晚', '春晚', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["思鄉之客空凝嚬，天邊欲盡未盡春。","獨攀江樹深不語，芳草落花愁殺人。"]', '["思乡之客空凝嚬，天邊欲尽未尽春。","独攀江樹深不語，芳草落花愁殺人。"]', '诗', 'shi', '', NULL, '春晚 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c032015d-7a60-47f7-b2c0-5409f438fb90', '喜渾吉見訪', '喜渾吉见訪', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["公子春衫桂水香，遠衝飛雪過書堂。","貧家冷落難消日，唯有松筠滿院涼。"]', '["公子春衫桂水香，远衝飞雪過书堂。","貧家冷落难消日，唯有松筠满院涼。"]', '诗', 'shi', '', NULL, '喜渾吉見訪 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('787bb977-7998-4893-853d-eb5ed377abb8', '索曲送酒', '索曲送酒', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["簾外春風正落梅，須求狂藥解愁回。","煩君玉指輕攏撚，慢撥鴛鴦送一杯。"]', '["簾外春风正落梅，須求狂藥解愁回。","煩君玉指轻攏撚，慢撥鴛鴦送一杯。"]', '诗', 'shi', '', NULL, '索曲送酒 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90890e99-9439-4c73-8a79-fbfd6fe7bd9f', '山驛梅花', '山驛梅花', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["生在幽崖獨無主，溪蘿澗鳥爲儔侶。","行人陌上不留情，愁香空謝深山雨。"]', '["生在幽崖独無主，溪蘿澗鸟爲儔侶。","行人陌上不留情，愁香空謝深山雨。"]', '诗', 'shi', '', NULL, '山驛梅花 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847e0f3f-47bc-498c-a747-6ff4d4e83bbb', '重陽日上渚宮楊尚書', '重陽日上渚宮楊尚书', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["落帽臺邊菊半黃，行人惆悵對重陽。","荆州一見桓宣武，爲趁悲秋入帝鄉。"]', '["落帽台邊菊半黄，行人惆悵对重陽。","荆州一见桓宣武，爲趁悲秋入帝乡。"]', '诗', 'shi', '', NULL, '重陽日上渚宮楊尚書 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cce42a6-26f2-483d-bdf2-2bdc02e3498f', '書院二小松', '书院二小松', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["一雙幽色出凡塵，數粒秋煙二尺鱗。","從此靜牕聞細韻，琴聲長伴讀書人。"]', '["一雙幽色出凡塵，數粒秋煙二尺鱗。","從此静牕闻細韻，琴声长伴读书人。"]', '诗', 'shi', '', NULL, '書院二小松 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc79dedd-27d1-492a-bdc6-9bc4216502df', '勸人廬山讀書', '勸人廬山读书', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["憐君少雋利如鋒，氣爽神清刻骨聰。","片玉若磨唯轉瑩，莫辭雲水入廬峰。"]', '["怜君少雋利如鋒，氣爽神清刻骨聰。","片玉若磨唯轉瑩，莫辞云水入廬峰。"]', '诗', 'shi', '', NULL, '勸人廬山讀書 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ac0fdd-9aed-47f0-a20e-8d0351163b8f', '言懷', '言懷', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["白鶴高飛不逐羣，嵇康琴酒鮑昭文。","此身未有棲歸處，天下人間一片雲。"]', '["白鹤高飞不逐羣，嵇康琴酒鲍昭文。","此身未有棲归处，天下人间一片云。"]', '诗', 'shi', '', NULL, '言懷 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fab4fec6-1b28-408f-af4e-e1f6add145d1', '聞笛', '闻笛', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["冉冉生山草何異，截而吹之動天地。","望鄉臺上望鄉時，不獨落梅兼落淚。"]', '["冉冉生山草何異，截而吹之动天地。","望乡台上望乡时，不独落梅兼落泪。"]', '诗', 'shi', '', NULL, '聞笛 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d45675d-2a28-4f84-9529-1467a01a3b1a', '曉讌', '晓讌', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["金波西傾銀漢落，綠樹含煙倚朱閣。","曉華朧𦝰聞調笙，一點殘燈隔羅幕。"]', '["金波西傾銀漢落，綠樹含煙倚朱閣。","晓华朧𦝰闻調笙，一点殘灯隔羅幕。"]', '诗', 'shi', '', NULL, '曉讌 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af881535-706e-4360-afc1-6fb96c6f8207', '將遊荆州投魏中丞', '將游荆州投魏中丞', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["貧埋病壓老巑岏，拂拭菱花不喜看。","又恐無人肯青眼，事須憑仗小還丹。"]', '["貧埋病壓老巑岏，拂拭菱花不喜看。","又恐無人肯青眼，事須憑仗小還丹。"]', '诗', 'shi', '', NULL, '將遊荆州投魏中丞 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1d0e493-7d09-4a82-a6a7-ab00c2e0504a', '二辛夷', '二辛夷', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["狂吟亂舞雙白鶴，霜翎玉羽紛紛落。","空庭向晚春雨微，却斂寒香抱瑤萼。"]', '["狂吟亂舞雙白鹤，霜翎玉羽紛紛落。","空庭向晚春雨微，却斂寒香抱瑤萼。"]', '诗', 'shi', '', NULL, '二辛夷 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('255ef1e3-d565-4f7f-bc9e-d9c0e8044747', '題龍潭西齋', '題龙潭西斋', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["寂寞幽齋暝煙起，滿徑西風落松子。","遠公一去兜率宮，唯有面前虎溪水。"]', '["寂寞幽斋暝煙起，满徑西风落松子。","远公一去兜率宮，唯有面前虎溪水。"]', '诗', 'shi', '', NULL, '題龍潭西齋 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0ecdd7d-ee70-4a78-b723-a3227049a555', '中秋寄南海梁侍御', '中秋寄南海梁侍御', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["海靜天高景氣殊，鯨晴失彩蚌潛珠。","不知今夜越臺上，望見瀛洲方丈無。"]', '["海静天高景氣殊，鯨晴失彩蚌潛珠。","不知今夜越台上，望见瀛洲方丈無。"]', '诗', 'shi', '', NULL, '中秋寄南海梁侍御 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ee291c-342b-4be9-8f7c-acbf3ab50f09', '戲贈姬人', '戲贈姬人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["骰子巡拋裹手拈，無因得見玉纖纖。","但知謔道金釵落，圖向人前露指尖。"]', '["骰子巡拋裹手拈，無因得见玉纖纖。","但知謔道金釵落，圖向人前露指尖。"]', '诗', 'shi', '', NULL, '戲贈姬人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd2be2cf-de96-4c81-85fd-1bc41b535f83', '大庾山嶺別友人', '大庾山嶺別友人', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["篔簹無子鴛雛飢，毛彩凋摧不得歸。","誰念火雲千嶂裏，低身猶傍鷓鴣飛。"]', '["篔簹無子鴛雛飢，毛彩凋摧不得归。","誰念火云千嶂裏，低身猶傍鷓鴣飞。"]', '诗', 'shi', '', NULL, '大庾山嶺別友人 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2850efd7-f2ea-4bdf-867b-e3b6e2058500', '石門戍', '石门戍', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["到此空思吳隱之，潮痕草蔓上幽碑。","人來皆望珠璣去，誰詠貪泉四句詩。"]', '["到此空思吳隐之，潮痕草蔓上幽碑。","人来皆望珠璣去，誰詠貪泉四句诗。"]', '诗', 'shi', '', NULL, '石門戍 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8861fe-bc1e-41ec-a389-19700e369916', '文殊院避暑', '文殊院避暑', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["赤日黃埃滿世間，松聲入耳即心閑。","願尋五百仙人去，一世清涼住雪山。"]', '["赤日黄埃满世间，松声入耳即心闲。","願尋五百仙人去，一世清涼住雪山。"]', '诗', 'shi', '', NULL, '文殊院避暑 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51d544b4-79b1-47e4-bbab-24fe8a162607', '南莊春晚二首 一', '南莊春晚二首 一', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["連雲草映一條陂，鸂鶒雙雙帶水飛。","南邨小路桃花落，細雨斜風獨自歸。"]', '["連云草映一條陂，鸂鶒雙雙带水飞。","南邨小路桃花落，細雨斜风独自归。"]', '诗', 'shi', '', NULL, '南莊春晚二首 一 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70ab4197-b7c0-4e9c-b735-ece3e3c3e27d', '南莊春晚二首 二', '南莊春晚二首 二', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["草暖沙長望去舟，微茫煙浪向巴丘。","沅江寂寂春歸盡，水綠蘋香人自愁。"]', '["草暖沙长望去舟，微茫煙浪向巴丘。","沅江寂寂春归尽，水綠蘋香人自愁。"]', '诗', 'shi', '', NULL, '南莊春晚二首 二 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4c96091-a834-43b8-b4a0-1a427c720e28', '湘妃廟', '湘妃廟', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["少將風月怨平湖，見盡扶桑水到枯。","相約杏花壇上去，畫欄紅紫鬬樗蒲。"]', '["少將风月怨平湖，见尽扶桑水到枯。","相約杏花壇上去，畫欄紅紫鬬樗蒲。"]', '诗', 'shi', '', NULL, '湘妃廟 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5874f656-3ae8-4c95-8e4f-883f9ed24e1d', '古意', '古意', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["碌碌復碌碌，百年雙轉轂。","志士終夜心，良馬白日足。","俱爲不等閑，誰是知音目。","眼中兩行淚，曾弔三獻玉。"]', '["碌碌复碌碌，百年雙轉轂。","志士終夜心，良马白日足。","俱爲不等闲，誰是知音目。","眼中兩行泪，曾弔三獻玉。"]', '诗', 'shi', '', NULL, '古意 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6829baaa-cb45-4864-a26b-fb27b73b6e34', '望山', '望山', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["南山三十里，不見踰一旬。","冒雨時立望，望之如朋親。","虬龍一掬波，洗蕩千萬春。","日日雨不斷，愁殺望山人。","天事不可長，勁風來如奔。","陰霪一以掃，浩翠寫國門。","長安百萬家，家家張屏新。","誰家最好山，我願爲其鄰。"]', '["南山三十里，不见踰一旬。","冒雨时立望，望之如朋親。","虬龙一掬波，洗蕩千万春。","日日雨不斷，愁殺望山人。","天事不可长，勁风来如奔。","陰霪一以掃，浩翠寫国门。","长安百万家，家家張屏新。","誰家最好山，我願爲其鄰。"]', '诗', 'shi', '', NULL, '望山 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2020472-81e6-49ed-a08d-900b97932629', '北嶽廟', '北嶽廟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["天地有五嶽，恒嶽居其北。","巖巒疊萬重，詭怪浩難測。","人來不敢入，祠宇白日黑。","有時起霖雨，一灑天地德。","神兮安在哉，永康我王國。"]', '["天地有五嶽，恒嶽居其北。","巖巒叠万重，詭怪浩难測。","人来不敢入，祠宇白日黑。","有时起霖雨，一灑天地德。","神兮安在哉，永康我王国。"]', '诗', 'shi', '', NULL, '北嶽廟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68ed6810-ae39-431b-bea7-ef0e053d9c1a', '朝飢', '朝飢', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["市中有樵山，此舍朝無煙。","井底有甘泉，釜中乃空然。","我要見白日，雪來塞青天。","坐聞西牀琴，凍折兩三弦。","飢莫詣他門，古人有拙言。"]', '["市中有樵山，此舍朝無煙。","井底有甘泉，釜中乃空然。","我要见白日，雪来塞青天。","坐闻西牀琴，凍折兩三弦。","飢莫詣他门，古人有拙言。"]', '诗', 'shi', '', NULL, '朝飢 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b5da8e-c04b-47b1-81e9-663364734624', '哭盧仝', '哭盧仝', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["賢人無官死，不親者亦悲。","空令古鬼哭，更得新鄰比。","平生四十年，惟著白布衣。","天子未辟召，地府誰來追。","長安有交友，託孤遽棄移。","塚側誌石短，文字行參差。","無錢買松栽，自生蒿草枝。","在日贈我文，淚流把讀時。","從茲加敬重，深藏恐失遺。"]', '["賢人無官死，不親者亦悲。","空令古鬼哭，更得新鄰比。","平生四十年，惟著白布衣。","天子未辟召，地府誰来追。","长安有交友，託孤遽棄移。","塚側誌石短，文字行參差。","無錢買松栽，自生蒿草枝。","在日贈我文，泪流把读时。","從茲加敬重，深藏恐失遺。"]', '诗', 'shi', '', NULL, '哭盧仝 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef5f6c59-7460-402d-a2e6-fb8214ea5332', '劍客', '劍客', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["十年磨一劍，霜刃未曾試。","今日把似君，誰爲不平事。"]', '["十年磨一劍，霜刃未曾試。","今日把似君，誰爲不平事。"]', '诗', 'shi', '', NULL, '劍客 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('372910ce-ef22-4847-b33e-0874e43f5cef', '口號', '口號', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["中夜忽自起，汲此百尺泉。","林木含白露，星斗在青天。"]', '["中夜忽自起，汲此百尺泉。","林木含白露，星斗在青天。"]', '诗', 'shi', '', NULL, '口號 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b57c5e-8bce-4540-ad71-3a36e5dec7e1', '寄遠', '寄远', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["別腸多鬱紆，豈能肥肌膚。","始知相結密，不及相結疎。","疎別恨應少，密離恨難袪。","門前南流水，中有北飛魚。","魚飛向北海，可以寄遠書。","不惜寄遠書，故人今在無。","況此數尺身，阻彼萬里途。","自非日月光，難以知子軀。"]', '["別腸多鬱紆，豈能肥肌膚。","始知相結密，不及相結疎。","疎別恨應少，密離恨难袪。","门前南流水，中有北飞鱼。","鱼飞向北海，可以寄远书。","不惜寄远书，故人今在無。","況此數尺身，阻彼万里途。","自非日月光，难以知子軀。"]', '诗', 'shi', '', NULL, '寄遠 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f760d47a-e3b6-4519-94c6-08108c244783', '齋中', '斋中', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["眈靜非謬爲，本性實疎索。","齋中一就枕，不覺白日落。","低扉礙軒轡，寡德謝接諾。","叢菊在牆陰，秋窮未開萼。","所餐類病馬，動影似移嶽。","欲駐迫逃衰，豈殊亂綆縛。","已見飽時雨，應豐蔬與藥。"]', '["眈静非謬爲，本性實疎索。","斋中一就枕，不覺白日落。","低扉礙軒轡，寡德謝接諾。","叢菊在牆陰，秋窮未开萼。","所餐類病马，动影似移嶽。","欲駐迫逃衰，豈殊亂綆縛。","已见飽时雨，應豐蔬與藥。"]', '诗', 'shi', '', NULL, '齋中 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16690f49-2754-48fa-8f6a-1212f1720f1b', '感秋', '感秋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["商氣颯已來，歲華又虛擲。","朝雲藏奇峰，暮雨灑疎滴。","幾蜩嘿涼葉，數蛩思陰壁。","落日空館中，歸心遠山碧。","昔人多秋感，今人何異昔。","四序馳百年，玄髮坐成白。","喧喧徇聲利，擾擾同轍迹。","儻無世上懷，去偃松下石。"]', '["商氣颯已来，歲华又虛擲。","朝云藏奇峰，暮雨灑疎滴。","幾蜩嘿涼葉，數蛩思陰壁。","落日空館中，归心远山碧。","昔人多秋感，今人何異昔。","四序驰百年，玄髮坐成白。","喧喧徇声利，擾擾同轍迹。","儻無世上懷，去偃松下石。"]', '诗', 'shi', '', NULL, '感秋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e785508d-0bf8-42c0-aa33-e6542a46894e', '翫月', '翫月', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寒月破東北，賈生立西南。","西南立倚何，立倚青青杉。","近月有數星，星名未詳諳。","但愛杉倚月，我倚杉爲三。","月乃不上杉，上杉難相參。","眙𥈭子細視，睛瞳桂枝劖。","目常有熱疾，久視無煩炎。","以手捫衣裳，零露已濡霑。","久立雙足凍，時向股䏶淹。","立久病足折，兀然黐膠黏。","他人應已睡，轉喜此景恬。","此景亦胡及，而我苦淫耽。","無異市井人，見金不知廉。","不知此夜中，幾人同無厭。","待得上頂看，未擬歸枕函。","強步望寢齋，步步情不堪。","步到竹叢西，東望如隔簾。","却坐竹叢外，清思刮幽潛。","量知愛月人，身願化爲蟾。"]', '["寒月破东北，賈生立西南。","西南立倚何，立倚青青杉。","近月有數星，星名未詳諳。","但愛杉倚月，我倚杉爲三。","月乃不上杉，上杉难相參。","眙𥈭子細視，睛瞳桂枝劖。","目常有熱疾，久視無煩炎。","以手捫衣裳，零露已濡霑。","久立雙足凍，时向股䏶淹。","立久病足折，兀然黐膠黏。","他人應已睡，轉喜此景恬。","此景亦胡及，而我苦淫耽。","無異市井人，见金不知廉。","不知此夜中，幾人同無厭。","待得上頂看，未擬归枕函。","強步望寢斋，步步情不堪。","步到竹叢西，东望如隔簾。","却坐竹叢外，清思刮幽潛。","量知愛月人，身願化爲蟾。"]', '诗', 'shi', '', NULL, '翫月 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18c0623d-3c84-4a97-ae20-5246611b1483', '辭二知己', '辞二知己', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一雙千歲鶴，立別孤翔鴻。","波島忽已暮，海雨寒濛濛。","離人聞美彈，亦與哀彈同。","況茲切切弄，繞彼行行躬。","雲飛北嶽碧，火息西山紅。","何以代遠誠，折芳臘雪中。"]', '["一雙千歲鹤，立別孤翔鴻。","波島忽已暮，海雨寒濛濛。","離人闻美彈，亦與哀彈同。","況茲切切弄，繞彼行行躬。","云飞北嶽碧，火息西山紅。","何以代远誠，折芳臘雪中。"]', '诗', 'shi', '', NULL, '辭二知己 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60a6229-3bf1-400e-8b56-1d307998456d', '義雀行和朱評事', '義雀行和朱評事', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["玄鳥雄雌俱，春雷驚蟄餘。","口銜黃河泥，空即翔天隅。","一夕皆莫歸，嘵嘵遺衆雛。","雙雀抱仁義，哺食勞劬劬。","雛既邐迤飛，雲間聲相呼。","燕雀雖微類，感媿誠不殊。","禽賢難自彰，幸得主人書。"]', '["玄鸟雄雌俱，春雷驚蟄餘。","口銜黄河泥，空即翔天隅。","一夕皆莫归，嘵嘵遺衆雛。","雙雀抱仁義，哺食勞劬劬。","雛既邐迤飞，云间声相呼。","燕雀雖微類，感媿誠不殊。","禽賢难自彰，幸得主人书。"]', '诗', 'shi', '', NULL, '義雀行和朱評事 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a07e44fe-2a73-40af-a53a-e735eb124928', '宿懸泉驛', '宿懸泉驛', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曉行瀝水樓，暮到懸泉驛。","林月值雲遮，山燈照愁寂。"]', '["晓行瀝水楼，暮到懸泉驛。","林月值云遮，山灯照愁寂。"]', '诗', 'shi', '', NULL, '宿懸泉驛 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4399b22a-5a04-43fd-8113-952d04674b0f', '辯士', '辯士', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["辯士多毀訾，不聞談己非。","猛虎恣殺暴，未嘗齧妻兒。","此理天所感，所感當問誰。","求食飼雛禽，吐出美言詞。","善哉君子人，揚光掩瑕玼。"]', '["辯士多毀訾，不闻談己非。","猛虎恣殺暴，未嘗齧妻兒。","此理天所感，所感當问誰。","求食飼雛禽，吐出美言词。","善哉君子人，揚光掩瑕玼。"]', '诗', 'shi', '', NULL, '辯士 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ff43d2f-dc93-4f57-9e7b-8a323caed335', '不欺', '不欺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["上不欺星辰，下不欺鬼神。","知心兩如此，然後何所陳。","食魚味在鮮，食蓼味在辛。","掘井須到流，結交須到頭。","此語誠不謬，敵君三萬秋。"]', '["上不欺星辰，下不欺鬼神。","知心兩如此，然後何所陳。","食鱼味在鲜，食蓼味在辛。","掘井須到流，結交須到头。","此語誠不謬，敵君三万秋。"]', '诗', 'shi', '', NULL, '不欺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054711fb-3baf-435e-83aa-549d8b007e4d', '絕句', '絕句', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["海底有明月，圓於天上輪。","得之一寸光，可買千里春。"]', '["海底有明月，圓於天上輪。","得之一寸光，可買千里春。"]', '诗', 'shi', '', NULL, '絕句 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d804d6e-6b8d-420f-a6f4-77ea407f0921', '寓興', '寓兴', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["莫居暗室中，開目閉目同。","莫趨碧霄路，容飛不容步。","暗室未可居，碧霄未可趨。","勸君跨仙鶴，日下雲爲衢。"]', '["莫居暗室中，开目閉目同。","莫趨碧霄路，容飞不容步。","暗室未可居，碧霄未可趨。","勸君跨仙鹤，日下云爲衢。"]', '诗', 'shi', '', NULL, '寓興 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4788fcc-0b63-4571-9b26-8d44760906ac', '遊仙', '游仙', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["借得孤鶴騎，高近金烏飛。","掬河洗老貌，照月生光輝。","天中鶴路直，天盡鶴一息。","歸來不騎鶴，身自有羽翼。","若人無仙骨，芝朮徒煩食。"]', '["借得孤鹤騎，高近金烏飞。","掬河洗老貌，照月生光輝。","天中鹤路直，天尽鹤一息。","归来不騎鹤，身自有羽翼。","若人無仙骨，芝朮徒煩食。"]', '诗', 'shi', '', NULL, '遊仙 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3be4f4c-15ed-4f6e-bc54-2a01224d69e6', '枕上吟', '枕上吟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["夜長憶白日，枕上吟千詩。","何當苦寒氣，忽被東風吹。","冰開魚龍別，天波殊路岐。"]', '["夜长憶白日，枕上吟千诗。","何當苦寒氣，忽被东风吹。","冰开鱼龙別，天波殊路岐。"]', '诗', 'shi', '', NULL, '枕上吟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc2bc36-c403-417a-8c3a-bbc37ecd73e1', '雙魚謠', '雙鱼謠', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["天河墮雙魴，飛我庭中央。","掌握尺餘雪，劈開腸有璜。","見令饞舌短，烹遶鄰舍香。","一得古詩字，與玉含異藏。"]', '["天河墮雙魴，飞我庭中央。","掌握尺餘雪，劈开腸有璜。","见令饞舌短，烹遶鄰舍香。","一得古诗字，與玉含異藏。"]', '诗', 'shi', '', NULL, '雙魚謠 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0a83246-7f4c-4814-8775-19c704132fa9', '易水懷古', '易水懷古', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["荆卿重虛死，節烈書前史。","我歎方寸心，誰論一時事。","至今易水橋，寒風兮蕭蕭。","易水流得盡，荆卿名不消。"]', '["荆卿重虛死，節烈书前史。","我歎方寸心，誰論一时事。","至今易水橋，寒风兮蕭蕭。","易水流得尽，荆卿名不消。"]', '诗', 'shi', '', NULL, '易水懷古 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe2946f9-e59c-4f30-8dba-1cfbc3608040', '早起', '早起', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["北客入西京，北鴈再離北。","秋寢獨前興，天梭星落織。","耽翫餘恬爽，顧盼輕痾力。","旅途少顏盡，明鏡勸仙食。","出門路縱橫，張家路最直。","昨夜夢見書，張家廳上壁。"]', '["北客入西京，北鴈再離北。","秋寢独前兴，天梭星落织。","耽翫餘恬爽，顧盼轻痾力。","旅途少顏尽，明镜勸仙食。","出门路縱橫，張家路最直。","昨夜梦见书，張家廳上壁。"]', '诗', 'shi', '', NULL, '早起 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b064ae34-c624-432b-8860-19fbb721b895', '客喜', '客喜', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["客喜非實喜，客悲非實悲。","百迴信到家，未當身一歸。","未歸長嗟愁，嗟愁填中懷。","開口吐愁聲，還却入耳來。","常恐淚滴多，自損兩目輝。","鬢邊雖有絲，不堪織寒衣。"]', '["客喜非實喜，客悲非實悲。","百迴信到家，未當身一归。","未归长嗟愁，嗟愁填中懷。","开口吐愁声，還却入耳来。","常恐泪滴多，自損兩目輝。","鬢邊雖有絲，不堪织寒衣。"]', '诗', 'shi', '', NULL, '客喜 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4375fad-c184-471a-a680-192fb44c6c7b', '延壽里精舍寓居', '延壽里精舍寓居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["旅託避華館，荒樓遂愚慵。","短庭無繁植，珍果春亦濃。","側廬廢扃樞，纖魄時臥逢。","耳目乃鄽井，肺肝即巖峰。","汲泉飲酌餘，見我閑靜容。","霜蹊猶舒英，寒蝶斷來踪。","雙履與誰逐，一尋青瘦筇。"]', '["旅託避华館，荒楼遂愚慵。","短庭無繁植，珍果春亦濃。","側廬廢扃樞，纖魄时臥逢。","耳目乃鄽井，肺肝即巖峰。","汲泉饮酌餘，见我闲静容。","霜蹊猶舒英，寒蝶斷来踪。","雙履與誰逐，一尋青瘦筇。"]', '诗', 'shi', '', NULL, '延壽里精舍寓居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dba77fb-923f-404d-af54-fe891d8bb01a', '贈智朗禪師', '贈智朗禪師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["上人分明見，玉兔潭底沒。","上人光慘貌，古來恨峭發。","涕辭孔顏廟，笑訪禪寂室。","步隨青山影，坐學白塔骨。","解聽無弄琴，不禮有身佛。","欲問師何之，忽與我相別。","率賦贈遠言，言慙非子曰。"]', '["上人分明见，玉兔潭底沒。","上人光慘貌，古来恨峭發。","涕辞孔顏廟，笑訪禪寂室。","步隨青山影，坐学白塔骨。","解听無弄琴，不禮有身佛。","欲问師何之，忽與我相別。","率賦贈远言，言慙非子曰。"]', '诗', 'shi', '', NULL, '贈智朗禪師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d58e148-6a3d-4502-b039-d4a7a5d7fdff', '送沈秀才下第東歸', '送沈秀才下第东归', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曲言惡者誰，悅耳如彈絲。","直言好者誰，刺耳如長錐。","沈生才俊秀，心腸無邪欺。","君子忌苟合，擇交如求師。","毀出疾夫口，騰入禮部闈。","下第子不恥，遺才人恥之。","東歸家室遠，掉轡時參差。","浙雲近吳見，汴柳接楚垂。","明年春光別，回首不復疑。"]', '["曲言惡者誰，悅耳如彈絲。","直言好者誰，刺耳如长錐。","沈生才俊秀，心腸無邪欺。","君子忌苟合，擇交如求師。","毀出疾夫口，腾入禮部闈。","下第子不恥，遺才人恥之。","东归家室远，掉轡时參差。","浙云近吳见，汴柳接楚垂。","明年春光別，回首不复疑。"]', '诗', 'shi', '', NULL, '送沈秀才下第東歸 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5be80e6-185d-4338-a834-976dfb2f5f47', '酬棲上人', '酬棲上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["夜久城館閑，情幽出在山。","新月有微輝，朗朗空庭間。","處世雖識機，伊余多掩關。","松姿度臘見，籬藥知春還。","靜覽冰雪詞，厚爲酬贈顏。","東林有躑躅，脫屣期共攀。"]', '["夜久城館闲，情幽出在山。","新月有微輝，朗朗空庭间。","处世雖識機，伊余多掩关。","松姿度臘见，籬藥知春還。","静覽冰雪词，厚爲酬贈顏。","东林有躑躅，脫屣期共攀。"]', '诗', 'shi', '', NULL, '酬棲上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2204bcb6-175b-46ba-a5f1-60e7e86f526d', '冬月長安雨中見終南雪', '冬月长安雨中见終南雪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["秋節新已盡，雨疎露山雪。","西峰稍覺明，殘滴猶未絕。","氣侵瀑布水，凍著白雲穴。","今朝灞滻鴈，何夕瀟湘月。","想彼石房人，對雪扉不閉。"]', '["秋節新已尽，雨疎露山雪。","西峰稍覺明，殘滴猶未絕。","氣侵瀑布水，凍著白云穴。","今朝灞滻鴈，何夕瀟湘月。","想彼石房人，对雪扉不閉。"]', '诗', 'shi', '', NULL, '冬月長安雨中見終南雪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12e1e859-e9f2-4aa8-b5b0-6625e5085283', '寄孟協律', '寄孟協律', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["我有弔古泣，不泣向路岐。","揮淚灑暮天，滴著桂樹枝。","別後冬節至，離心北風吹。","坐孤雪扉夕，泉落石橋時。","不驚猛虎嘯，難辱君子詞。","欲酬空覺老，無以堪遠持。","岧嶤倚角窗，王屋懸清思。"]', '["我有弔古泣，不泣向路岐。","揮泪灑暮天，滴著桂樹枝。","別後冬節至，離心北风吹。","坐孤雪扉夕，泉落石橋时。","不驚猛虎嘯，难辱君子词。","欲酬空覺老，無以堪远持。","岧嶤倚角窗，王屋懸清思。"]', '诗', 'shi', '', NULL, '寄孟協律 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cd16646-c3ab-4c85-a297-53c2706d4d58', '和劉涵', '和劉涵', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["京官始云滿，野人依舊閑。","閉扉一畝居，中有古風還。","市井日已午，幽窗夢南山。","喬木覆北齋，有鳥鳴其間。","前日遠嶽僧，來時與開關。","新題驚我瘦，窺鏡見醜顏。","陶情惜清澹，此意復誰攀。"]', '["京官始云满，野人依旧闲。","閉扉一畝居，中有古风還。","市井日已午，幽窗梦南山。","喬木覆北斋，有鸟鳴其间。","前日远嶽僧，来时與开关。","新題驚我瘦，窺镜见醜顏。","陶情惜清澹，此意复誰攀。"]', '诗', 'shi', '', NULL, '和劉涵 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9c2fe8-a393-40f1-9f7c-2f4e95d4f5a9', '明月山懷獨孤崇魚琢', '明月山懷独孤崇鱼琢', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["明月長在目，明月長在心。","在心復在目，何得稀去尋。","試望明月人，孟夏樹蔽岑。","想彼嘆此懷，樂喧忘幽林。","鄉本北嶽外，悔恨東夷深。","願縮地脈還，豈待天恩臨。","非不渴隱秀，却嫌他事侵。","或云岳樓鐘，來繞草堂吟。","當從令伊後，再往步柏林。"]', '["明月长在目，明月长在心。","在心复在目，何得稀去尋。","試望明月人，孟夏樹蔽岑。","想彼嘆此懷，乐喧忘幽林。","乡本北嶽外，悔恨东夷深。","願縮地脈還，豈待天恩臨。","非不渴隐秀，却嫌他事侵。","或云岳楼鐘，来繞草堂吟。","當從令伊後，再往步柏林。"]', '诗', 'shi', '', NULL, '明月山懷獨孤崇魚琢 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78d98cda-00dd-48ca-b377-4dccad7e184f', '投張太祝', '投張太祝', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["風骨高更老，向春初陽葩。","[泠泠]月下韻，一一落海涯。","有子不敢和，一聽千嘆嗟。","身臥東北泥，魂挂西南霞。","手把一枝栗，往輕覺程賒。","水天朔方色，暖日嵩根花。","達閑幽棲山，遣尋種藥家。","欲買雙瓊瑤，慙無一木瓜。"]', '["风骨高更老，向春初陽葩。","[泠泠]月下韻，一一落海涯。","有子不敢和，一听千嘆嗟。","身臥东北泥，魂挂西南霞。","手把一枝栗，往轻覺程賒。","水天朔方色，暖日嵩根花。","達闲幽棲山，遣尋種藥家。","欲買雙瓊瑤，慙無一木瓜。"]', '诗', 'shi', '', NULL, '投張太祝 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958692bc-c547-4dbb-b773-912121e27a7f', '詠韓氏二子', '詠韓氏二子', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["千巖一尺璧，八月十五夕。","清露墮桂花，白鳥舞虛碧。"]', '["千巖一尺璧，八月十五夕。","清露墮桂花，白鸟舞虛碧。"]', '诗', 'shi', '', NULL, '詠韓氏二子 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29474401-25a5-4f15-8f30-bd1bbc899557', '送別', '送別', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["丈夫未得意，行行且低眉。","素琴彈復彈，會有知音知。"]', '["丈夫未得意，行行且低眉。","素琴彈复彈，會有知音知。"]', '诗', 'shi', '', NULL, '送別 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cfd0726-3105-41c1-ab25-aef335f3a82a', '攜新文詣張籍韓愈途中成', '携新文詣張籍韓愈途中成', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["袖有新成詩，欲見張韓老。","青竹未生翼，一步萬里道。","仰望青冥天，雲雪壓我腦。","失却終南山，惆悵滿懷抱。","安得西北風，身願變蓬草。","地祇聞此語，突出驚我倒。"]', '["袖有新成诗，欲见張韓老。","青竹未生翼，一步万里道。","仰望青冥天，云雪壓我腦。","失却終南山，惆悵满懷抱。","安得西北风，身願变蓬草。","地祇闻此語，突出驚我倒。"]', '诗', 'shi', '', NULL, '攜新文詣張籍韓愈途中成 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2498e5d9-766c-4015-8cb9-5883cd6b143e', '上谷送客遊江湖', '上谷送客游江湖', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["莫歎迢遰分，何殊咫尺別。","江樓到夜登，還見南臺月。"]', '["莫歎迢遰分，何殊咫尺別。","江楼到夜登，還见南台月。"]', '诗', 'shi', '', NULL, '上谷送客遊江湖 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2624bfa-bfb4-4294-bdab-e5054184bee9', '重酬姚少府', '重酬姚少府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["隙月斜枕旁，諷詠夏貽什。","如今何時節，蟲虺亦已蟄。","答遲禮涉傲，抱疾思加澀。","僕本胡爲者，銜肩貢客集。","茫然九州內，譬如一錐立。","欺暗少此懷，自明曾瀝泣。","量無趫勇士，誠欲戈矛戢。","原閣期躋攀，潭舫偶俱入。","深齋竹木合，畢夕風雨急。","俸利沐均分，價稱煩噓噏。","百篇見刪罷，一命嗟未及。","滄浪愚將還，知音激所習。"]', '["隙月斜枕旁，諷詠夏貽什。","如今何时節，蟲虺亦已蟄。","答遲禮涉傲，抱疾思加澀。","僕本胡爲者，銜肩貢客集。","茫然九州內，譬如一錐立。","欺暗少此懷，自明曾瀝泣。","量無趫勇士，誠欲戈矛戢。","原閣期躋攀，潭舫偶俱入。","深斋竹木合，畢夕风雨急。","俸利沐均分，價稱煩噓噏。","百篇见刪罷，一命嗟未及。","滄浪愚將還，知音激所習。"]', '诗', 'shi', '', NULL, '重酬姚少府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b76e800b-6bd5-433a-9384-edbfb139d31e', '投孟郊', '投孟郊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["月中有孤芳，天下聆薰風。","江南有高唱，海北初來通。","容飄清冷餘，自蘊襟抱中。","止息乃流溢，推尋却冥濛。","我知雪山子，謁彼偈句空。","必竟獲所實，爾焉遂深衷。","錄之孤燈前，猶恨百首終。","一吟動狂機，萬疾辭頑躬。","生平面未交，永夕夢輒同。","敘詰誰君師，詎言無吾宗。","余求履其跡，君曰可但攻。","啜波腸易飽，揖險神難從。","前歲曾入洛，差池阻從龍。","萍家復從趙，雲思長縈縈。","嵩海每可詣，長途追再窮。","願傾肺腸事，盡入焦梧桐。"]', '["月中有孤芳，天下聆薰风。","江南有高唱，海北初来通。","容飄清冷餘，自蘊襟抱中。","止息乃流溢，推尋却冥濛。","我知雪山子，謁彼偈句空。","必竟獲所實，爾焉遂深衷。","錄之孤灯前，猶恨百首終。","一吟动狂機，万疾辞頑躬。","生平面未交，永夕梦輒同。","敘詰誰君師，詎言無吾宗。","余求履其跡，君曰可但攻。","啜波腸易飽，揖險神难從。","前歲曾入洛，差池阻從龙。","萍家复從趙，云思长縈縈。","嵩海每可詣，长途追再窮。","願傾肺腸事，尽入焦梧桐。"]', '诗', 'shi', '', NULL, '投孟郊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7105487f-ef6b-465d-913f-97f57b5e45e8', '代邊將', '代邊將', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["持戈簇邊日，戰罷浮雲收。","露草泣寒霽，夜泉鳴隴頭。","三尺握中鐵，氣衝星斗牛。","報國不拘貴，憤將平虜讎。"]', '["持戈簇邊日，戰罷浮云收。","露草泣寒霽，夜泉鳴隴头。","三尺握中鐵，氣衝星斗牛。","報国不拘貴，憤將平虜讎。"]', '诗', 'shi', '', NULL, '代邊將 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944615b0-d7de-4fc2-bb6d-49236d59de4e', '寄劉棲楚', '寄劉棲楚', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["趨走與偃臥，去就自殊分。","當窗一重樹，上有萬里雲。","離披不相顧，髣髴類人羣。","友生去更遠，來書絕如焚。","蟬吟我爲聽，我歌蟬豈聞。","歲暮儻旋歸，晤言桂氛氳。"]', '["趨走與偃臥，去就自殊分。","當窗一重樹，上有万里云。","離披不相顧，髣髴類人羣。","友生去更远，来书絕如焚。","蟬吟我爲听，我歌蟬豈闻。","歲暮儻旋归，晤言桂氛氳。"]', '诗', 'shi', '', NULL, '寄劉棲楚 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30c5344b-c451-4045-9051-ef99599bc78e', '寄丘儒', '寄丘儒', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["地近輕數見，地遠重一面。","一面如何重，重甚珍寶片。","自經失歡笑，幾度騰霜霰。","此心鎮懸懸，天象固迴轉。","長安秋風高，子在東甸縣。","儀形信寂蔑，風雨豈乖間。","憑人報消息，何易憑筆硯。","俱不盡我心，終須對君宴。"]', '["地近轻數见，地远重一面。","一面如何重，重甚珍寶片。","自經失歡笑，幾度腾霜霰。","此心鎮懸懸，天象固迴轉。","长安秋风高，子在东甸縣。","儀形信寂蔑，风雨豈乖间。","憑人報消息，何易憑笔硯。","俱不尽我心，終須对君宴。"]', '诗', 'shi', '', NULL, '寄丘儒 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cd115ca-3719-420a-b44c-f7f48505ae30', '送陳商', '送陳商', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["古道長荆棘，新岐路交橫。","君於荒榛中，尋得古轍行。","足踏聖人路，貌端禪士形。","我曾接夜談，似聽講一經。","聯翩曾數舉，昨登高第名。","釜底絕煙火，曉行皇帝京。","上客遠府遊，主人須目明。","青雲別青山，何日復可升。"]', '["古道长荆棘，新岐路交橫。","君於荒榛中，尋得古轍行。","足踏聖人路，貌端禪士形。","我曾接夜談，似听講一經。","聯翩曾數舉，昨登高第名。","釜底絕煙火，晓行皇帝京。","上客远府游，主人須目明。","青云別青山，何日复可升。"]', '诗', 'shi', '', NULL, '送陳商 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('997c1a22-0cda-46b8-914e-f3cee4341d1a', '送張校書季霞', '送張校书季霞', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["從京去容州，馬在船上多。","容州幾千里，直傍青天涯。","掌記試校書，未稱高詞華。","義往不可屈，出家如入家。","城市七月初，熱與夏未差。","餞君到野地，秋涼滿山坡。","南境異北候，風起無塵沙。","秦吟宿楚澤，海酒落桂花。","暫醉即還醒，彼土生桂茶。"]', '["從京去容州，马在船上多。","容州幾千里，直傍青天涯。","掌記試校书，未稱高词华。","義往不可屈，出家如入家。","城市七月初，熱與夏未差。","餞君到野地，秋涼满山坡。","南境異北候，风起無塵沙。","秦吟宿楚澤，海酒落桂花。","暫醉即還醒，彼土生桂茶。"]', '诗', 'shi', '', NULL, '送張校書季霞 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e19a7c36-f220-4788-88b4-6ddb93d4414a', '寄友人', '寄友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["同人半年別，一別寂來音。","賴有別時文，相思時一吟。","我常倦投跡，君亦知此衿。","筆硯且勿棄，蘇張曾陸沈。","但存舌在口，當冀身遂心。","君看明月夜，松桂寒森森。"]', '["同人半年別，一別寂来音。","賴有別时文，相思时一吟。","我常倦投跡，君亦知此衿。","笔硯且勿棄，蘇張曾陸沈。","但存舌在口，當冀身遂心。","君看明月夜，松桂寒森森。"]', '诗', 'shi', '', NULL, '寄友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('039ffb7a-91b1-4ec7-965f-104fb9b217da', '答王參', '答王參', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寸晷不相待，四時互如競。","客思先覺秋，蟲聲苦知暝。","霜松積舊翠，露月團如鏡。","詩負屬景同，琴孤坐堂聽。","相期黃菊節，別約紅桃徑。","每把式微篇，臨風一長詠。"]', '["寸晷不相待，四时互如競。","客思先覺秋，蟲声苦知暝。","霜松積旧翠，露月團如镜。","诗負屬景同，琴孤坐堂听。","相期黄菊節，別約紅桃徑。","每把式微篇，臨风一长詠。"]', '诗', 'shi', '', NULL, '答王參 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efbe4455-a579-48b3-83b6-bf4260a904c5', '延康吟', '延康吟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寄居延壽里，爲與延康鄰。","不愛延康里，愛此里中人。","人非十年故，人非九族親。","人有不朽語，得之煙山春。"]', '["寄居延壽里，爲與延康鄰。","不愛延康里，愛此里中人。","人非十年故，人非九族親。","人有不朽語，得之煙山春。"]', '诗', 'shi', '', NULL, '延康吟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90ee4e7c-bff8-4c8e-98e8-1e5daa0f5797', '戲贈友人', '戲贈友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一日不作詩，心源如廢井。","筆硯爲轆轤，吟詠作縻綆。","朝來重汲引，依舊得清[冷]。","書贈同懷人，詞中多苦辛。"]', '["一日不作诗，心源如廢井。","笔硯爲轆轤，吟詠作縻綆。","朝来重汲引，依旧得清[冷]。","书贈同懷人，词中多苦辛。"]', '诗', 'shi', '', NULL, '戲贈友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070c4620-5a89-4fb0-86c4-548df280b9f6', '寓興', '寓兴', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["真集道方至，貌殊妬還多。","山泉入城池，自然生渾波。","今時出古言，在衆翻爲訛。","有琴含正韻，知音者如何。","一生足感激，世言忽嵯峨。","不得市井味，思響吾巖阿。","浮華豈我事，日月徒蹉跎。","曠哉潁陽風，千載無其他。"]', '["真集道方至，貌殊妬還多。","山泉入城池，自然生渾波。","今时出古言，在衆翻爲訛。","有琴含正韻，知音者如何。","一生足感激，世言忽嵯峨。","不得市井味，思响吾巖阿。","浮华豈我事，日月徒蹉跎。","曠哉潁陽风，千載無其他。"]', '诗', 'shi', '', NULL, '寓興 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eb962dd-8122-42d4-bf21-2f02542a1f85', '懷鄭從志', '懷鄭從志', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["西風吹陰雲，雨雪半夜收。","忽憶天涯人，起看斗與牛。","故人別二年，我意如百秋。","音信兩杳杳，誰云昔綢繆。","平明一封書，寄向東北舟。","翩翩春歸鳥，會自爲匹儔。"]', '["西风吹陰云，雨雪半夜收。","忽憶天涯人，起看斗與牛。","故人別二年，我意如百秋。","音信兩杳杳，誰云昔綢繆。","平明一封书，寄向东北舟。","翩翩春归鸟，會自爲匹儔。"]', '诗', 'shi', '', NULL, '懷鄭從志 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2177b201-7397-4ea2-b7da-fb81d844ea4d', '易州登龍興寺樓望郡北高峰', '易州登龙兴寺楼望郡北高峰', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["郡北最高峰，巉巖絕雲路。","朝來上樓望，稍覺得幽趣。","朦朧碧煙裏，羣嶺若相附。","何時一登陟，萬物皆下顧。"]', '["郡北最高峰，巉巖絕云路。","朝来上楼望，稍覺得幽趣。","朦朧碧煙裏，羣嶺若相附。","何时一登陟，万物皆下顧。"]', '诗', 'shi', '', NULL, '易州登龍興寺樓望郡北高峰 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fcd232e-4138-41fc-a236-4ccc563e6655', '送鄭山人遊江湖', '送鄭山人游江湖', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["南遊衡嶽上，東往天台裏。","足躡華頂峰，目觀滄海水。"]', '["南游衡嶽上，东往天台裏。","足躡华頂峰，目观滄海水。"]', '诗', 'shi', '', NULL, '送鄭山人遊江湖 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b600f2d2-8c3f-4499-9406-173baa538e6d', '就峰公宿', '就峰公宿', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["河出鳥宿後，螢火白露中。","上人坐不倚，共我論量空。","殘月華晻曖，遠水響玲瓏。","爾時無了夢，茲宵方未窮。"]', '["河出鸟宿後，螢火白露中。","上人坐不倚，共我論量空。","殘月华晻曖，远水响玲瓏。","爾时無了梦，茲宵方未窮。"]', '诗', 'shi', '', NULL, '就峰公宿 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f5dd2d2-6572-483d-94b1-166ef926ec96', '劉景陽東齋', '劉景陽东斋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["松陰連竹影，中有蕪苔井。","清風此地多，白日空自永。","景陽公幹孫，詩句得真景。","勸我不須歸，月出東齋靜。"]', '["松陰連竹影，中有蕪苔井。","清风此地多，白日空自永。","景陽公幹孫，诗句得真景。","勸我不須归，月出东斋静。"]', '诗', 'shi', '', NULL, '劉景陽東齋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6718251-5934-4db9-ae50-edf26f8b0ea8', '對菊', '对菊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["九日不出門，十日見黃菊。","灼灼尚繁英，美人無消息。"]', '["九日不出门，十日见黄菊。","灼灼尚繁英，美人無消息。"]', '诗', 'shi', '', NULL, '對菊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfdc12c-f5ab-4677-9af5-30a800451058', '送集文上人遊方', '送集文上人游方', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["來從道陵井，雙木溪邊會。","分首芳草時，遠意青天外。","此遊詣幾嶽，嵩華衡恒泰。"]', '["来從道陵井，雙木溪邊會。","分首芳草时，远意青天外。","此游詣幾嶽，嵩华衡恒泰。"]', '诗', 'shi', '', NULL, '送集文上人遊方 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef56cd70-b969-45d4-87fd-520c076bb796', '題岸上人郡內閑居', '題岸上人郡內闲居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["靜向方寸求，不居山嶂幽。","池開菡萏香，門閉莓苔秋。","金玉重四句，粃糠輕九流。","鑪煙上喬木，鐘磬下危樓。","手種一株松，貞心與師儔。"]', '["静向方寸求，不居山嶂幽。","池开菡萏香，门閉莓苔秋。","金玉重四句，粃糠轻九流。","鑪煙上喬木，鐘磬下危楼。","手種一株松，貞心與師儔。"]', '诗', 'shi', '', NULL, '題岸上人郡內閑居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7074e5-711f-4cd2-b687-fe64aefeea06', '遊子', '游子', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["遊子喜鄉遠，非吾憶歸廬。","誰知奔他山，自欲早旋車。","朝賞暮已足，圖歸願無餘。","當期附鵬翼，未偶方躊躇。"]', '["游子喜乡远，非吾憶归廬。","誰知奔他山，自欲早旋车。","朝賞暮已足，圖归願無餘。","當期附鵬翼，未偶方躊躇。"]', '诗', 'shi', '', NULL, '遊子 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('938a360a-c268-446c-a15c-ca5711218465', '寄山中王參', '寄山中王參', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["我看嶽西雲，君看嶽北月。","長懷燕城南，相送十里別。","別來千餘日，日日憶不歇。","遠寄一紙書，數字論白髮。"]', '["我看嶽西云，君看嶽北月。","长懷燕城南，相送十里別。","別来千餘日，日日憶不歇。","远寄一紙书，數字論白髮。"]', '诗', 'shi', '', NULL, '寄山中王參 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68829c20-1e3c-4ae7-8238-15237574912a', '送汲鵬', '送汲鵬', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["淮南臥理後，復逢君姓汲。","文采非尋常，志願期卓立。","深江東泛舟，夕陽眺原隰。","夏夜言詩會，往往追不及。"]', '["淮南臥理後，复逢君姓汲。","文采非尋常，志願期卓立。","深江东泛舟，夕陽眺原隰。","夏夜言诗會，往往追不及。"]', '诗', 'shi', '', NULL, '送汲鵬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0cf3541-5073-4f4f-917f-9a0a67b75566', '寄令狐相公', '寄令狐相公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["策杖馳山驛，逢人問梓州。","長江那可到，行客替生愁。"]', '["策杖驰山驛，逢人问梓州。","长江那可到，行客替生愁。"]', '诗', 'shi', '', NULL, '寄令狐相公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38a5fd17-055c-404e-8ac0-1aa49efcfc15', '哭柏巖和尚', '哭柏巖和尚', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["苔覆石床新，師曾占幾春。","寫留行道影，焚却坐禪身。","塔院關松雪，經房鎖隙塵。","自嫌雙淚下，不是解空人。"]', '["苔覆石床新，師曾占幾春。","寫留行道影，焚却坐禪身。","塔院关松雪，經房鎖隙塵。","自嫌雙泪下，不是解空人。"]', '诗', 'shi', '', NULL, '哭柏巖和尚 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545013fe-bf41-4ae5-aa62-74e0c42db6c9', '山中道士', '山中道士', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["頭髮梳千下，休糧帶瘦容。","養雛成大鶴，種子作高松。","白石通宵煮，寒泉盡日舂。","不曾離隱處，那得世人逢。"]', '["头髮梳千下，休糧带瘦容。","養雛成大鹤，種子作高松。","白石通宵煮，寒泉尽日舂。","不曾離隐处，那得世人逢。"]', '诗', 'shi', '', NULL, '山中道士 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b78fb422-a1bc-4c84-a1fa-30da6ebd6290', '就可公宿', '就可公宿', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["十里尋幽寺，寒流數派分。","僧同雪夜坐，鴈向草堂聞。","靜語終燈焰，餘生許嶠雲。","由來多抱疾，聲不達明君。"]', '["十里尋幽寺，寒流數派分。","僧同雪夜坐，鴈向草堂闻。","静語終灯焰，餘生許嶠云。","由来多抱疾，声不達明君。"]', '诗', 'shi', '', NULL, '就可公宿 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d86aee8-14b4-45d2-8eee-e5df6c26a3b1', '旅遊', '旅游', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["此心非一事，書札若爲傳。","舊國別多日，故人無少年。","空巢霜葉落，疎牖水螢穿。","留得林僧宿，中宵坐默然。"]', '["此心非一事，书札若爲傳。","旧国別多日，故人無少年。","空巢霜葉落，疎牖水螢穿。","留得林僧宿，中宵坐默然。"]', '诗', 'shi', '', NULL, '旅遊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a0c154-0605-4418-a0f0-3960655a5cfa', '送鄒明府遊靈武', '送鄒明府游靈武', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曾宰西畿縣，三年馬不肥。","債多平劍與，官滿載書歸。","邊雪藏行徑，林風透臥衣。","靈州聽曉角，客館未開扉。"]', '["曾宰西畿縣，三年马不肥。","債多平劍與，官满載书归。","邊雪藏行徑，林风透臥衣。","靈州听晓角，客館未开扉。"]', '诗', 'shi', '', NULL, '送鄒明府遊靈武 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45adb6be-0d14-4946-9a26-040534f936be', '題皇甫荀藍田廳', '題皇甫荀藍田廳', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["任官經一年，縣與玉峰連。","竹籠拾山果，瓦瓶擔石泉。","客歸秋雨後，印鎖暮鐘前。","久別丹陽浦，時時夢釣船。"]', '["任官經一年，縣與玉峰連。","竹籠拾山果，瓦瓶擔石泉。","客归秋雨後，印鎖暮鐘前。","久別丹陽浦，时时梦釣船。"]', '诗', 'shi', '', NULL, '題皇甫荀藍田廳 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba2d62b4-30f4-47f9-b06a-3dda46ec4c1e', '贈王將軍', '贈王將軍', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["宿衛爐煙近，除書墨未乾。","馬曾金鏃中，身有寶刀瘢。","父子同時捷，君王畫陣看。","何當爲外帥，白日出長安。"]', '["宿衛爐煙近，除书墨未乾。","马曾金鏃中，身有寶刀瘢。","父子同时捷，君王畫陣看。","何當爲外帥，白日出长安。"]', '诗', 'shi', '', NULL, '贈王將軍 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c95bbf5c-9b61-4570-a7db-e786a36b4861', '下第', '下第', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["下第只空囊，如何住帝鄉。","杏園啼百舌，誰醉在花傍。","淚落故山遠，病來春草長。","知音逢豈易，孤棹負三湘。"]', '["下第只空囊，如何住帝乡。","杏园啼百舌，誰醉在花傍。","泪落故山远，病来春草长。","知音逢豈易，孤棹負三湘。"]', '诗', 'shi', '', NULL, '下第 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7530421-4251-4597-a3fd-7f5d713e9aa0', '寄賀蘭朋吉', '寄賀蘭朋吉', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["往往東林下，花香似火焚。","故園從小別，夜雨近秋聞。","野菜連寒水，枯株簇古墳。","泛舟同遠客，尋寺入幽雲。","斜日扉多掩，荒田徑細分。","相思蟬幾處，偶坐蝶成羣。","會宿曾論道，登高省議文。","苦吟遙可想，邊葉向紛紛。"]', '["往往东林下，花香似火焚。","故园從小別，夜雨近秋闻。","野菜連寒水，枯株簇古墳。","泛舟同远客，尋寺入幽云。","斜日扉多掩，荒田徑細分。","相思蟬幾处，偶坐蝶成羣。","會宿曾論道，登高省議文。","苦吟遙可想，邊葉向紛紛。"]', '诗', 'shi', '', NULL, '寄賀蘭朋吉 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e96e000-b517-48c8-a957-bc9394dd7fcf', '憶吳處士', '憶吳处士', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["半夜長安雨，燈前越客吟。","孤舟行一月，萬水與千岑。","島嶼夏雲起，汀洲芳草深。","何當折松葉，拂石剡溪陰。"]', '["半夜长安雨，灯前越客吟。","孤舟行一月，万水與千岑。","島嶼夏云起，汀洲芳草深。","何當折松葉，拂石剡溪陰。"]', '诗', 'shi', '', NULL, '憶吳處士 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee09c928-2f1a-47b2-96da-2e2ba808c8f1', '哭孟郊', '哭孟郊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["身死聲名在，多應萬古傳。","寡妻無子息，破宅帶林泉。","塚近登山道，詩隨過海船。","故人相弔後，斜日下寒天。"]', '["身死声名在，多應万古傳。","寡妻無子息，破宅带林泉。","塚近登山道，诗隨過海船。","故人相弔後，斜日下寒天。"]', '诗', 'shi', '', NULL, '哭孟郊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f44531a-aa6d-4d1f-8233-baf9b01a7413', '送崔定', '送崔定', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["未知遊子意，何不避炎蒸？","幾日到漢水，新蟬鳴杜陵。","秋江待得月，夜語恨無僧。","巴峽吟過否，連天十二層。"]', '["未知游子意，何不避炎蒸？","幾日到漢水，新蟬鳴杜陵。","秋江待得月，夜語恨無僧。","巴峽吟過否，連天十二層。"]', '诗', 'shi', '', NULL, '送崔定 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b16538c8-f5e1-40c8-8dc9-3652646ca912', '寄白閣默公', '寄白閣默公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["已知歸白閣，山遠晚晴看。","石室人心靜，冰潭月影殘。","微雲分片滅，古木落薪乾。","後夜誰聞磬，西峰絕頂寒。"]', '["已知归白閣，山远晚晴看。","石室人心静，冰潭月影殘。","微云分片滅，古木落薪乾。","後夜誰闻磬，西峰絕頂寒。"]', '诗', 'shi', '', NULL, '寄白閣默公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a9c99a9-6234-4b26-88ab-65cfa279db37', '雨後宿劉司馬池上', '雨後宿劉司马池上', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["藍溪秋漱玉，此地漲清澄。","蘆葦聲兼雨，芰荷香遶燈。","岸頭秦古道，亭面漢荒陵。","靜想泉根本，幽崖落幾層。"]', '["藍溪秋漱玉，此地漲清澄。","蘆葦声兼雨，芰荷香遶灯。","岸头秦古道，亭面漢荒陵。","静想泉根本，幽崖落幾層。"]', '诗', 'shi', '', NULL, '雨後宿劉司馬池上 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6c2f2c1-10ce-4b51-b7c9-b79747ee7aea', '送朱可久歸越中', '送朱可久归越中', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["石頭城下泊，北固暝鐘初。","汀鷺潮衝起，船窗月過虛。","吳山侵越衆，隋柳入唐疎。","日欲躬調膳，辟來何府書。"]', '["石头城下泊，北固暝鐘初。","汀鷺潮衝起，船窗月過虛。","吳山侵越衆，隋柳入唐疎。","日欲躬調膳，辟来何府书。"]', '诗', 'shi', '', NULL, '送朱可久歸越中 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('877224c7-59e3-4b74-898e-8ccc947b4be6', '送田卓入華山', '送田卓入华山', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["幽深足暮蟬，驚覺石床眠。","瀑布五千仞，草堂瀑布邊。","壇松涓滴露，嶽月泬寥天。","鶴過君須看，上頭應有仙。"]', '["幽深足暮蟬，驚覺石床眠。","瀑布五千仞，草堂瀑布邊。","壇松涓滴露，嶽月泬寥天。","鹤過君須看，上头應有仙。"]', '诗', 'shi', '', NULL, '送田卓入華山 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcf47c93-2a6a-4ca1-a66d-e7e6954b4f0e', '送董正字常州覲省', '送董正字常州覲省', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["相逐一行鴻，何時出磧中？","江流翻白浪，木葉落青楓。","輕檝浮吳國，繁霜下楚空。","春來懽侍阻，正字在東宮。"]', '["相逐一行鴻，何时出磧中？","江流翻白浪，木葉落青楓。","轻檝浮吳国，繁霜下楚空。","春来懽侍阻，正字在东宮。"]', '诗', 'shi', '', NULL, '送董正字常州覲省 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1163584a-72ee-4aea-bb6c-4f961a6b65dc', '酬姚少府', '酬姚少府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["梅樹與山木，俱應搖落初。","柴門掩寒雨，蟲響出秋蔬。","枯槁彰清鏡，孱愚友道書。","刊文非不朽，君子自相於。"]', '["梅樹與山木，俱應搖落初。","柴门掩寒雨，蟲响出秋蔬。","枯槁彰清镜，孱愚友道书。","刊文非不朽，君子自相於。"]', '诗', 'shi', '', NULL, '酬姚少府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('520cffaf-ac95-4ead-ac6c-270a257614ff', '送無可上人', '送無可上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["圭峰霽色新，送此草堂人。","麈尾同離寺，蛩鳴暫別親。","獨行潭底影，數息樹邊身。","終有煙霞約，天台作近鄰。"]', '["圭峰霽色新，送此草堂人。","麈尾同離寺，蛩鳴暫別親。","独行潭底影，數息樹邊身。","終有煙霞約，天台作近鄰。"]', '诗', 'shi', '', NULL, '送無可上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475f81aa-cfd7-4d6b-9ba7-03376f000cab', '送李騎曹', '送李騎曹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["歸騎雙旌遠，懽生此別中。","蕭關分磧路，嘶馬背寒鴻。","朔色晴天北，河源落日東。","賀蘭山頂草，時動捲帆風。"]', '["归騎雙旌远，懽生此別中。","蕭关分磧路，嘶马背寒鴻。","朔色晴天北，河源落日东。","賀蘭山頂草，时动捲帆风。"]', '诗', 'shi', '', NULL, '送李騎曹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eadab97a-5345-4046-96da-d092c663ca3f', '送烏行中石淙別業', '送烏行中石淙別業', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寒水長繩汲，丁泠數滴翻。","草通石淙脈，硯帶海潮痕。","嶽色何曾遠，蟬聲尚未繁。","勞思當此夕，苗稼在西原。"]', '["寒水长繩汲，丁泠數滴翻。","草通石淙脈，硯带海潮痕。","嶽色何曾远，蟬声尚未繁。","勞思當此夕，苗稼在西原。"]', '诗', 'shi', '', NULL, '送烏行中石淙別業 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d92e0a-8fd7-4951-bd59-33134742bd11', '送覺興上人歸中條山兼謁河中李司空', '送覺兴上人归中條山兼謁河中李司空', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["又憶西巖寺，秦原草白時。","山尋樵徑上，人到雪房遲。","暮磬潭泉凍，荒林野燒移。","聞師新譯偈，說擬對旌麾。"]', '["又憶西巖寺，秦原草白时。","山尋樵徑上，人到雪房遲。","暮磬潭泉凍，荒林野燒移。","闻師新譯偈，说擬对旌麾。"]', '诗', 'shi', '', NULL, '送覺興上人歸中條山兼謁河中李司空 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ab3a0ff-5a99-44fd-bf3e-f06a29d2a0cb', '寄無可上人', '寄無可上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["僻寺多高樹，涼天憶重遊。","磬過溝水盡，月入草堂秋。","穴蟻苔痕靜，藏蟬柏葉稠。","名山思徧往，早晚到嵩丘。"]', '["僻寺多高樹，涼天憶重游。","磬過溝水尽，月入草堂秋。","穴蟻苔痕静，藏蟬柏葉稠。","名山思徧往，早晚到嵩丘。"]', '诗', 'shi', '', NULL, '寄無可上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27bb97a5-6af3-4284-a86a-edfc8d90e65e', '南池', '南池', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["蕭條微雨絕，荒岸抱清源。","入舫山侵塞，分泉稻接村。","秋聲依樹色，月影在蒲根。","淹泊方難遂，他宵關夢魂。"]', '["蕭條微雨絕，荒岸抱清源。","入舫山侵塞，分泉稻接村。","秋声依樹色，月影在蒲根。","淹泊方难遂，他宵关梦魂。"]', '诗', 'shi', '', NULL, '南池 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0689c43-8cc5-41b4-bee3-9f6308c1346f', '寄龍池寺貞空二上人', '寄龙池寺貞空二上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["受請終南住，俱妨去石橋。","林中秋信絕，峰頂夜禪遙。","寒草煙藏虎，高松月照鵰。","霜天期到寺，寺置即前朝。"]', '["受請終南住，俱妨去石橋。","林中秋信絕，峰頂夜禪遙。","寒草煙藏虎，高松月照鵰。","霜天期到寺，寺置即前朝。"]', '诗', 'shi', '', NULL, '寄龍池寺貞空二上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d59a13-1244-4185-b60c-4d154417e3ce', '送貞空二上人', '送貞空二上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["林下中餐後，天涯欲去時。","衡陽過有伴，夢澤出應遲。","石磬疎寒韻，銅瓶結夜澌。","殷勤訝此別，且未定歸期。"]', '["林下中餐後，天涯欲去时。","衡陽過有伴，梦澤出應遲。","石磬疎寒韻，銅瓶結夜澌。","殷勤訝此別，且未定归期。"]', '诗', 'shi', '', NULL, '送貞空二上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa82d5d0-1912-4895-a206-9c96ac130b1e', '送裴校書', '送裴校书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["拜官從祕省，署職在藩維。","多故長疎索，高秋遠別離。","天寒泗上醉，夜靜岳陽碁。","使府臨南海，帆飛到不遲。"]', '["拜官從祕省，署職在藩維。","多故长疎索，高秋远別離。","天寒泗上醉，夜静岳陽碁。","使府臨南海，帆飞到不遲。"]', '诗', 'shi', '', NULL, '送裴校書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86c5d034-0007-4cf0-9767-95a934c7a3ed', '昇道精舍南臺對月寄姚合', '昇道精舍南台对月寄姚合', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["月向南臺見，秋霖洗滌餘。","出逢危葉落，靜看衆峰疎。","[冷]露常時有，禪窗此夜虛。","相思聊悵望，潤氣徧衣初。"]', '["月向南台见，秋霖洗滌餘。","出逢危葉落，静看衆峰疎。","[冷]露常时有，禪窗此夜虛。","相思聊悵望，潤氣徧衣初。"]', '诗', 'shi', '', NULL, '昇道精舍南臺對月寄姚合 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8726f662-01ec-4acc-8edd-186797b7a81a', '即事', '即事', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["索莫對孤燈，陰雲積幾層。","自嗟憐十上，誰肯待三徵。","心被通人見，文叨大匠稱。","悲秋秦塞草，懷古漢家陵。","城靜高崖樹，漏多幽沼冰。","過聲沙島鷺，絕行石菴僧。","豈謂舊廬在，誰言歸未曾。"]', '["索莫对孤灯，陰云積幾層。","自嗟怜十上，誰肯待三徵。","心被通人见，文叨大匠稱。","悲秋秦塞草，懷古漢家陵。","城静高崖樹，漏多幽沼冰。","過声沙島鷺，絕行石菴僧。","豈謂旧廬在，誰言归未曾。"]', '诗', 'shi', '', NULL, '即事 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98e803f0-7681-439a-b725-abf4636ca6a1', '黃子陂上韓吏部', '黄子陂上韓吏部', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["石樓云一別，二十二三春。","相逐升堂者，幾爲埋骨人。","涕流聞度瘴，病起喜還秦。","曾是令勤道，非惟卹在迍。","疎衣蕉縷細，爽味茗芽新。","鐘絕滴殘雨，螢多無近鄰。","溪潭承到數，位秩見辭頻。","若箇山招隱，機忘任此身。"]', '["石楼云一別，二十二三春。","相逐升堂者，幾爲埋骨人。","涕流闻度瘴，病起喜還秦。","曾是令勤道，非惟卹在迍。","疎衣蕉縷細，爽味茗芽新。","鐘絕滴殘雨，螢多無近鄰。","溪潭承到數，位秩见辞頻。","若箇山招隐，機忘任此身。"]', '诗', 'shi', '', NULL, '黃子陂上韓吏部 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1743caa3-080c-47ad-ace6-827aa47a0385', '投李益', '投李益', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["四十歸燕字，千年外始吟。","已將書北嶽，不用比南金。"]', '["四十归燕字，千年外始吟。","已將书北嶽，不用比南金。"]', '诗', 'shi', '', NULL, '投李益 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c94bedaa-949f-4c8d-b08e-b4ed20427ffd', '弔孟協律', '弔孟協律', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["才行古人齊，生前品位低。","葬時貧賣馬，遠日哭惟妻。","孤塚北邙外，空齋中嶽西。","集詩應萬首，物象徧曾題。"]', '["才行古人齊，生前品位低。","葬时貧賣马，远日哭惟妻。","孤塚北邙外，空斋中嶽西。","集诗應万首，物象徧曾題。"]', '诗', 'shi', '', NULL, '弔孟協律 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9498e20a-e4c1-407c-8e26-ce64e03797dc', '送人適越', '送人適越', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["高城滿夕陽，何事欲霑裳。","遷客蓬蒿暮，遊人道路長。","晴湖勝鏡碧，寒柳似金黃。","若有相思夢，殷勤載八行。"]', '["高城满夕陽，何事欲霑裳。","遷客蓬蒿暮，游人道路长。","晴湖勝镜碧，寒柳似金黄。","若有相思梦，殷勤載八行。"]', '诗', 'shi', '', NULL, '送人適越 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72cda914-6b8f-416a-bd38-f47ca67f1c39', '送僧遊衡嶽', '送僧游衡嶽', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["心知衡嶽路，不怕去人稀。","船裏猶鳴磬，溪頭自曝衣。","有家從小別，無寺不言歸。","料得逢寒住，當禪雪滿扉。"]', '["心知衡嶽路，不怕去人稀。","船裏猶鳴磬，溪头自曝衣。","有家從小別，無寺不言归。","料得逢寒住，當禪雪满扉。"]', '诗', 'shi', '', NULL, '送僧遊衡嶽 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5202208a-d7c1-4f14-b4c8-da431d8569a8', '送路', '送路', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["別我就蓬蒿，日斜飛伯勞。","龍門流水急，嵩岳片雲高。","歎命無知己，梳頭落白毛。","從軍當此去，風起廣陵濤。"]', '["別我就蓬蒿，日斜飞伯勞。","龙门流水急，嵩岳片云高。","歎命無知己，梳头落白毛。","從軍當此去，风起廣陵濤。"]', '诗', 'shi', '', NULL, '送路 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84edfc9b-e4cf-4fa5-9855-456303efeee2', '洛陽道中寄弟', '洛陽道中寄弟', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["趨走迫流年，慙經此路偏。","密雲埋二室，積雪度三川。","生類梗萍泛，悲無金石堅。","翻鴻有歸翼，極目仰聯翩。"]', '["趨走迫流年，慙經此路偏。","密云埋二室，積雪度三川。","生類梗萍泛，悲無金石堅。","翻鴻有归翼，極目仰聯翩。"]', '诗', 'shi', '', NULL, '洛陽道中寄弟 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52be87fc-2013-4cad-a6ba-c210115f6fd0', '登江亭晚望', '登江亭晚望', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["浩渺浸雲根，煙嵐沒遠村。","鳥歸沙有跡，帆過浪無痕。","望水知柔性，看山欲倦魂。","縱情猶未已，迴馬欲黃昏。"]', '["浩渺浸云根，煙嵐沒远村。","鸟归沙有跡，帆過浪無痕。","望水知柔性，看山欲倦魂。","縱情猶未已，迴马欲黄昏。"]', '诗', 'shi', '', NULL, '登江亭晚望 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d647571-a2ad-4007-b3f5-826171647db8', '送耿處士', '送耿处士', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一瓶離別酒，未盡即言行。","萬水千山路，孤舟幾月程。","川原秋色靜，蘆葦晚風鳴。","迢遰不歸客，人傳虛隱名。"]', '["一瓶離別酒，未尽即言行。","万水千山路，孤舟幾月程。","川原秋色静，蘆葦晚风鳴。","迢遰不归客，人傳虛隐名。"]', '诗', 'shi', '', NULL, '送耿處士 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652003fa-7b9b-4cb7-b507-985c3a2d9089', '過唐校書書齋', '過唐校书书斋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["池滿風吹竹，時時得爽神。","聲齊雛鳥語，畫卷老僧真。","月出行幾步，花開到四鄰。","江湖心自切，未可挂頭巾。"]', '["池满风吹竹，时时得爽神。","声齊雛鸟語，畫卷老僧真。","月出行幾步，花开到四鄰。","江湖心自切，未可挂头巾。"]', '诗', 'shi', '', NULL, '過唐校書書齋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80711255-f575-4d15-ba78-04a36e2d7c12', '送杜秀才東遊', '送杜秀才东游', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["東遊誰見待，盡室寄長安。","別後葉頻落，去程山已寒。","大河風色度，曠野燒煙殘。","匣有青銅鏡，時將照鬢看。"]', '["东游誰见待，尽室寄长安。","別後葉頻落，去程山已寒。","大河风色度，曠野燒煙殘。","匣有青銅镜，时將照鬢看。"]', '诗', 'shi', '', NULL, '送杜秀才東遊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9caf782-4bac-45c2-8205-3ec69dcb948c', '送天台僧', '送天台僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["遠夢歸華頂，扁舟背岳陽。","寒蔬修淨食，夜浪動禪床。","鴈過孤峰曉，猨啼一樹霜。","身心無別念，餘習在詩章。"]', '["远梦归华頂，扁舟背岳陽。","寒蔬修淨食，夜浪动禪床。","鴈過孤峰晓，猨啼一樹霜。","身心無別念，餘習在诗章。"]', '诗', 'shi', '', NULL, '送天台僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c7f373b-10ed-48ac-bd37-620690935386', '懷紫閣隱者', '懷紫閣隐者', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寂寥思隱者，孤燭坐秋霖。","梨栗猨喜熟，雲山僧說深。","寄書應不到，結伴擬同尋。","廢寢方終夕，迢迢紫閣心。"]', '["寂寥思隐者，孤燭坐秋霖。","梨栗猨喜熟，云山僧说深。","寄书應不到，結伴擬同尋。","廢寢方終夕，迢迢紫閣心。"]', '诗', 'shi', '', NULL, '懷紫閣隱者 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e2be323-14cf-47fc-8c8d-c43e3d036fc8', '雨夜同厲玄懷皇甫荀', '雨夜同厲玄懷皇甫荀', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["桐竹遶庭匝，雨多風更吹。","還如舊山夜，臥聽瀑泉時。","磧鴈來期近，秋鐘到夢遲。","溝西吟苦客，中夕話兼思。"]', '["桐竹遶庭匝，雨多风更吹。","還如旧山夜，臥听瀑泉时。","磧鴈来期近，秋鐘到梦遲。","溝西吟苦客，中夕話兼思。"]', '诗', 'shi', '', NULL, '雨夜同厲玄懷皇甫荀 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa1f13cf-fc73-4c9f-942d-6c87d8a76f09', '秋暮', '秋暮', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["北門楊柳葉，不覺已繽紛。","值鶴因臨水，迎僧忽背雲。","白鬚相並出，清淚兩行分。","默默空朝夕，苦吟誰喜聞。"]', '["北门楊柳葉，不覺已繽紛。","值鹤因臨水，迎僧忽背云。","白鬚相並出，清泪兩行分。","默默空朝夕，苦吟誰喜闻。"]', '诗', 'shi', '', NULL, '秋暮 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a495857d-bd17-446a-80cb-50eed7ff7c6c', '哭胡遇', '哭胡遇', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["夭壽知齊理，何曾免歎嗟。","祭迴收朔雪，弔後折寒花。","野水秋吟斷，空山暮影斜。","弟兄相識徧，猶得到君家。"]', '["夭壽知齊理，何曾免歎嗟。","祭迴收朔雪，弔後折寒花。","野水秋吟斷，空山暮影斜。","弟兄相識徧，猶得到君家。"]', '诗', 'shi', '', NULL, '哭胡遇 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53611cf-b7d8-403a-bc3f-e1f29977fbee', '送丹師歸閩中', '送丹師归閩中', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["波濤路杳然，衰柳落陽蟬。","行李經雷電，禪前漱島泉。","歸林久別寺，過越未離船。","自說從今去，身應老海邊。"]', '["波濤路杳然，衰柳落陽蟬。","行李經雷電，禪前漱島泉。","归林久別寺，過越未離船。","自说從今去，身應老海邊。"]', '诗', 'shi', '', NULL, '送丹師歸閩中 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24be512b-9298-4f49-bc63-cd643f3cc05b', '送安南惟鑒法師', '送安南惟鑒法師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["講經春殿裏，花遶御牀飛。","南海幾迴渡，舊山臨老歸。","潮搖蠻草落，月溼島松微。","空水既如彼，往來消息稀。"]', '["講經春殿裏，花遶御牀飞。","南海幾迴渡，旧山臨老归。","潮搖蠻草落，月溼島松微。","空水既如彼，往来消息稀。"]', '诗', 'shi', '', NULL, '送安南惟鑒法師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b07455d5-c662-4c95-ae96-d4d106a43db0', '題李凝幽居', '題李凝幽居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["閑居少鄰並，草徑入荒園。","鳥宿池邊樹，僧敲月下門。","過橋分野色，移石動雲根。","暫去還來此，幽期不負言。"]', '["闲居少鄰並，草徑入荒园。","鸟宿池邊樹，僧敲月下门。","過橋分野色，移石动云根。","暫去還来此，幽期不負言。"]', '诗', 'shi', '', NULL, '題李凝幽居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa02218e-77f2-4a1a-b14d-6df92ca49d68', '送韓湘', '送韓湘', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["挂席從古路，長風起廣津。","楚城花未發，上苑蝶來新。","半沒湖波月，初生島草春。","孤霞臨石鏡，極浦映村神。","細響吟乾葦，餘馨動遠蘋。","欲憑將一札，寄與沃洲人。"]', '["挂席從古路，长风起廣津。","楚城花未發，上苑蝶来新。","半沒湖波月，初生島草春。","孤霞臨石镜，極浦映村神。","細响吟乾葦，餘馨动远蘋。","欲憑將一札，寄與沃洲人。"]', '诗', 'shi', '', NULL, '送韓湘 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ce72d5e-b764-409b-8886-ebc4263fe5f0', '寄董武', '寄董武', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["雖同一城裏，少省得從容。","門掩園林僻，日高巾幘慵。","孤鴻來半夜，積雪在諸峰。","正憶毗陵客，聲聲隔水鐘。"]', '["雖同一城裏，少省得從容。","门掩园林僻，日高巾幘慵。","孤鴻来半夜，積雪在諸峰。","正憶毗陵客，声声隔水鐘。"]', '诗', 'shi', '', NULL, '寄董武 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b5ba16-e3ab-4278-85a7-e0fa89c05a95', '宿贇上人房', '宿贇上人房', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["堦前多是竹，閑地擬栽松。","朱點草書疏，雪平麻履蹤。","御溝寒夜雨，宮寺靜時鐘。","此時無他事，來尋不厭重。"]', '["堦前多是竹，闲地擬栽松。","朱点草书疏，雪平麻履蹤。","御溝寒夜雨，宮寺静时鐘。","此时無他事，来尋不厭重。"]', '诗', 'shi', '', NULL, '宿贇上人房 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('645e508e-1b7d-4d83-bef0-36e0717a84f5', '訪李甘原居', '訪李甘原居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["原西居處靜，門對曲江開。","石縫銜枯草，查根上淨苔。","翠微泉夜落，紫閣鳥時來。","仍憶尋淇岸，同行採蕨回。"]', '["原西居处静，门对曲江开。","石縫銜枯草，查根上淨苔。","翠微泉夜落，紫閣鸟时来。","仍憶尋淇岸，同行採蕨回。"]', '诗', 'shi', '', NULL, '訪李甘原居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baee2bfa-ce98-4977-87d4-efe149414075', '題山寺井', '題山寺井', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["沈沈百尺餘，功就豈斯須。","汲早僧出定，鑿新蟲自無。","藏源重嶂底，澄翳大空隅。","此地如經劫，涼潭會共枯。"]', '["沈沈百尺餘，功就豈斯須。","汲早僧出定，鑿新蟲自無。","藏源重嶂底，澄翳大空隅。","此地如經劫，涼潭會共枯。"]', '诗', 'shi', '', NULL, '題山寺井 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5e1618-f686-49a6-a7b0-1968961d8126', '僻居無可上人相訪', '僻居無可上人相訪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["自從居此地，少有事相關。","積雨荒鄰圃，秋池照遠山。","硯中枯葉落，枕上斷雲閑。","野客將禪子，依依偏往還。"]', '["自從居此地，少有事相关。","積雨荒鄰圃，秋池照远山。","硯中枯葉落，枕上斷云闲。","野客將禪子，依依偏往還。"]', '诗', 'shi', '', NULL, '僻居無可上人相訪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef3783fc-5ab0-47a9-9cf2-6636673b4c0d', '送李餘及第歸蜀', '送李餘及第归蜀', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["知音伸久屈，覲省去光輝。","津渡逢清夜，途程盡翠微。","雲當绵竹疊，鳥離錦江飛。","肯寄書來否，原居出亦稀。"]', '["知音伸久屈，覲省去光輝。","津渡逢清夜，途程尽翠微。","云當绵竹叠，鸟離錦江飞。","肯寄书来否，原居出亦稀。"]', '诗', 'shi', '', NULL, '送李餘及第歸蜀 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5bb58de-5bb7-44eb-b7c8-0ffd78d41fe4', '荒齋', '荒斋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["草合徑微微，終南對掩扉。","晚涼疎雨絕，初曉遠山稀。","落葉無青地，閑身著白衣。","朴愚猶本性，不是學忘機。"]', '["草合徑微微，終南对掩扉。","晚涼疎雨絕，初晓远山稀。","落葉無青地，闲身著白衣。","朴愚猶本性，不是学忘機。"]', '诗', 'shi', '', NULL, '荒齋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8a64073-762b-49e0-88ce-10fcc94fd36b', '夜喜賀蘭三見訪', '夜喜賀蘭三见訪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["漏鐘仍夜淺，時節欲秋分。","泉聒棲松鶴，風除翳月雲。","踏苔行引興，枕石臥論文。","即此尋常靜，來多秖是君。"]', '["漏鐘仍夜淺，时節欲秋分。","泉聒棲松鹤，风除翳月云。","踏苔行引兴，枕石臥論文。","即此尋常静，来多秖是君。"]', '诗', 'shi', '', NULL, '夜喜賀蘭三見訪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d577b03-e57f-49b2-8a4a-d31a424e863f', '題青龍寺鏡公房', '題青龙寺镜公房', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一夕曾留宿，終南搖落時。","孤燈岡舍掩，殘磬雪風吹。","樹老因寒折，泉深出井遲。","疎慵豈有事，多失上方期。"]', '["一夕曾留宿，終南搖落时。","孤灯岡舍掩，殘磬雪风吹。","樹老因寒折，泉深出井遲。","疎慵豈有事，多失上方期。"]', '诗', 'shi', '', NULL, '題青龍寺鏡公房 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c861994-a47a-445b-a47b-e16ae0094027', '送陳判官赴綏德', '送陳判官赴綏德', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["將軍邀入幕，束帶便離家。","身暖蕉衣窄，天寒磧日斜。","火燒岡斷葦，風卷雪平沙。","絲竹豐州有，春來秖欠花。"]', '["將軍邀入幕，束带便離家。","身暖蕉衣窄，天寒磧日斜。","火燒岡斷葦，风卷雪平沙。","絲竹豐州有，春来秖欠花。"]', '诗', 'shi', '', NULL, '送陳判官赴綏德 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbb5fb8-d224-4d6f-a0ad-ef81d3424aba', '送唐環歸敷水莊', '送唐环归敷水莊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["毛女峰當戶，日高頭未梳。","地侵山影掃，葉帶露痕書。","松徑僧尋藥，沙泉鶴見魚。","一川風景好，恨不有吾廬。"]', '["毛女峰當戶，日高头未梳。","地侵山影掃，葉带露痕书。","松徑僧尋藥，沙泉鹤见鱼。","一川风景好，恨不有吾廬。"]', '诗', 'shi', '', NULL, '送唐環歸敷水莊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7a92e56-f5a9-4b2c-81f3-e8bf88210878', '原東居喜唐溫琪頻至', '原东居喜唐溫琪頻至', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曲江春草生，紫閣雪分明。","汲井嘗泉味，聽鐘問寺名。","墨研秋日雨，茶試老僧鐺。","地近勞頻訪，烏紗出送迎。"]', '["曲江春草生，紫閣雪分明。","汲井嘗泉味，听鐘问寺名。","墨研秋日雨，茶試老僧鐺。","地近勞頻訪，烏紗出送迎。"]', '诗', 'shi', '', NULL, '原東居喜唐溫琪頻至 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23818817-a8c2-4a52-a995-0f84dd5b548e', '送敭法師', '送敭法師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["度歲不相見，嚴冬始出關。","孤煙寒色樹，高雪夕陽山。","瀑布寺應到，牡丹房甚閑。","南朝遺跡在，此去幾時還。"]', '["度歲不相见，嚴冬始出关。","孤煙寒色樹，高雪夕陽山。","瀑布寺應到，牡丹房甚闲。","南朝遺跡在，此去幾时還。"]', '诗', 'shi', '', NULL, '送敭法師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('848c0ab5-600d-4e80-8b02-db52bf525cbe', '寄錢庶子', '寄錢庶子', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曲江春水滿，北岸掩柴關。","秖有僧鄰舍，全無物映山。","樹陰終日掃，藥債隔年還。","猶記聽琴夜，寒燈竹屋間。"]', '["曲江春水满，北岸掩柴关。","秖有僧鄰舍，全無物映山。","樹陰終日掃，藥債隔年還。","猶記听琴夜，寒灯竹屋间。"]', '诗', 'shi', '', NULL, '寄錢庶子 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5df71537-93fd-43c0-be60-4bef5bf1910a', '原上秋居', '原上秋居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["關西又落木，心事復如何。","歲月辭山久，秋霖入夜多。","鳥從井口出，人自洛陽過。","倚杖聊閑望，田家未翦禾。"]', '["关西又落木，心事复如何。","歲月辞山久，秋霖入夜多。","鸟從井口出，人自洛陽過。","倚杖聊闲望，田家未翦禾。"]', '诗', 'shi', '', NULL, '原上秋居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1743d87-b29d-448f-b00d-60a242f8a1fa', '夏夜', '夏夜', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["原寺偏鄰近，開門物景澄。","磬通多葉罅，月離片雲稜。","寄宿山中鳥，相尋海畔僧。","唯愁秋色至，乍可在炎蒸。"]', '["原寺偏鄰近，开门物景澄。","磬通多葉罅，月離片云稜。","寄宿山中鸟，相尋海畔僧。","唯愁秋色至，乍可在炎蒸。"]', '诗', 'shi', '', NULL, '夏夜 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('944a04d7-eac2-4092-9258-12a275a3b530', '冬夜', '冬夜', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["羈旅復經冬，瓢空盎亦空。","淚流寒枕上，跡絕舊山中。","淩結浮萍水，雪和衰柳風。","曙光雞未報，嘹唳兩三鴻。"]', '["羈旅复經冬，瓢空盎亦空。","泪流寒枕上，跡絕旧山中。","淩結浮萍水，雪和衰柳风。","曙光雞未報，嘹唳兩三鴻。"]', '诗', 'shi', '', NULL, '冬夜 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa55078f-c074-4710-b32d-dc9968a3765e', '送厲宗上人', '送厲宗上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["擁策背岷峨，終南雨雪和。","漱泉秋鶴至，禪樹夜猨過。","高頂白雲盡，前山黃葉多。","曾吟廬嶽上，月動九江波。"]', '["擁策背岷峨，終南雨雪和。","漱泉秋鹤至，禪樹夜猨過。","高頂白云尽，前山黄葉多。","曾吟廬嶽上，月动九江波。"]', '诗', 'shi', '', NULL, '送厲宗上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76b51be2-877b-40c3-b694-344892b49348', '寄李存穆', '寄李存穆', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["聞道船中病，似憂親弟兄。","信來從水路，身去到柴城。","久別長鬚鬢，相思書姓名。","忽然消息絕，頻夢却還京。"]', '["闻道船中病，似憂親弟兄。","信来從水路，身去到柴城。","久別长鬚鬢，相思书姓名。","忽然消息絕，頻梦却還京。"]', '诗', 'shi', '', NULL, '寄李存穆 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb1d5e4-aee8-4d9e-a49f-d52160c74058', '贈無懷禪師', '贈無懷禪師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["身從劫劫修，果以此生周。","禪定石床暖，月移山樹秋。","捧盂觀宿飯，敲磬過清流。","不掩玄關路，敎人問白頭。"]', '["身從劫劫修，果以此生周。","禪定石床暖，月移山樹秋。","捧盂观宿飯，敲磬過清流。","不掩玄关路，敎人问白头。"]', '诗', 'shi', '', NULL, '贈無懷禪師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab87d158-11a5-4d10-92bc-14d33eb4a530', '寄武功姚主簿', '寄武功姚主簿', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["居枕江沱北，情懸渭曲西。","數宵曾夢見，幾處得書披。","驛路穿荒坂，公田帶淤泥。","靜棊功奧妙，閑作韻清淒。","鋤草留叢藥，尋山上石梯。","客迴河水漲，風起夕陽低。","空地苔連井，孤村火隔溪。","卷簾黃葉落，鎖印子規啼。","隴色澄秋月，邊聲入戰鼙。","會須過縣去，況是屢招攜。"]', '["居枕江沱北，情懸渭曲西。","數宵曾梦见，幾处得书披。","驛路穿荒坂，公田带淤泥。","静棊功奧妙，闲作韻清淒。","鋤草留叢藥，尋山上石梯。","客迴河水漲，风起夕陽低。","空地苔連井，孤村火隔溪。","卷簾黄葉落，鎖印子規啼。","隴色澄秋月，邊声入戰鼙。","會須過縣去，況是屢招携。"]', '诗', 'shi', '', NULL, '寄武功姚主簿 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e26074a2-a61a-4b6b-8d63-fd329f3e52b5', '題劉華書齋', '題劉华书斋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["白石床無塵，青松樹有鱗。","一鶯啼帶雨，兩樹合從春。","荒榭苔膠砌，幽叢果墮榛。","偶來疎或數，當暑夕勝晨。","露滴星河水，巢重草木薪。","終南同往意，趙北獨遊身。","渡葉司天漏，驚蛩遠地人。","機清公幹族，也莫臥漳濱。"]', '["白石床無塵，青松樹有鱗。","一鶯啼带雨，兩樹合從春。","荒榭苔膠砌，幽叢果墮榛。","偶来疎或數，當暑夕勝晨。","露滴星河水，巢重草木薪。","終南同往意，趙北独游身。","渡葉司天漏，驚蛩远地人。","機清公幹族，也莫臥漳濱。"]', '诗', 'shi', '', NULL, '題劉華書齋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c720ab58-0a69-4033-a325-fc1c1105680f', '送盧秀才遊潞府', '送盧秀才游潞府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["雨餘滋潤在，風不起塵沙。","邊日寡文思，送君吟月華。","過山干相府，臨水宿僧家。","能賦焉長屈，芳春宴杏花。"]', '["雨餘滋潤在，风不起塵沙。","邊日寡文思，送君吟月华。","過山干相府，臨水宿僧家。","能賦焉长屈，芳春宴杏花。"]', '诗', 'shi', '', NULL, '送盧秀才遊潞府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93bad2e8-a7c3-44d5-aec1-5a0664e90905', '送南康姚明府', '送南康姚明府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["銅章美少年，小邑在南天。","版籍多遷客，封疆接洞田。","靜江鳴野鼓，發纜帶村煙。","却笑陶元亮，何須憶醉眠。"]', '["銅章美少年，小邑在南天。","版籍多遷客，封疆接洞田。","静江鳴野鼓，發纜带村煙。","却笑陶元亮，何須憶醉眠。"]', '诗', 'shi', '', NULL, '送南康姚明府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abc7de1d-6726-441e-8282-a2d58e6558bf', '送友人棄官遊江左', '送友人棄官游江左', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["羨君休作尉，萬事且全身。","寰海多虞日，江湖獨往人。","姓名何處變，鷗鳥幾時親。","別後吳中使，應須訪子真。"]', '["羨君休作尉，万事且全身。","寰海多虞日，江湖独往人。","姓名何处变，鷗鸟幾时親。","別後吳中使，應須訪子真。"]', '诗', 'shi', '', NULL, '送友人棄官遊江左 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2cabd75-5b60-47d9-868b-7de24329db65', '雨中懷友人', '雨中懷友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["對雨思君子，嘗茶近竹幽。","儒家鄰古寺，不到又逢秋。"]', '["对雨思君子，嘗茶近竹幽。","儒家鄰古寺，不到又逢秋。"]', '诗', 'shi', '', NULL, '雨中懷友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f5ea03-9eef-4394-aa3d-031520ed58c4', '寄遠', '寄远', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["家住錦水上，身征遼海邊。","十書九不到，一到忽經年。"]', '["家住錦水上，身征遼海邊。","十书九不到，一到忽經年。"]', '诗', 'shi', '', NULL, '寄遠 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b137d820-afec-45b7-b5b7-634540fe1dd7', '南齋', '南斋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["獨自南齋臥，神閑景亦空。","有山來枕上，無事到心中。","簾卷侵牀月，屏遮入座風。","望春春未至，應在海門東。"]', '["独自南斋臥，神闲景亦空。","有山来枕上，無事到心中。","簾卷侵牀月，屏遮入座风。","望春春未至，應在海门东。"]', '诗', 'shi', '', NULL, '南齋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f719b3-cded-4cc2-992e-9da94308eab5', '早春題友人湖上新居二首 一', '早春題友人湖上新居二首 一', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["近得雲中路，門長侵早開。","到時猶有雪，行處已無苔。","勸酒客初醉，留茶僧未來。","每逢晴暖日，惟見乞花栽。"]', '["近得云中路，门长侵早开。","到时猶有雪，行处已無苔。","勸酒客初醉，留茶僧未来。","每逢晴暖日，惟见乞花栽。"]', '诗', 'shi', '', NULL, '早春題友人湖上新居二首 一 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9687e261-4583-4bd7-b9db-664755939a85', '早春題友人湖上新居二首 二', '早春題友人湖上新居二首 二', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["門不當官道，行人到亦稀。","故從餐後出，多是夜深歸。","開篋收詩卷，掃牀移臥衣。","幾時同買宅，相送有柴扉。"]', '["门不當官道，行人到亦稀。","故從餐後出，多是夜深归。","开篋收诗卷，掃牀移臥衣。","幾时同買宅，相送有柴扉。"]', '诗', 'shi', '', NULL, '早春題友人湖上新居二首 二 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1c41f4d-5352-4782-b5e6-09279f6337b6', '送雍陶入蜀', '送雍陶入蜀', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["江山事若諳，那肯滯雲南。","草色分危磴，杉陰近古潭。","日斜襃谷鳥，夏淺巂州蠶。","吾自疑雙鬢，相逢更不堪。"]', '["江山事若諳，那肯滯云南。","草色分危磴，杉陰近古潭。","日斜襃谷鸟，夏淺巂州蠶。","吾自疑雙鬢，相逢更不堪。"]', '诗', 'shi', '', NULL, '送雍陶入蜀 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9f439a-bd51-46c5-8788-5aaad8d7f456', '張郎中過原東居', '張郎中過原东居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["年長惟添嬾，經旬止掩關。","高人餐藥後，下馬此林間。","對坐天將暮，同來客亦閑。","幾時能重至，水味似深山。"]', '["年长惟添嬾，經旬止掩关。","高人餐藥後，下马此林间。","对坐天將暮，同来客亦闲。","幾时能重至，水味似深山。"]', '诗', 'shi', '', NULL, '張郎中過原東居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db84e11f-1ab6-4997-963b-3b9bde8ec214', '荅王建祕書', '荅王建祕书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["人皆聞蟋蟀，我獨恨蹉跎。","白髮無心鑷，青山去意多。","信來漳浦岸，期負洞庭波。","時掃高槐影，朝迴或恐過。"]', '["人皆闻蟋蟀，我独恨蹉跎。","白髮無心鑷，青山去意多。","信来漳浦岸，期負洞庭波。","时掃高槐影，朝迴或恐過。"]', '诗', 'shi', '', NULL, '荅王建祕書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('627003df-142e-4868-afdf-a90dcc4a9112', '送李餘往湖南', '送李餘往湖南', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["昔去候溫涼，秋山滿楚鄉。","今來從辟命，春物徧涔陽。","岳石挂海雪，野楓堆渚檣。","若尋吾祖宅，寂寞在瀟湘。"]', '["昔去候溫涼，秋山满楚乡。","今来從辟命，春物徧涔陽。","岳石挂海雪，野楓堆渚檣。","若尋吾祖宅，寂寞在瀟湘。"]', '诗', 'shi', '', NULL, '送李餘往湖南 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a91950e-3ffc-4b62-abd5-51d113aeeacd', '偶作', '偶作', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["野步隨吾意，那知是與非。","稔年時雨足，閏月暮蟬稀。","獨樹依岡老，遙峰出草微。","園林自有主，宿鳥且同歸。"]', '["野步隨吾意，那知是與非。","稔年时雨足，閏月暮蟬稀。","独樹依岡老，遙峰出草微。","园林自有主，宿鸟且同归。"]', '诗', 'shi', '', NULL, '偶作 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55a5663c-3a12-431d-9ef0-df39bcf59f5c', '過雍秀才居', '過雍秀才居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["夏木鳥巢邊，終南嶺色鮮。","就涼安坐石，煮茗汲鄰泉。","鐘遠清霄半，蜩稀暑雨前。","幽齋如葺罷，約我一來眠。"]', '["夏木鸟巢邊，終南嶺色鲜。","就涼安坐石，煮茗汲鄰泉。","鐘远清霄半，蜩稀暑雨前。","幽斋如葺罷，約我一来眠。"]', '诗', 'shi', '', NULL, '過雍秀才居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1bd198b-bb8c-4d32-b8ad-8a2db6a44474', '寄顧非熊', '寄顧非熊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["知君歸有處，山水亦難齊。","猶去瀟湘遠，不聞猨狖啼。","穴通茆嶺下，潮滿石頭西。","獨立生遙思，秋原日漸低。"]', '["知君归有处，山水亦难齊。","猶去瀟湘远，不闻猨狖啼。","穴通茆嶺下，潮满石头西。","独立生遙思，秋原日漸低。"]', '诗', 'shi', '', NULL, '寄顧非熊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e81417d-ccba-45dd-b919-e887cf3214da', '送神邈法師', '送神邈法師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["柳絮落濛濛，西州道路中。","相逢春忽盡，獨去講初終。","行疾遙山雨，眠遲後夜風。","繞房三兩樹，迴日葉應紅。"]', '["柳絮落濛濛，西州道路中。","相逢春忽尽，独去講初終。","行疾遙山雨，眠遲後夜风。","繞房三兩樹，迴日葉應紅。"]', '诗', 'shi', '', NULL, '送神邈法師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5e3a51-9b38-48b8-b104-bc93f03ca835', '送慈恩寺霄韻法師謁太原李司空', '送慈恩寺霄韻法師謁太原李司空', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["何故謁司空，雲山知幾重。","磧遙來鴈盡，雪急去僧逢。","清磬先寒角，禪燈徹曉烽。","舊房閑片石，倚著最高松。"]', '["何故謁司空，云山知幾重。","磧遙来鴈尽，雪急去僧逢。","清磬先寒角，禪灯徹晓烽。","旧房闲片石，倚著最高松。"]', '诗', 'shi', '', NULL, '送慈恩寺霄韻法師謁太原李司空 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('884df2cf-2a30-431b-a705-2bf9cb4e9b43', '送知興上人', '送知兴上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["久住巴興寺，如今始拂衣。","欲臨秋水別，不向故園歸。","錫挂天涯樹，房開嶽頂扉。","下看千里曉，霜海日生微。"]', '["久住巴兴寺，如今始拂衣。","欲臨秋水別，不向故园归。","錫挂天涯樹，房开嶽頂扉。","下看千里晓，霜海日生微。"]', '诗', 'shi', '', NULL, '送知興上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db690a9f-422e-458d-8965-75710332aec8', '送惠雅法師歸玉泉', '送惠雅法師归玉泉', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["秖到瀟湘水，洞庭湖未遊。","飲泉看月別，下峽聽猨愁。","講不停雷雨，吟當近海流。","降霜歸楚夕，星冷玉泉秋。"]', '["秖到瀟湘水，洞庭湖未游。","饮泉看月別，下峽听猨愁。","講不停雷雨，吟當近海流。","降霜归楚夕，星冷玉泉秋。"]', '诗', 'shi', '', NULL, '送惠雅法師歸玉泉 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58d0214a-58d8-4066-a12f-50ff7e4aae1f', '憶江上吳處士', '憶江上吳处士', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["閩國揚帆去，蟾蜍虧復團。","秋風生渭水，落葉滿長安。","此地聚會夕，當時雷雨寒。","蘭橈殊未返，消息海雲端。"]', '["閩国揚帆去，蟾蜍虧复團。","秋风生渭水，落葉满长安。","此地聚會夕，當时雷雨寒。","蘭橈殊未返，消息海云端。"]', '诗', 'shi', '', NULL, '憶江上吳處士 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5720cc78-ffca-417f-901c-d8d0d96e246f', '題張博士新居', '題張博士新居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["青楓何不種，林在洞庭村。","應爲三湘遠，難移萬里根。","斗牛初過伏，菡萏欲香門。","舊即湖山隱，新廬葺此原。"]', '["青楓何不種，林在洞庭村。","應爲三湘远，难移万里根。","斗牛初過伏，菡萏欲香门。","旧即湖山隐，新廬葺此原。"]', '诗', 'shi', '', NULL, '題張博士新居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('062dcf86-1663-4038-bba4-39fa6a727333', '石門陂留辭從叔謩', '石门陂留辞從叔謩', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["幽鳥飛不遠，此行千里間。","寒衝陂水霧，醉下菊花山。","有恥長爲客，無成又入關。","何時臨澗柳，吾黨共來攀。"]', '["幽鸟飞不远，此行千里间。","寒衝陂水霧，醉下菊花山。","有恥长爲客，無成又入关。","何时臨澗柳，吾黨共来攀。"]', '诗', 'shi', '', NULL, '石門陂留辭從叔謩 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81002d91-a8d2-4ff6-b9ae-1a550d1816d5', '送朱兵曹迴越', '送朱兵曹迴越', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["星彩練中見，澄江豈有泥。","潮生垂釣罷，楚盡去檣西。","磧鳥辭沙至，山鼯隔水啼。","會稽半侵海，濤白禹祠溪。"]', '["星彩練中见，澄江豈有泥。","潮生垂釣罷，楚尽去檣西。","磧鸟辞沙至，山鼯隔水啼。","會稽半侵海，濤白禹祠溪。"]', '诗', 'shi', '', NULL, '送朱兵曹迴越 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efbc18ca-6bc1-4795-b085-f81e15a7900d', '懷博陵故人', '懷博陵故人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["孤城易水頭，不忘舊交遊。","雪壓圍碁石，風吹飲酒樓。","路遙千萬里，人別十三秋。","吟苦相思處，天寒水急流。"]', '["孤城易水头，不忘旧交游。","雪壓圍碁石，风吹饮酒楼。","路遙千万里，人別十三秋。","吟苦相思处，天寒水急流。"]', '诗', 'shi', '', NULL, '懷博陵故人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd4d3717-2301-4efe-b7a6-4a6ed76265dc', '夕思', '夕思', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["秋宵已難曙，漏向二更分。","我憶山水坐，蟲當寂寞聞。","洞庭風落木，天姥月離雲。","會自東浮去，將何欲致君。"]', '["秋宵已难曙，漏向二更分。","我憶山水坐，蟲當寂寞闻。","洞庭风落木，天姥月離云。","會自东浮去，將何欲致君。"]', '诗', 'shi', '', NULL, '夕思 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b2ca48-2430-4305-8939-85b07e358354', '寄河中楊少尹', '寄河中楊少尹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["非惟咎曩時，投刺詣門遲。","悵望三秋後，參差萬里期。","禹留疏鑿跡，舜在寂寥祠。","此到杳難共，迴風逐所思。"]', '["非惟咎曩时，投刺詣门遲。","悵望三秋後，參差万里期。","禹留疏鑿跡，舜在寂寥祠。","此到杳难共，迴风逐所思。"]', '诗', 'shi', '', NULL, '寄河中楊少尹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db04d535-fcaf-4283-84f3-923b59fa56d5', '孟融逸人', '孟融逸人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["孟君臨水居，不食水中魚。","衣褐唯麤帛，筐箱秖素書。","樹林幽鳥戀，世界此心疎。","擬棹孤舟去，何峰又結廬。"]', '["孟君臨水居，不食水中鱼。","衣褐唯麤帛，筐箱秖素书。","樹林幽鸟戀，世界此心疎。","擬棹孤舟去，何峰又結廬。"]', '诗', 'shi', '', NULL, '孟融逸人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ccf240f-d51f-45cf-8bb7-71e6f52ed204', '晚晴見終南諸峰', '晚晴见終南諸峰', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["秦分積多峰，連巴勢不窮。","半旬藏雨裏，此日到窗中。","圓魄將昇兔，高空欲呌鴻。","故山思不見，碣石泬寥東。"]', '["秦分積多峰，連巴勢不窮。","半旬藏雨裏，此日到窗中。","圓魄將昇兔，高空欲呌鴻。","故山思不见，碣石泬寥东。"]', '诗', 'shi', '', NULL, '晚晴見終南諸峰 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7292b3b-e11b-41d6-8587-19ad5f2071cc', '宿池上', '宿池上', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["泉來從絕壑，亭敞在中流。","竹密無空岸，松長可絆舟。","蟪蛄潭上夜，河漢島前秋。","異夕期深漲，攜琴却此遊。"]', '["泉来從絕壑，亭敞在中流。","竹密無空岸，松长可絆舟。","蟪蛄潭上夜，河漢島前秋。","異夕期深漲，携琴却此游。"]', '诗', 'shi', '', NULL, '宿池上 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24855878-b6e3-4668-b0e9-a1617a1035b5', '喜姚郎中自杭州迴', '喜姚郎中自杭州迴', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["路多楓樹林，累日泊清陰。","來去泛流水，翛然適此心。","一披江上作，三起月中吟。","東省期司諫，雲門悔不尋。"]', '["路多楓樹林，累日泊清陰。","来去泛流水，翛然適此心。","一披江上作，三起月中吟。","东省期司諫，云门悔不尋。"]', '诗', 'shi', '', NULL, '喜姚郎中自杭州迴 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31216179-278b-4adf-9701-b7854e4b2bf7', '送鄭長史之嶺南', '送鄭长史之嶺南', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["雲林頗重疊，岑渚復幽奇。","汨水斜陽岸，騷人正則祠。","蒼梧多蟋蟀，白露溼江蘺。","擢第榮南去，晨昏近九疑。"]', '["云林頗重叠，岑渚复幽奇。","汨水斜陽岸，騷人正則祠。","蒼梧多蟋蟀，白露溼江蘺。","擢第榮南去，晨昏近九疑。"]', '诗', 'shi', '', NULL, '送鄭長史之嶺南 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36b88fe-f2d5-4118-8d1a-ab6393795640', '送李溟謁宥州李權使君', '送李溟謁宥州李權使君', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["英雄典宥州，迢遰苦吟遊。","風宿驪山下，月斜灞水流。","去時初落葉，回日定非秋。","太守攜才子，看鵬百尺樓。"]', '["英雄典宥州，迢遰苦吟游。","风宿驪山下，月斜灞水流。","去时初落葉，回日定非秋。","太守携才子，看鵬百尺楼。"]', '诗', 'shi', '', NULL, '送李溟謁宥州李權使君 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2f984cd-59fc-402d-b3ee-306841c379c6', '永福湖和楊鄭州', '永福湖和楊鄭州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["積水還平岸，春來引鄭溪。","舊渠通郭下，新堰絕湖西。","嵩少分明對，瀟湘闊狹齊。","客遊隨庶子，孤嶼草萋萋。"]', '["積水還平岸，春来引鄭溪。","旧渠通郭下，新堰絕湖西。","嵩少分明对，瀟湘闊狹齊。","客游隨庶子，孤嶼草萋萋。"]', '诗', 'shi', '', NULL, '永福湖和楊鄭州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7d85fdc-f5fe-4302-88d6-05f3959a1d52', '題長江', '題长江', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["言心俱好靜，廨署落暉空。","歸吏封宵鑰，行蛇入古桐。","長江頻雨後，明月衆星中。","若任遷人去，西溪與剡通。"]', '["言心俱好静，廨署落暉空。","归吏封宵鑰，行蛇入古桐。","长江頻雨後，明月衆星中。","若任遷人去，西溪與剡通。"]', '诗', 'shi', '', NULL, '題長江 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad218733-8a82-47b0-b8e8-fbdd98eb021f', '泥陽館', '泥陽館', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["客愁何併起，暮送故人回。","廢館秋螢出，空城寒雨來。","夕陽飄白露，樹影掃青苔。","獨坐離容慘，孤燈照不開。"]', '["客愁何併起，暮送故人回。","廢館秋螢出，空城寒雨来。","夕陽飄白露，樹影掃青苔。","独坐離容慘，孤灯照不开。"]', '诗', 'shi', '', NULL, '泥陽館 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1318ca07-1acc-4acf-96aa-37646370a216', '送徐員外赴河中', '送徐員外赴河中', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["原野正蕭瑟，中間分散情。","吏從甘扈罷，詔許朔方行。","邊日沈殘角，河關截夜城。","雲居閑獨往，長老出房迎。"]', '["原野正蕭瑟，中间分散情。","吏從甘扈罷，詔許朔方行。","邊日沈殘角，河关截夜城。","云居闲独往，长老出房迎。"]', '诗', 'shi', '', NULL, '送徐員外赴河中 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c24590f-6d3e-44fb-bf97-a20026e4f025', '送賀蘭上人', '送賀蘭上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["野僧來別我，略坐傍泉沙。","遠道擎空鉢，深山蹋落花。","無師禪自解，有格句堪誇。","此去非緣事，孤雲不定家。"]', '["野僧来別我，略坐傍泉沙。","远道擎空鉢，深山蹋落花。","無師禪自解，有格句堪誇。","此去非緣事，孤云不定家。"]', '诗', 'shi', '', NULL, '送賀蘭上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fafa5158-c354-41b6-82c0-5fcfc1453c0e', '送令狐綯相公', '送令狐綯相公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["梁園趨戟節，海草幾枯春。","風水難遭便，差池未振鱗。","姓名猶語及，門館阻何因。","苦擬修文卷，重擎獻匠人。","吟看青島處，朝退赤墀晨。","根愛杉栽活，枝憐雪霰新。","綴篇嗟調逸，不知揣才貧。","早晚還霖雨，滂沱洗月輪。","揠苗方滅裂，成器待陶鈞。","困坂思迴顧，迷邦輙問津。","數行望外札，絕句握中珍。","是日榮遊汴，當時怯往陳。","鴻舂乖漢爵，[楨]病臥漳濱。","嶽整五千仞，雲惟一片身。","故山離未死，秋水宿經旬。","下第能無恧，高科恐有神。","罷耕田料廢，省釣岸應榛。","慷慨知音在，誰能淚墮巾。"]', '["梁园趨戟節，海草幾枯春。","风水难遭便，差池未振鱗。","姓名猶語及，门館阻何因。","苦擬修文卷，重擎獻匠人。","吟看青島处，朝退赤墀晨。","根愛杉栽活，枝怜雪霰新。","綴篇嗟調逸，不知揣才貧。","早晚還霖雨，滂沱洗月輪。","揠苗方滅裂，成器待陶鈞。","困坂思迴顧，迷邦輙问津。","數行望外札，絕句握中珍。","是日榮游汴，當时怯往陳。","鴻舂乖漢爵，[楨]病臥漳濱。","嶽整五千仞，云惟一片身。","故山離未死，秋水宿經旬。","下第能無恧，高科恐有神。","罷耕田料廢，省釣岸應榛。","慷慨知音在，誰能泪墮巾。"]', '诗', 'shi', '', NULL, '送令狐綯相公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62ba41c5-bab9-4c53-9365-3e237fc04bd0', '寄滄州李尚書', '寄滄州李尚书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["滄溟深絕闊，西岸郭東門。","弋者羅夷鳥，桴人思嶠猨。","威稜高臘冽，煦育極春溫。","陂淀封疆內，蒹葭壁壘根。","搖鞞邊地脈，愁箭虎狼魂。","水縣賣紗市，鹽田煮海村。","枝條分御葉，家世食唐恩。","武可縱橫講，功從戰伐論。","天涯生月片，嶼頂湧泉源。","非是泥池物，方因雷雨尊。","沈謀藏未露，隣境帖無喧。","青塚驕回鶻，蕭關陷吐蕃。","何時霖歲旱，早晚雪邦冤。","迢遰瞻旌纛，浮陽寄詠言。"]', '["滄溟深絕闊，西岸郭东门。","弋者羅夷鸟，桴人思嶠猨。","威稜高臘冽，煦育極春溫。","陂淀封疆內，蒹葭壁壘根。","搖鞞邊地脈，愁箭虎狼魂。","水縣賣紗市，鹽田煮海村。","枝條分御葉，家世食唐恩。","武可縱橫講，功從戰伐論。","天涯生月片，嶼頂湧泉源。","非是泥池物，方因雷雨尊。","沈謀藏未露，隣境帖無喧。","青塚驕回鶻，蕭关陷吐蕃。","何时霖歲旱，早晚雪邦冤。","迢遰瞻旌纛，浮陽寄詠言。"]', '诗', 'shi', '', NULL, '寄滄州李尚書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea5a87a1-3fab-45e8-a21e-c438cb012a37', '逢舊識', '逢旧識', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["幾歲阻干戈，今朝勸酒歌。","羨君無白髮，走馬過黃河。","舊宅兵燒盡，新宮日奏多。","妖星還有角，數尺鐵重磨。"]', '["幾歲阻干戈，今朝勸酒歌。","羨君無白髮，走马過黄河。","旧宅兵燒尽，新宮日奏多。","妖星還有角，數尺鐵重磨。"]', '诗', 'shi', '', NULL, '逢舊識 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c2c0218-03e1-42d3-a86c-f2b1ac3d467f', '崇聖寺斌公房', '崇聖寺斌公房', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["近來惟一食，樹下掩禪扉。","落日寒山磬，多年壞衲衣。","白鬚長更剃，青靄遠還歸。","仍說遊南嶽，經行是息機。"]', '["近来惟一食，樹下掩禪扉。","落日寒山磬，多年壞衲衣。","白鬚长更剃，青靄远還归。","仍说游南嶽，經行是息機。"]', '诗', 'shi', '', NULL, '崇聖寺斌公房 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5450ffc-ebde-4d1f-a940-a8b81683af2c', '送李傅侍郎劒南行營', '送李傅侍郎劒南行營', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["走馬從邊事，新恩受外臺。","勇看雙節出，期破八蠻回。","許國家無戀，盤江棧不摧。","移軍刁斗逐，報捷劒門開。","角咽狝猴呌，鼙乾霹靂來。","去年新甸邑，猶滯佐時才。"]', '["走马從邊事，新恩受外台。","勇看雙節出，期破八蠻回。","許国家無戀，盤江棧不摧。","移軍刁斗逐，報捷劒门开。","角咽狝猴呌，鼙乾霹靂来。","去年新甸邑，猶滯佐时才。"]', '诗', 'shi', '', NULL, '送李傅侍郎劒南行營 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('670e4ce9-a5c1-4837-bf41-995146437875', '別徐明府', '別徐明府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["抱琴非本意，生事偶相縈。","口尚袁安節，身無子賤名。","地寒春雪盛，山淺夕風輕。","百戰餘荒野，千夫漸耦耕。","一杯宜獨夜，孤客戀交情。","明日疲驂去，蕭條過古城。"]', '["抱琴非本意，生事偶相縈。","口尚袁安節，身無子賤名。","地寒春雪盛，山淺夕风轻。","百戰餘荒野，千夫漸耦耕。","一杯宜独夜，孤客戀交情。","明日疲驂去，蕭條過古城。"]', '诗', 'shi', '', NULL, '別徐明府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8823fad8-5ca4-4069-abe9-597843ef2156', '岐下送友人歸襄陽', '岐下送友人归襄陽', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["蹉跎隨汎梗，羈旅到西州。","舉翮籠中鳥，知心海上鷗。","山光分首暮，草色向家秋。","若更登高峴，看碑定淚流。"]', '["蹉跎隨汎梗，羈旅到西州。","舉翮籠中鸟，知心海上鷗。","山光分首暮，草色向家秋。","若更登高峴，看碑定泪流。"]', '诗', 'shi', '', NULL, '岐下送友人歸襄陽 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc61db7-860f-47c8-ad8c-774fe47bb64d', '送友人遊蜀', '送友人游蜀', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["萬岑深積翠，路向此中難。","欲暮多羈思，因高莫遠看。","卓家人寂寞，揚子業凋殘。","唯有岷江水，悠悠帶月寒。"]', '["万岑深積翠，路向此中难。","欲暮多羈思，因高莫远看。","卓家人寂寞，揚子業凋殘。","唯有岷江水，悠悠带月寒。"]', '诗', 'shi', '', NULL, '送友人遊蜀 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6f71377-9740-43c2-9af4-1a3f4ec769b3', '送鄭少府', '送鄭少府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["江岸一相見，空令惜此分。","夕陽行帶月，酌水少留君。","野地初燒草，荒山過雪雲。","明年還調集，蟬可在家聞。"]', '["江岸一相见，空令惜此分。","夕陽行带月，酌水少留君。","野地初燒草，荒山過雪云。","明年還調集，蟬可在家闻。"]', '诗', 'shi', '', NULL, '送鄭少府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c2e176-93bf-4947-b39c-95240a6ce3a8', '子規', '子規', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["遊魂自相呌，寧復記前身。","飛過隣家月，聲連野路春。","夢邊催曉急，愁處送風頻。","自有霑花血，相和雨滴新。"]', '["游魂自相呌，寧复記前身。","飞過隣家月，声連野路春。","梦邊催晓急，愁处送风頻。","自有霑花血，相和雨滴新。"]', '诗', 'shi', '', NULL, '子規 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e8c04b-98e5-4bf2-9705-08919322d7f2', '送僧歸天台', '送僧归天台', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["辭秦經越過，歸寺海西峯。","石磵雙流水，山門九里松。","曾聞清禁漏，却聽赤城鐘。","妙宇研磨講，應齊智者蹤。"]', '["辞秦經越過，归寺海西峯。","石磵雙流水，山门九里松。","曾闻清禁漏，却听赤城鐘。","妙宇研磨講，應齊智者蹤。"]', '诗', 'shi', '', NULL, '送僧歸天台 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d70c7b3-ad88-433f-921c-a518dc0dbe35', '讓糺曹上樂使君', '讓糺曹上乐使君', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["戰戰復兢兢，猶如履薄冰。","雖然叨一掾，還似說三乘。","瓶汲南溪水，書來北嶽僧。","戇愚兼抱疾，權紀不相應。"]', '["戰戰复兢兢，猶如履薄冰。","雖然叨一掾，還似说三乘。","瓶汲南溪水，书来北嶽僧。","戇愚兼抱疾，權紀不相應。"]', '诗', 'shi', '', NULL, '讓糺曹上樂使君 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3cecd71-644c-41d6-936a-c2e3fae71858', '贈友人', '贈友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["五字詩成卷，清新韻具偕。","不同狂客醉，自伴律僧齋。","春別和花樹，秋辭帶月淮。","却歸登第日，名近榜頭排。"]', '["五字诗成卷，清新韻具偕。","不同狂客醉，自伴律僧斋。","春別和花樹，秋辞带月淮。","却归登第日，名近榜头排。"]', '诗', 'shi', '', NULL, '贈友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cf12aa9-4b6d-4fce-9bf9-1f58827b7c97', '送雍陶及第歸成都寧親', '送雍陶及第归成都寧親', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["不唯詩著籍，兼又賦知名。","議論於題稱，春秋對問精。","半應陰隲與，全賴有司平。","歸去峯巒衆，別來松桂生。","漲江流水品，當道白雲坑。","勿以攻文捷，而將學劒輕。","製衣新濯錦，開醞舊燒罌。","同日昇科士，誰同膝下榮。"]', '["不唯诗著籍，兼又賦知名。","議論於題稱，春秋对问精。","半應陰隲與，全賴有司平。","归去峯巒衆，別来松桂生。","漲江流水品，當道白云坑。","勿以攻文捷，而將学劒轻。","製衣新濯錦，开醞旧燒罌。","同日昇科士，誰同膝下榮。"]', '诗', 'shi', '', NULL, '送雍陶及第歸成都寧親 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82fd3e95-ed55-42d1-9a70-5da5adb3fa4f', '謝令狐綯相公賜衣九事', '謝令狐綯相公賜衣九事', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["長江飛鳥外，主簿跨驢歸。","逐客寒前夜，元戎予厚衣。","雪來松更綠，霜降月彌輝。","即日調殷鼎，朝分是與非。"]', '["长江飞鸟外，主簿跨驢归。","逐客寒前夜，元戎予厚衣。","雪来松更綠，霜降月彌輝。","即日調殷鼎，朝分是與非。"]', '诗', 'shi', '', NULL, '謝令狐綯相公賜衣九事 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd828556-fd5c-4116-8159-18007ef65bd7', '送金州鑒周上人', '送金州鑒周上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["地必尋天目，溪仍住若耶。","帆隨風便發，月不要雲遮。","極浦浮霜雁，迴潮落海查。","峨嵋省春上，立雪指流沙。"]', '["地必尋天目，溪仍住若耶。","帆隨风便發，月不要云遮。","極浦浮霜雁，迴潮落海查。","峨嵋省春上，立雪指流沙。"]', '诗', 'shi', '', NULL, '送金州鑒周上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfd453a-0bec-446d-b8a2-91ea9f2e0681', '送譚遠上人', '送譚远上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["下視白雲時，山房蓋樹皮。","垂枝松落子，側頂鶴聽棋。","清淨從沙劫，中終未日欹。","金光明本行，同侍出峨嵋。"]', '["下視白云时，山房蓋樹皮。","垂枝松落子，側頂鹤听棋。","清淨從沙劫，中終未日欹。","金光明本行，同侍出峨嵋。"]', '诗', 'shi', '', NULL, '送譚遠上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b608f6d0-1b8d-4266-b907-12af4b907f34', '新年', '新年', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["嗟以龍鍾身，如何歲復新。","石門思隱久，銅鏡強窺頻。","花發新移樹，心知故國春。","誰能平此恨，豈是北宗人。"]', '["嗟以龙鍾身，如何歲复新。","石门思隐久，銅镜強窺頻。","花發新移樹，心知故国春。","誰能平此恨，豈是北宗人。"]', '诗', 'shi', '', NULL, '新年 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b957e2fe-02de-4fb1-bd40-16400e2d58b0', '送僧', '送僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["出家從丱歲，解論造玄門。","不惜揮談柄，誰能聽至言。","中時山果熟，後夏竹陰繁。","此去逢何日，峨嵋曉復昏。"]', '["出家從丱歲，解論造玄门。","不惜揮談柄，誰能听至言。","中时山果熟，後夏竹陰繁。","此去逢何日，峨嵋晓复昏。"]', '诗', 'shi', '', NULL, '送僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e9ca82f-2295-4e31-b500-0e38da48f5da', '送姚杭州', '送姚杭州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["白雲峯下城，日夕白雲生。","人老江波釣，田侵海樹耕。","吳山鍾入越，蓮葉吹搖旌。","詩異石門思，濤來向越迎。"]', '["白云峯下城，日夕白云生。","人老江波釣，田侵海樹耕。","吳山鍾入越，蓮葉吹搖旌。","诗異石门思，濤来向越迎。"]', '诗', 'shi', '', NULL, '送姚杭州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8f7ff8-9aad-45e3-ab83-99fcecdb1783', '夜集田卿宅', '夜集田卿宅', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["朗詠高齋下，如將古調彈。","翻鴻向桂水，來雪渡桑乾。","滴滴玉漏曙，翛翛竹籟殘。","曩年曾宿此，亦值五陵寒。"]', '["朗詠高斋下，如將古調彈。","翻鴻向桂水，来雪渡桑乾。","滴滴玉漏曙，翛翛竹籟殘。","曩年曾宿此，亦值五陵寒。"]', '诗', 'shi', '', NULL, '夜集田卿宅 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83f1e49f-39e4-4f77-b193-a5a4fe83b4cb', '寄山友長孫棲嶠', '寄山友长孫棲嶠', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["此時氣蕭颯，琴院可應關。","鶴似君無事，風吹雨遍山。","松生青石上，泉落白雲間。","有徑連高頂，心期相與還。"]', '["此时氣蕭颯，琴院可應关。","鹤似君無事，风吹雨遍山。","松生青石上，泉落白云间。","有徑連高頂，心期相與還。"]', '诗', 'shi', '', NULL, '寄山友長孫棲嶠 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b35d65-a22c-4bf3-b5f8-7bfab1a519fe', '詶厲玄', '詶厲玄', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["我來從北鄙，子省涉西陵。","白髮初相識，秋山擬共登。","鄰居帝城雨，會宿御溝冰。","未報見貽作，耿然中夜興。"]', '["我来從北鄙，子省涉西陵。","白髮初相識，秋山擬共登。","鄰居帝城雨，會宿御溝冰。","未報见貽作，耿然中夜兴。"]', '诗', 'shi', '', NULL, '詶厲玄 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a43cbc2-0caa-4019-8750-5ebbe6ad196b', '送劉式洛中覲省', '送劉式洛中覲省', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["晴峯三十六，侍立上春臺。","同宿別離恨，共看星月迴。","野鶯臨苑語，河櫂歷江來。","便寄相思札，緘封花下開。"]', '["晴峯三十六，侍立上春台。","同宿別離恨，共看星月迴。","野鶯臨苑語，河櫂歷江来。","便寄相思札，緘封花下开。"]', '诗', 'shi', '', NULL, '送劉式洛中覲省 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77efa3f1-80d9-44c9-a795-42b9d984cd66', '送空公往金州', '送空公往金州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["七百里山水，手中楖栗麤。","松生師坐石，潭滌祖傳盂。","長擬老嶽嶠，又聞思海湖。","惠能同俗姓，不是嶺南盧。"]', '["七百里山水，手中楖栗麤。","松生師坐石，潭滌祖傳盂。","长擬老嶽嶠，又闻思海湖。","惠能同俗姓，不是嶺南盧。"]', '诗', 'shi', '', NULL, '送空公往金州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4b6f017-0f4f-4acd-a552-20d568b43af8', '贈紹明上人', '贈紹明上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["未住青雲室，中秋獨往年。","上方嵩若寺，下視雨和烟。","祖豈無言去，心因斷臂傳。","不知能已後，更有幾燈然。"]', '["未住青云室，中秋独往年。","上方嵩若寺，下視雨和烟。","祖豈無言去，心因斷臂傳。","不知能已後，更有幾灯然。"]', '诗', 'shi', '', NULL, '贈紹明上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b39d37a-34ac-4bf2-a592-8de3df388685', '贈弘泉上人', '贈弘泉上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["洗足下藍嶺，古師精進同。","心知溪卉長，居此玉林空。","西殿宵燈磬，東林曙雨風。","舊峯鄰太白，石座雨苔濛。"]', '["洗足下藍嶺，古師精進同。","心知溪卉长，居此玉林空。","西殿宵灯磬，东林曙雨风。","旧峯鄰太白，石座雨苔濛。"]', '诗', 'shi', '', NULL, '贈弘泉上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02198763-6d7a-456f-85a6-840183fa7932', '送宣皎上人遊太白', '送宣皎上人游太白', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["剃髮鬢無雪，去年三十三。","山過春草寺，磬度落花潭。","得句才鄰約，論宗意在南。","峯靈疑懶下，蒼翠太虛參。"]', '["剃髮鬢無雪，去年三十三。","山過春草寺，磬度落花潭。","得句才鄰約，論宗意在南。","峯靈疑懶下，蒼翠太虛參。"]', '诗', 'shi', '', NULL, '送宣皎上人遊太白 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee996d66-0273-4fe5-afaf-a802a82aaaee', '病起', '病起', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["高丘歸未得，空自責遲迴。","身事豈能遂，蘭花又已開。","病令新作少，雨阻故人來。","燈下南華卷，袪愁當酒杯。"]', '["高丘归未得，空自責遲迴。","身事豈能遂，蘭花又已开。","病令新作少，雨阻故人来。","灯下南华卷，袪愁當酒杯。"]', '诗', 'shi', '', NULL, '病起 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2babaa7e-6311-4c0a-b5c7-35823d1e80e2', '送殷侍御赴同州', '送殷侍御赴同州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["馮翊蒲西郡，沙岡擁地形。","中條全離嶽，清渭半和涇。","夜暮眠明月，秋深至洞庭。","猶來交辟士，事別偃林扃。"]', '["馮翊蒲西郡，沙岡擁地形。","中條全離嶽，清渭半和涇。","夜暮眠明月，秋深至洞庭。","猶来交辟士，事別偃林扃。"]', '诗', 'shi', '', NULL, '送殷侍御赴同州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49467b77-e3c1-4922-bb03-adf64c8b0a34', '送沈鶴', '送沈鹤', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["家楚壻於秦，攜妻去養親。","陸行千里外，風卷一帆新。","夜泊疏山雨，秋吟搗藥輪。","蕪城登眺作，才動廣陵人。"]', '["家楚壻於秦，携妻去養親。","陸行千里外，风卷一帆新。","夜泊疏山雨，秋吟捣藥輪。","蕪城登眺作，才动廣陵人。"]', '诗', 'shi', '', NULL, '送沈鶴 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f194e7dc-9789-4c14-803c-c5d625fbba8d', '秋夜仰懷錢孟二公琴客會', '秋夜仰懷錢孟二公琴客會', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["月色四時好，秋光君子知。","南山昨夜雨，爲我寫清規。","獨鶴聳寒骨，高杉韻細颸。","仙家縹緲弄，髣髴此中期。"]', '["月色四时好，秋光君子知。","南山昨夜雨，爲我寫清規。","独鹤聳寒骨，高杉韻細颸。","仙家縹緲弄，髣髴此中期。"]', '诗', 'shi', '', NULL, '秋夜仰懷錢孟二公琴客會 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4afc801c-9158-4928-930e-545d534a986f', '贈李金州', '贈李金州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["綺里祠前後，山程踐白雲。","泝流隨大斾，登岸見全軍。","曉角吹人夢，秋風卷雁羣。","霧開方露日，漢水底沙分。"]', '["綺里祠前後，山程踐白云。","泝流隨大斾，登岸见全軍。","晓角吹人梦，秋风卷雁羣。","霧开方露日，漢水底沙分。"]', '诗', 'shi', '', NULL, '贈李金州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed4aaa57-199d-4d4e-a754-5600a559610f', '酬姚合校書', '酬姚合校书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["因貧行遠道，得見舊交遊。","美酒易傾盡，好詩難卒酬。","公堂朝共到，私第夜相留。","不覺入關晚，別來林木秋。"]', '["因貧行远道，得见旧交游。","美酒易傾尽，好诗难卒酬。","公堂朝共到，私第夜相留。","不覺入关晚，別来林木秋。"]', '诗', 'shi', '', NULL, '酬姚合校書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266532ab-b212-4e5c-afc0-9ea092589c38', '送獨孤馬二秀才居明月山讀書', '送独孤马二秀才居明月山读书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["濯志俱高潔，儒科慕冉顏。","家辭臨水郡，雨到讀書山。","棲鳥椶花上，聲鐘礫閣間。","寂寥窗戶外，時見一舟還。"]', '["濯志俱高潔，儒科慕冉顏。","家辞臨水郡，雨到读书山。","棲鸟椶花上，声鐘礫閣间。","寂寥窗戶外，时见一舟還。"]', '诗', 'shi', '', NULL, '送獨孤馬二秀才居明月山讀書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7c4f65-58ea-4f21-854b-499ab7540559', '病蟬', '病蟬', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["病蟬飛不得，向我掌中行。","拆翼猶能薄，酸吟尚極清。","露華凝在腹，塵點誤侵睛。","黃雀幷鳶鳥，俱懷害爾情。"]', '["病蟬飞不得，向我掌中行。","拆翼猶能薄，酸吟尚極清。","露华凝在腹，塵点誤侵睛。","黄雀幷鳶鸟，俱懷害爾情。"]', '诗', 'shi', '', NULL, '病蟬 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cdf47f1-8f58-4758-be40-1d0a5048ae69', '青門里作', '青门里作', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["燕存鴻已過，海內幾人愁。","欲問南宗理，將歸北嶽修。","若無攀桂分，秖是臥雲休。","泉樹一爲別，依稀三十秋。"]', '["燕存鴻已過，海內幾人愁。","欲问南宗理，將归北嶽修。","若無攀桂分，秖是臥云休。","泉樹一爲別，依稀三十秋。"]', '诗', 'shi', '', NULL, '青門里作 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4d8cc57-2f58-402b-9ec2-ef93cec8aafa', '盧秀才南臺', '盧秀才南台', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["居在青門里，臺當千萬岑。","下因岡助勢，上有樹交陰。","陵遠根纔近，空長畔可尋。","新晴登嘯處，驚起宿枝禽。"]', '["居在青门里，台當千万岑。","下因岡助勢，上有樹交陰。","陵远根纔近，空长畔可尋。","新晴登嘯处，驚起宿枝禽。"]', '诗', 'shi', '', NULL, '盧秀才南臺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9872a085-af71-44ea-b8fd-d81f508497d1', '寄李輈侍郎', '寄李輈侍郎', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["終過盟津書，分明夢不虛。","人從清渭別，地隔太行餘。","賓幕誰嫌靜，公門但晏如。","櫑鞞乾霹靂，斜漢溼蟾蜍。","追琢垂今後，敦龐得古初。","井臺憐操築，漳岸想丕疏。","亦冀鏗珉珮，終當直石渠。","此身多抱疾，幽里近營居。","憶漱蘇門澗，經浮楚澤瀦。","松栽侵古影，葷斷尚芹葅。","語嘿曾延接，心源離滓淤。","誰言姓琴氏，獨跨角生魚。"]', '["終過盟津书，分明梦不虛。","人從清渭別，地隔太行餘。","賓幕誰嫌静，公门但晏如。","櫑鞞乾霹靂，斜漢溼蟾蜍。","追琢垂今後，敦龐得古初。","井台怜操築，漳岸想丕疏。","亦冀鏗珉珮，終當直石渠。","此身多抱疾，幽里近營居。","憶漱蘇门澗，經浮楚澤瀦。","松栽侵古影，葷斷尚芹葅。","語嘿曾延接，心源離滓淤。","誰言姓琴氏，独跨角生鱼。"]', '诗', 'shi', '', NULL, '寄李輈侍郎 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3add393-cedc-4577-b5db-e7785019a281', '寄令狐綯相公', '寄令狐綯相公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["驢駿勝羸馬，東川路匪賒。","一緘論賈誼，三蜀寄嚴家。","澄徹霜江水，分明露石沙。","話言聲及政，棧閣谷離斜。","自著衣偏暖，誰憂雪六花。","裹裳留闊襆，防患與通茶。","山館中宵起，星河殘月華。","雙僮前日雇，數口向天涯。","良樂知騏驥，張雷驗鏌鋣。","謙光賢將相，別紙聖龍蛇。","豈有斯言玷，應無白璧瑕。","不妨圓魄裏，人亦指蝦蟇。"]', '["驢駿勝羸马，东川路匪賒。","一緘論賈誼，三蜀寄嚴家。","澄徹霜江水，分明露石沙。","話言声及政，棧閣谷離斜。","自著衣偏暖，誰憂雪六花。","裹裳留闊襆，防患與通茶。","山館中宵起，星河殘月华。","雙僮前日雇，數口向天涯。","良乐知騏驥，張雷驗鏌鋣。","謙光賢將相，別紙聖龙蛇。","豈有斯言玷，應無白璧瑕。","不妨圓魄裏，人亦指蝦蟇。"]', '诗', 'shi', '', NULL, '寄令狐綯相公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3475054-935b-47c0-aac8-d770f46d7e92', '再投李益常侍', '再投李益常侍', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["何處初投刺，當時赴尹京。","淹留花柳變，然諾肺腸傾。","避暑蟬移樹，高眠雁過城。","人家嵩嶽色，公府洛河聲。","聯句逢秋盡，嘗茶見月生。","新衣裁白苧，思從曲江行。"]', '["何处初投刺，當时赴尹京。","淹留花柳变，然諾肺腸傾。","避暑蟬移樹，高眠雁過城。","人家嵩嶽色，公府洛河声。","聯句逢秋尽，嘗茶见月生。","新衣裁白苧，思從曲江行。"]', '诗', 'shi', '', NULL, '再投李益常侍 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75da8f5c-0f91-4d83-851e-3f74b34e1eff', '積雪', '積雪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["昔屬時霖滯，今逢臘雪多。","南猜飄桂渚，北訝雨交河。","盡滅平蕪色，彌重古木柯。","空中離白氣，島外下滄波。","隱者迷樵道，朝人冷玉珂。","夕繁仍晝密，漏間復鐘和。","想積高嵩頂，新秋皎月過。"]', '["昔屬时霖滯，今逢臘雪多。","南猜飄桂渚，北訝雨交河。","尽滅平蕪色，彌重古木柯。","空中離白氣，島外下滄波。","隐者迷樵道，朝人冷玉珂。","夕繁仍晝密，漏间复鐘和。","想積高嵩頂，新秋皎月過。"]', '诗', 'shi', '', NULL, '積雪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c84b0f3-ef7a-4a2b-bf4d-03572a6c79f9', '過楊道士居', '過楊道士居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["先生修道處，茆屋遠囂氛。","叩齒坐明月，搘頤望白雲。","精神含藥色，衣服帶霞紋。","無話瀛洲路，多年別少君。"]', '["先生修道处，茆屋远囂氛。","叩齒坐明月，搘頤望白云。","精神含藥色，衣服带霞紋。","無話瀛洲路，多年別少君。"]', '诗', 'shi', '', NULL, '過楊道士居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef6d055e-823a-4744-875e-26aff4ed8998', '贈僧', '贈僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["亂山秋木穴，裏有靈蛇藏。","鐵錫挂臨海，石樓聞異香。","出塵頭未白，入定衲凝霜。","莫話五湖事，令人心欲狂。"]', '["亂山秋木穴，裏有靈蛇藏。","鐵錫挂臨海，石楼闻異香。","出塵头未白，入定衲凝霜。","莫話五湖事，令人心欲狂。"]', '诗', 'shi', '', NULL, '贈僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b81132b-59bb-49ec-babf-894ade00e4d8', '送友人遊塞', '送友人游塞', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["飄蓬多塞下，君見益潸然。","逈磧沙銜日，長河水接天。","夜泉行客火，曉戍向京煙。","少結相思恨，佳期芳草前。"]', '["飄蓬多塞下，君见益潸然。","逈磧沙銜日，长河水接天。","夜泉行客火，晓戍向京煙。","少結相思恨，佳期芳草前。"]', '诗', 'shi', '', NULL, '送友人遊塞 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('929b8cd3-572f-4f0f-a6ea-f6bdbf9484d9', '思遊邊友人', '思游邊友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["凝愁對孤燭，昨日飲離杯。","葉下故人去，天中新雁來。","連沙秋草薄，帶雪暮山開。","苑北紅塵道，何時見遠迴。"]', '["凝愁对孤燭，昨日饮離杯。","葉下故人去，天中新雁来。","連沙秋草薄，带雪暮山开。","苑北紅塵道，何时见远迴。"]', '诗', 'shi', '', NULL, '思遊邊友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e344072f-9493-4281-afcd-6a496f21fe20', '秋暮寄友人', '秋暮寄友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寥落關河暮，霜風樹葉低。","遠天垂地外，寒日下峯西。","有志煙霞切，無家歲月迷。","清宵話白閣，已負十年棲。"]', '["寥落关河暮，霜风樹葉低。","远天垂地外，寒日下峯西。","有志煙霞切，無家歲月迷。","清宵話白閣，已負十年棲。"]', '诗', 'shi', '', NULL, '秋暮寄友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8448fb5d-ae18-4d13-9a21-ca15afb2b3ab', '寄令狐綯相公', '寄令狐綯相公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["官高頻敕授，老免把犁鋤。","一主長江印，三封東省書。","不無濠上思，唯食圃中蔬。","夢幻將泡影，浮生事只如。"]', '["官高頻敕授，老免把犁鋤。","一主长江印，三封东省书。","不無濠上思，唯食圃中蔬。","梦幻將泡影，浮生事只如。"]', '诗', 'shi', '', NULL, '寄令狐綯相公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ce6b4d1-a880-40df-8da8-e49bec9cc5e7', '和孟逸人林下道情', '和孟逸人林下道情', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["四氣相陶鑄，中庸道豈銷。","夏雲生此日，春色盡今朝。","陋巷貧無悶，毘耶疾未調。","已栽天末柏，合抱豈非遙。"]', '["四氣相陶鑄，中庸道豈銷。","夏云生此日，春色尽今朝。","陋巷貧無悶，毘耶疾未調。","已栽天末柏，合抱豈非遙。"]', '诗', 'shi', '', NULL, '和孟逸人林下道情 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26cba10d-6dde-447b-8f06-29c68533fe98', '宿姚少府北齋', '宿姚少府北斋', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["石溪同夜泛，復此北齋期。","鳥絕吏歸後，蛩鳴客臥時。","鏁城涼雨細，開印曙鐘遲。","憶此漳川岸，如今是別離。"]', '["石溪同夜泛，复此北斋期。","鸟絕吏归後，蛩鳴客臥时。","鏁城涼雨細，开印曙鐘遲。","憶此漳川岸，如今是別離。"]', '诗', 'shi', '', NULL, '宿姚少府北齋 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d897d962-5d51-46cc-9155-e505580398fe', '雪晴晚望', '雪晴晚望', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["倚杖望晴雪，溪雲幾萬重。","樵人歸白屋，寒日下危峯。","野火燒岡草，斷煙生石松。","却回山寺路，聞打暮天鐘。"]', '["倚杖望晴雪，溪云幾万重。","樵人归白屋，寒日下危峯。","野火燒岡草，斷煙生石松。","却回山寺路，闻打暮天鐘。"]', '诗', 'shi', '', NULL, '雪晴晚望 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f24bfcb-5619-43b3-8879-620f5a73e545', '送崔嶠遊瀟湘', '送崔嶠游瀟湘', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["功烈尚書孫，琢磨風雅言。","渡河山鑿處，陟峴漢灘喧。","夢想吟天目，宵同話石門。","楓林葉欲下，極浦月清暾。"]', '["功烈尚书孫，琢磨风雅言。","渡河山鑿处，陟峴漢灘喧。","梦想吟天目，宵同話石门。","楓林葉欲下，極浦月清暾。"]', '诗', 'shi', '', NULL, '送崔嶠遊瀟湘 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53765d53-3bc1-4ed5-8fc4-452473913b3b', '寄朱錫珪', '寄朱錫珪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["遠泊與誰同，來從古木中。","長江人釣月，曠野火燒風。","夢澤吞楚大，閩山阨海叢。","此時檣底水，濤起屈原通。"]', '["远泊與誰同，来從古木中。","长江人釣月，曠野火燒风。","梦澤吞楚大，閩山阨海叢。","此时檣底水，濤起屈原通。"]', '诗', 'shi', '', NULL, '寄朱錫珪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a781aac-8711-4ca6-a54d-b3e8693e8f55', '馬戴居華山因寄', '马戴居华山因寄', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["玉女洗頭盆，孤高不可言。","瀑流蓮嶽頂，河注華山根。","絕雀林藏鶻，無人境有猨。","秋蟾纔過雨，石上古松門。"]', '["玉女洗头盆，孤高不可言。","瀑流蓮嶽頂，河注华山根。","絕雀林藏鶻，無人境有猨。","秋蟾纔過雨，石上古松门。"]', '诗', 'shi', '', NULL, '馬戴居華山因寄 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d307d844-01a2-472e-baf5-8ea7f7fda096', '寄胡遇', '寄胡遇', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一自殘春別，經炎復到涼。","螢從枯樹出，蛩入破堦藏。","落葉書勝紙，閑砧坐當林。","東門因送客，相訪也何妨。"]', '["一自殘春別，經炎复到涼。","螢從枯樹出，蛩入破堦藏。","落葉书勝紙，闲砧坐當林。","东门因送客，相訪也何妨。"]', '诗', 'shi', '', NULL, '寄胡遇 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65326ea9-c944-4a08-9102-1adabbab4647', '送李戎扶侍往壽安', '送李戎扶侍往壽安', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["二千餘里路，一半是波濤。","未曉著衣起，出城逢日高。","關山多寇盜，扶侍帶弓刀。","臨別不揮淚，誰知心鬱陶。"]', '["二千餘里路，一半是波濤。","未晓著衣起，出城逢日高。","关山多寇盜，扶侍带弓刀。","臨別不揮泪，誰知心鬱陶。"]', '诗', 'shi', '', NULL, '送李戎扶侍往壽安 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7a27559-ee67-48d9-a98c-2444d05a5245', '送孫逸人', '送孫逸人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["衣屨猶同俗，妻兒亦宛然。","不餐能累月，無病已多年。","是藥皆諳性，令人漸信仙。","杖頭書數卷，荷入翠微煙。"]', '["衣屨猶同俗，妻兒亦宛然。","不餐能累月，無病已多年。","是藥皆諳性，令人漸信仙。","杖头书數卷，荷入翠微煙。"]', '诗', 'shi', '', NULL, '送孫逸人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c4dc01-80ca-489c-b87f-4c02b6231cb8', '寄華山僧', '寄华山僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["遙知白石室，松柏隱朦朧。","月落看心次，雲生閉目中。","五更鐘隔嶽，萬尺水懸空。","苔蘚嵌巖所，依稀有徑通。"]', '["遙知白石室，松柏隐朦朧。","月落看心次，云生閉目中。","五更鐘隔嶽，万尺水懸空。","苔蘚嵌巖所，依稀有徑通。"]', '诗', 'shi', '', NULL, '寄華山僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812b219c-4999-45e4-9f14-63bee2f7a4c7', '送李登少府', '送李登少府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["伊陽耽酒尉，朗詠醉醒新。","應見嵩山裏，明年躑躅春。","一千尋樹直，三十六峯鄰。","流水潺潺處，堅貞玉澗珉。"]', '["伊陽耽酒尉，朗詠醉醒新。","應见嵩山裏，明年躑躅春。","一千尋樹直，三十六峯鄰。","流水潺潺处，堅貞玉澗珉。"]', '诗', 'shi', '', NULL, '送李登少府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d50b59a-2afb-46da-a485-39ea3f0a8bc3', '易州過郝逸人居', '易州過郝逸人居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["每逢詞翰客，邀我共尋君。","果見閑居賦，未曾流俗聞。","也知鄰市井，宛似出囂氛。","却笑巢由輩，何須隱白雲。"]', '["每逢词翰客，邀我共尋君。","果见闲居賦，未曾流俗闻。","也知鄰市井，宛似出囂氛。","却笑巢由輩，何須隐白云。"]', '诗', 'shi', '', NULL, '易州過郝逸人居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a938c35a-36fb-4b1e-b425-180f1f94a101', '詶鄠縣李廓少府見寄', '詶鄠縣李廓少府见寄', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["稍憐公事退，復遇夕陽時。","北朔霜凝竹，南山水入籬。","吟懷滄海侶，空問白雲師。","恨不相從去，心惟野鶴知。"]', '["稍怜公事退，复遇夕陽时。","北朔霜凝竹，南山水入籬。","吟懷滄海侶，空问白云師。","恨不相從去，心惟野鹤知。"]', '诗', 'shi', '', NULL, '詶鄠縣李廓少府見寄 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41c87e51-e9ce-4968-82c7-f1971c2647b4', '淨業寺與前鄠縣李廓少府同宿', '淨業寺與前鄠縣李廓少府同宿', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["來從城上峯，京寺暮相逢。","往往語復默，微微雨灑松。","家貧初罷吏，年長畏聞蛩。","前日獨拘束，披衣起曉鐘。"]', '["来從城上峯，京寺暮相逢。","往往語复默，微微雨灑松。","家貧初罷吏，年长畏闻蛩。","前日独拘束，披衣起晓鐘。"]', '诗', 'shi', '', NULL, '淨業寺與前鄠縣李廓少府同宿 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87c03a72-d792-4cdd-8d43-22e777809302', '送南卓歸京', '送南卓归京', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["殘春別鏡陂，罷郡未霜髭。","行李逢炎暑，山泉滿路岐。","雲藏巢鶴樹，風觸囀鶯枝。","三省同虛位，雙旌帶去思。","入城宵夢後，待漏月沈時。","長策幷忠告，從容寫玉墀。"]', '["殘春別镜陂，罷郡未霜髭。","行李逢炎暑，山泉满路岐。","云藏巢鹤樹，风觸囀鶯枝。","三省同虛位，雙旌带去思。","入城宵梦後，待漏月沈时。","长策幷忠告，從容寫玉墀。"]', '诗', 'shi', '', NULL, '送南卓歸京 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d2a6786-4683-45f0-81fb-d83cb21c7047', '臥疾走筆詶韓愈書問', '臥疾走笔詶韓愈书问', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一臥三四旬，數書惟獨君。","願爲出海月，不作歸山雲。","身上衣頻寄，甌中物亦分。","欲知強健否，病鶴未離羣。"]', '["一臥三四旬，數书惟独君。","願爲出海月，不作归山云。","身上衣頻寄，甌中物亦分。","欲知強健否，病鹤未離羣。"]', '诗', 'shi', '', NULL, '臥疾走筆詶韓愈書問 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c28fa9ab-884d-4058-8e83-354c49e222d6', '長孫霞李溟自紫閣白閣二峯見訪', '长孫霞李溟自紫閣白閣二峯见訪', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["寂寞吾廬貧，同來二閣人。","所論唯野事，招作住雲鄰。","古寺期秋宿，平林散早春。","漱流今已矣，巢許豈堯臣。"]', '["寂寞吾廬貧，同来二閣人。","所論唯野事，招作住云鄰。","古寺期秋宿，平林散早春。","漱流今已矣，巢許豈堯臣。"]', '诗', 'shi', '', NULL, '長孫霞李溟自紫閣白閣二峯見訪 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47b3a6a9-7b4c-4201-8e01-5b4794c4d135', '送惟一遊清涼寺', '送惟一游清涼寺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["去有巡臺侶，荒溪衆樹分。","瓶殘秦地水，錫入晉山雲。","秋月離喧見，寒泉出定聞。","人間臨欲別，旬日雨紛紛。"]', '["去有巡台侶，荒溪衆樹分。","瓶殘秦地水，錫入晉山云。","秋月離喧见，寒泉出定闻。","人间臨欲別，旬日雨紛紛。"]', '诗', 'shi', '', NULL, '送惟一遊清涼寺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c1f90ef-c33b-4806-b87c-01faedde8b49', '鄭尚書新開涪江二首 一', '鄭尚书新开涪江二首 一', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["岸鑿青山破，江開白浪寒。","日沈源出海，春至草生灘。","梓匠防波溢，蓬仙畏水乾。","從今疏決後，任雨滯峯巒。"]', '["岸鑿青山破，江开白浪寒。","日沈源出海，春至草生灘。","梓匠防波溢，蓬仙畏水乾。","從今疏決後，任雨滯峯巒。"]', '诗', 'shi', '', NULL, '鄭尚書新開涪江二首 一 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('664671a1-232e-4309-89e1-50dfe57c7493', '鄭尚書新開涪江二首 二', '鄭尚书新开涪江二首 二', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["不侵南畝務，已拔北江流。","涪水方移岸，潯陽有到舟。","潭澄初擣藥，波動乍垂鉤。","山可疏三里，從知歷億秋。"]', '["不侵南畝務，已拔北江流。","涪水方移岸，潯陽有到舟。","潭澄初擣藥，波动乍垂鉤。","山可疏三里，從知歷億秋。"]', '诗', 'shi', '', NULL, '鄭尚書新開涪江二首 二 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ae1182-a801-4cb9-aa0f-3c12e6012654', '寄喬侍郎', '寄喬侍郎', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["大寧猶未到，曾渡北浮橋。","曉出爬船寺，手擎紫栗條。","差池不相見，悵望至今朝。","近日營家計，繩懸一小瓢。"]', '["大寧猶未到，曾渡北浮橋。","晓出爬船寺，手擎紫栗條。","差池不相见，悵望至今朝。","近日營家計，繩懸一小瓢。"]', '诗', 'shi', '', NULL, '寄喬侍郎 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74625e13-92fb-4f31-96cd-baa572883e63', '送去華法師', '送去华法師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["在越居何寺，東南水路歸。","秋江洗一鉢，寒日曬三衣。","默聽鴻聲盡，行看葉影飛。","囊中無寶貨，船戶夜扃稀。"]', '["在越居何寺，东南水路归。","秋江洗一鉢，寒日曬三衣。","默听鴻声尽，行看葉影飞。","囊中無寶貨，船戶夜扃稀。"]', '诗', 'shi', '', NULL, '送去華法師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a4829df-0a0d-4e78-9d28-346ffd9ed07d', '送蔡京', '送蔡京', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["躍蹄歸魯日，帶漏別秦星。","易折芳條桂，難窮邃義經。","登封多泰嶽，巡狩徧滄溟。","家在何林下，梁山翠滿庭。"]', '["躍蹄归魯日，带漏別秦星。","易折芳條桂，难窮邃義經。","登封多泰嶽，巡狩徧滄溟。","家在何林下，梁山翠满庭。"]', '诗', 'shi', '', NULL, '送蔡京 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('924ce680-c634-4699-8864-21c7b1a92684', '慈恩寺上座院', '慈恩寺上座院', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["未委衡山色，何如對塔峯。","曩宵曾宿此，今夕值秋濃。","羽族棲煙竹，寒流帶月鐘。","井甘源起異，泉湧漬苔封。"]', '["未委衡山色，何如对塔峯。","曩宵曾宿此，今夕值秋濃。","羽族棲煙竹，寒流带月鐘。","井甘源起異，泉湧漬苔封。"]', '诗', 'shi', '', NULL, '慈恩寺上座院 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('972dc507-f58c-4a10-9f81-e2c497c34425', '題朱慶餘所居', '題朱慶餘所居', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["天寒吟竟曉，古屋瓦生松。","寄信船一隻，隔鄉山萬重。","樹來沙岸鳥，窗度雪樓鐘。","每憶江中嶼，更看城上峯。"]', '["天寒吟竟晓，古屋瓦生松。","寄信船一隻，隔乡山万重。","樹来沙岸鸟，窗度雪楼鐘。","每憶江中嶼，更看城上峯。"]', '诗', 'shi', '', NULL, '題朱慶餘所居 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9127714f-a12b-4610-a965-8f82d00e1a07', '送黃知新歸安南', '送黄知新归安南', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["池亭沈飲徧，非獨曲江花。","地遠路穿海，春歸冬到家。","火山難下雪，瘴土不生茶。","知決移來計，相逢期尚賒。"]', '["池亭沈饮徧，非独曲江花。","地远路穿海，春归冬到家。","火山难下雪，瘴土不生茶。","知決移来計，相逢期尚賒。"]', '诗', 'shi', '', NULL, '送黃知新歸安南 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53607c0e-81e8-400d-a768-cecc6c3f2119', '贈胡禪歸', '贈胡禪归', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["自是根機鈍，非關夏臘深。","秋來江上寺，夜坐嶺南心。","井鑿山含月，風吹磬出林。","祖師攜隻履，去路杳難尋。"]', '["自是根機鈍，非关夏臘深。","秋来江上寺，夜坐嶺南心。","井鑿山含月，风吹磬出林。","祖師携隻履，去路杳难尋。"]', '诗', 'shi', '', NULL, '贈胡禪歸 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d68da3-1c96-456e-8dbb-76bd3a2bbe4f', '元日女道士受籙', '元日女道士受籙', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["元日更新夜，齋身稱淨衣。","數星連斗出，萬里斷雲飛。","霜下磬聲在，月高壇影微。","立聽師語了，左肘繫符歸。"]', '["元日更新夜，斋身稱淨衣。","數星連斗出，万里斷云飞。","霜下磬声在，月高壇影微。","立听師語了，左肘繫符归。"]', '诗', 'shi', '', NULL, '元日女道士受籙 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('519c23bf-c0ba-4969-814f-115ffc4e3b80', '重與彭兵曹', '重與彭兵曹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["故人在城裏，休寄海邊書。","漸去老不遠，別來情豈疎。","硯冰催臘日，山雀到貧居。","每有平戎計，官家別敕除。"]', '["故人在城裏，休寄海邊书。","漸去老不远，別来情豈疎。","硯冰催臘日，山雀到貧居。","每有平戎計，官家別敕除。"]', '诗', 'shi', '', NULL, '重與彭兵曹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b06de45-88c1-4ba6-b715-cb6eed69c02a', '贈莊上人', '贈莊上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["不語焚香坐，心知道已成。","流年衰此世，定力見他生。","暮雪餘春冷，寒燈續晝明。","尋常五侯至，敢望下堦迎。"]', '["不語焚香坐，心知道已成。","流年衰此世，定力见他生。","暮雪餘春冷，寒灯續晝明。","尋常五侯至，敢望下堦迎。"]', '诗', 'shi', '', NULL, '贈莊上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6bc3538-77b3-4cbc-bf01-1672db5a6fb8', '落第東歸逢僧伯陽', '落第东归逢僧伯陽', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["相逢須語笑，人世別離頻。","曉至長侵月，思鄉動隔春。","見僧心暫靜，從俗事多迍。","宇宙詩名小，山河客路新。","翠桐猶入爨，清鏡未辭塵。","逸足思奔驥，隨羣且退鱗。","宴乖紅杏寺，愁在綠楊津。","老病難爲樂，開眉賴故人。"]', '["相逢須語笑，人世別離頻。","晓至长侵月，思乡动隔春。","见僧心暫静，從俗事多迍。","宇宙诗名小，山河客路新。","翠桐猶入爨，清镜未辞塵。","逸足思奔驥，隨羣且退鱗。","宴乖紅杏寺，愁在綠楊津。","老病难爲乐，开眉賴故人。"]', '诗', 'shi', '', NULL, '落第東歸逢僧伯陽 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b0d9223-7f7a-43dc-a7f7-074f65f14a50', '皇甫主簿期遊山不及赴', '皇甫主簿期游山不及赴', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["休官匹馬在，新意入山中。","更住應難遂，前期恨不同。","集蟬苔樹僻，留客雨堂空。","深夜誰相訪，惟當清淨翁。"]', '["休官匹马在，新意入山中。","更住應难遂，前期恨不同。","集蟬苔樹僻，留客雨堂空。","深夜誰相訪，惟當清淨翁。"]', '诗', 'shi', '', NULL, '皇甫主簿期遊山不及赴 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1603e614-b7c1-469a-bd5e-60cfb9ee66e4', '宿成湘林下', '宿成湘林下', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["相訪夕陽時，千株木未衰。","石泉流出谷，山雨滴棲鴟。","漏向燈聽數，酒因客寢遲。","今宵不盡興，更有月明期。"]', '["相訪夕陽时，千株木未衰。","石泉流出谷，山雨滴棲鴟。","漏向灯听數，酒因客寢遲。","今宵不尽兴，更有月明期。"]', '诗', 'shi', '', NULL, '宿成湘林下 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf9bc53-7beb-43b3-a6d9-aefa39a5d817', '喜雍陶至', '喜雍陶至', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["今朝笑語同，幾日百憂中。","鳥度劒門靜，蠻歸瀘水空。","步霜吟菊畔，待月坐林東。","且莫孤此興，勿論窮與通。"]', '["今朝笑語同，幾日百憂中。","鸟度劒门静，蠻归瀘水空。","步霜吟菊畔，待月坐林东。","且莫孤此兴，勿論窮與通。"]', '诗', 'shi', '', NULL, '喜雍陶至 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d7cc07c-efcc-4c9f-b7ea-7c42cb14849b', '酬胡遇', '酬胡遇', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["麗句傳人口，科名立可圖。","移居見山燒，買樹帶巢烏。","遊遠風濤急，吟清雪月孤。","却思初識面，仍未有多鬚。"]', '["丽句傳人口，科名立可圖。","移居见山燒，買樹带巢烏。","游远风濤急，吟清雪月孤。","却思初識面，仍未有多鬚。"]', '诗', 'shi', '', NULL, '酬胡遇 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3da8fb0a-9cd6-4c16-b725-d333312b9d09', '宿慈恩寺郁公房', '宿慈恩寺郁公房', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["病身來寄宿，自掃一牀閑。","反照臨江磬，新秋過雨山。","竹陰移冷月，荷氣帶禪關。","獨住天台意，方從內請還。"]', '["病身来寄宿，自掃一牀闲。","反照臨江磬，新秋過雨山。","竹陰移冷月，荷氣带禪关。","独住天台意，方從內請還。"]', '诗', 'shi', '', NULL, '宿慈恩寺郁公房 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dec54f3-9937-42b2-957a-b75fd837aa09', '送褚山人歸日本', '送褚山人归日本', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["懸帆待秋水，去入杳冥間。","東海幾年別，中華此日還。","岸遙生白髮，波盡露青山。","隔水相思在，無書也是閑。"]', '["懸帆待秋水，去入杳冥间。","东海幾年別，中华此日還。","岸遙生白髮，波尽露青山。","隔水相思在，無书也是闲。"]', '诗', 'shi', '', NULL, '送褚山人歸日本 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bc9e121-f932-49f0-9043-04f7341f479c', '寄韓湘', '寄韓湘', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["過嶺行多少，潮州漲滿川。","花開南去後，水凍北歸前。","望鷺吟登閣，聽猨淚滴船。","相思堪面話，不著尺書傳。"]', '["過嶺行多少，潮州漲满川。","花开南去後，水凍北归前。","望鷺吟登閣，听猨泪滴船。","相思堪面話，不著尺书傳。"]', '诗', 'shi', '', NULL, '寄韓湘 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8885fe11-cf97-4267-bb7b-d457859c3b04', '雨夜寄馬戴', '雨夜寄马戴', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["芳林杏花樹，花落子西東。","今夕曲江雨，寒催朔北風。","鄉書滄海絕，隱路翠微通。","寂寂相思際，孤釭殘漏中。"]', '["芳林杏花樹，花落子西东。","今夕曲江雨，寒催朔北风。","乡书滄海絕，隐路翠微通。","寂寂相思際，孤釭殘漏中。"]', '诗', 'shi', '', NULL, '雨夜寄馬戴 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('381c42eb-dc7a-40e4-abf5-a87f9828712e', '喜無可上人遊山回', '喜無可上人游山回', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["一食復何如，尋山無定居。","相逢新夏滿，不見半年餘。","聽話龍潭雪，休傳鳥道書。","別來還似舊，白髮日高梳。"]', '["一食复何如，尋山無定居。","相逢新夏满，不见半年餘。","听話龙潭雪，休傳鸟道书。","別来還似旧，白髮日高梳。"]', '诗', 'shi', '', NULL, '喜無可上人遊山回 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be4e7fdb-daac-43a9-891d-987d0947dfbf', '寄毘陵徹公', '寄毘陵徹公', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["身依吳寺老，黃葉幾迴看。","早講林霜在，孤禪隙月殘。","井通潮浪遠，鐘與角聲寒。","已有南遊約，誰言禮謁難。"]', '["身依吳寺老，黄葉幾迴看。","早講林霜在，孤禪隙月殘。","井通潮浪远，鐘與角声寒。","已有南游約，誰言禮謁难。"]', '诗', 'shi', '', NULL, '寄毘陵徹公 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16a94311-5fda-45a5-a594-242ad23b4748', '送韋瓊校書', '送韋瓊校书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["賓佐兼歸覲，此行江漢心。","別離從闕下，道路向山陰。","孤嶼消寒沫，空城滴夜霖。","若邪溪畔寺，秋色共誰尋。"]', '["賓佐兼归覲，此行江漢心。","別離從闕下，道路向山陰。","孤嶼消寒沫，空城滴夜霖。","若邪溪畔寺，秋色共誰尋。"]', '诗', 'shi', '', NULL, '送韋瓊校書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4133e659-3ad8-4fef-92c5-c0f4fac5c387', '寄劉侍御', '寄劉侍御', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["衣多苔蘚痕，猶擬更趨門。","自夏雖無病，經秋不過原。","積泉留岱鳥，疊岫隔巴猨。","琴月西齋集，如今豈復言。"]', '["衣多苔蘚痕，猶擬更趨门。","自夏雖無病，經秋不過原。","積泉留岱鸟，叠岫隔巴猨。","琴月西斋集，如今豈复言。"]', '诗', 'shi', '', NULL, '寄劉侍御 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23b194b4-a3d3-4d88-b41f-d0e34503bb81', '送穆少府知眉州', '送穆少府知眉州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["劒門倚青漢，君昔未曾過。","日暮行人少，山深異鳥多。","猨啼和峽雨，棧盡到江波。","一路白雲裏，飛泉灑薜蘿。"]', '["劒门倚青漢，君昔未曾過。","日暮行人少，山深異鸟多。","猨啼和峽雨，棧尽到江波。","一路白云裏，飞泉灑薜蘿。"]', '诗', 'shi', '', NULL, '送穆少府知眉州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8f0cbc6-63ed-431c-963a-9a97f83e4bd1', '二月晦日留別鄠中友人', '二月晦日留別鄠中友人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["立馬柳花裏，別君當酒酣。","春風漸向北，雲雁不飛南。","明曉日初一，今年月又三。","鞭羸去暮色，遠嶽起煙嵐。"]', '["立马柳花裏，別君當酒酣。","春风漸向北，云雁不飞南。","明晓日初一，今年月又三。","鞭羸去暮色，远嶽起煙嵐。"]', '诗', 'shi', '', NULL, '二月晦日留別鄠中友人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82528aeb-1624-44c2-8460-669f4a9d1dff', '送李校書赴吉期', '送李校书赴吉期', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["筮算重重吉，良期詎可遷。","不同牛女夜，是配鳳凰年。","佩玉春風裏，題章蠟燭前。","詩書與箴訓，夫哲又妻賢。"]', '["筮算重重吉，良期詎可遷。","不同牛女夜，是配鳳凰年。","佩玉春风裏，題章蠟燭前。","诗书與箴訓，夫哲又妻賢。"]', '诗', 'shi', '', NULL, '送李校書赴吉期 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dec7640-c4d5-480c-85c8-31ad8ebccda1', '宿孤館', '宿孤館', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["落日投村戍，愁生爲客途。","寒山晴後綠，秋月夜來孤。","橘樹千株在，漁家一半無。","自知風水靜，舟繫岸邊蘆。"]', '["落日投村戍，愁生爲客途。","寒山晴後綠，秋月夜来孤。","橘樹千株在，漁家一半無。","自知风水静，舟繫岸邊蘆。"]', '诗', 'shi', '', NULL, '宿孤館 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39599798-21e2-4df5-bddb-1b244bd5af89', '哭宗密禪師', '哭宗密禪師', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["鳥道雪岑巔，師亡誰去禪。","几塵增滅後，樹色改生前。","層塔當松吹，殘蹤傍野泉。","唯嗟聽經虎，時到壞菴邊。"]', '["鸟道雪岑巔，師亡誰去禪。","几塵增滅後，樹色改生前。","層塔當松吹，殘蹤傍野泉。","唯嗟听經虎，时到壞菴邊。"]', '诗', 'shi', '', NULL, '哭宗密禪師 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54d324bf-a9cb-4156-9cb9-b32aef00ea68', '宿山寺', '宿山寺', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["衆岫聳寒色，精廬向此分。","流星透疎木，走月逆行雲。","絕頂人來少，高松鶴不羣。","一僧年八十，世事未曾聞。"]', '["衆岫聳寒色，精廬向此分。","流星透疎木，走月逆行云。","絕頂人来少，高松鹤不羣。","一僧年八十，世事未曾闻。"]', '诗', 'shi', '', NULL, '宿山寺 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e94507f7-8771-470a-83b3-12c63a5a5c41', '送友人如邊', '送友人如邊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["去日重陽後，前程菊正芳。","行車輾秋嶽，落葉墜寒霜。","雲入漢天白，風高磧色黃。","蒲輪待恐晚，求薦向諸方。"]', '["去日重陽後，前程菊正芳。","行车輾秋嶽，落葉墜寒霜。","云入漢天白，风高磧色黄。","蒲輪待恐晚，求薦向諸方。"]', '诗', 'shi', '', NULL, '送友人如邊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('443f86fe-9ab9-4376-b0ab-0a80736e6021', '題竹谷上人院', '題竹谷上人院', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["禪庭高鳥道，迴望極川原。","樵徑連峯頂，石泉通竹根。","木深猶積雪，山淺未聞猨。","欲別塵中苦，願師貽一言。"]', '["禪庭高鸟道，迴望極川原。","樵徑連峯頂，石泉通竹根。","木深猶積雪，山淺未闻猨。","欲別塵中苦，願師貽一言。"]', '诗', 'shi', '', NULL, '題竹谷上人院 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06330d8-6ac1-4917-8670-a06cbc629315', '京北原作', '京北原作', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["登原見城闕，策蹇思炎天。","日午路中客，槐花風處蟬。","遠山秦木上，清渭漢陵前。","何事居人世，皆從名利牽。"]', '["登原见城闕，策蹇思炎天。","日午路中客，槐花风处蟬。","远山秦木上，清渭漢陵前。","何事居人世，皆從名利牽。"]', '诗', 'shi', '', NULL, '京北原作 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af9d4ac-16d1-4fe2-82a3-56a8cf5d4c96', '寄江上人', '寄江上人', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["紫閣舊房在，新家中嶽東。","煙波千里隔，消息一朝通。","寒日汀洲路，秋晴島嶼風。","分明杜陵葉，別後兩經紅。"]', '["紫閣旧房在，新家中嶽东。","煙波千里隔，消息一朝通。","寒日汀洲路，秋晴島嶼风。","分明杜陵葉，別後兩經紅。"]', '诗', 'shi', '', NULL, '寄江上人 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b7df15c-0382-4925-a6f2-f04a44bf03d4', '送僧歸太白山', '送僧归太白山', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["堅冰連夏處，太白接青天。","雲塞石房路，峯明雨外巔。","夜禪臨虎穴，寒漱撇龍泉。","後會不期日，相逢應信緣。"]', '["堅冰連夏处，太白接青天。","云塞石房路，峯明雨外巔。","夜禪臨虎穴，寒漱撇龙泉。","後會不期日，相逢應信緣。"]', '诗', 'shi', '', NULL, '送僧歸太白山 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6530401f-631b-426e-9abd-4b7403e0b69d', '暮過山村', '暮過山村', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["數里聞寒水，山家少四鄰。","怪禽啼曠野，落日恐行人。","初月未終夕，邊烽不過秦。","蕭條桑柘外，煙火漸相親。"]', '["數里闻寒水，山家少四鄰。","怪禽啼曠野，落日恐行人。","初月未終夕，邊烽不過秦。","蕭條桑柘外，煙火漸相親。"]', '诗', 'shi', '', NULL, '暮過山村 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f4cf11-aa0b-43da-ba43-574faecb4f97', '鷺鷥', '鷺鷥', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["求魚未得食，沙岸往來行。","島月獨棲影，暮天寒過聲。","墮巢因木折，失侶遇弦驚。","頻向煙霄望，吾知爾去程。"]', '["求鱼未得食，沙岸往来行。","島月独棲影，暮天寒過声。","墮巢因木折，失侶遇弦驚。","頻向煙霄望，吾知爾去程。"]', '诗', 'shi', '', NULL, '鷺鷥 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aa6a5d2-d9c1-432c-bd71-9a6c4804c963', '內道場僧弘紹', '內道場僧弘紹', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["麟德燃香請，長安春幾回。","夜閑同像寂，晝定爲吾開。","講罷松根老，經浮海水來。","六年雙足履，只步院中苔。"]', '["麟德燃香請，长安春幾回。","夜闲同像寂，晝定爲吾开。","講罷松根老，經浮海水来。","六年雙足履，只步院中苔。"]', '诗', 'shi', '', NULL, '內道場僧弘紹 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53c3bf2e-7797-466f-ae05-def157c59a6d', '蔣亭和蔡湘州', '蔣亭和蔡湘州', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["蔣宅爲亭榭，蔡城東郭門。","潭連秦相井，松老漢朝根。","已積蒼苔徧，何曾舊徑存。","高齋無事後，時復一攜尊。"]', '["蔣宅爲亭榭，蔡城东郭门。","潭連秦相井，松老漢朝根。","已積蒼苔徧，何曾旧徑存。","高斋無事後，时复一携尊。"]', '诗', 'shi', '', NULL, '蔣亭和蔡湘州 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e5da35a-a97a-42ca-8ca5-8494952ded7f', '光州王建使君水亭作', '光州王建使君水亭作', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["楚水臨軒積，澄鮮一畝餘。","柳根連岸盡，荷葉出萍初。","極浦清相似，幽禽到不虛。","夕陽庭際眺，槐雨滴疎疎。"]', '["楚水臨軒積，澄鲜一畝餘。","柳根連岸尽，荷葉出萍初。","極浦清相似，幽禽到不虛。","夕陽庭際眺，槐雨滴疎疎。"]', '诗', 'shi', '', NULL, '光州王建使君水亭作 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edbd6e1a-a7f7-4d2d-a65d-de9edd6a443f', '留別光州王使君建', '留別光州王使君建', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["杜陵千里外，期在末秋歸。","既見林花落，須防木葉飛。","楚從何地盡，淮隔數峯微。","迴首餘霞失，斜陽照客衣。"]', '["杜陵千里外，期在末秋归。","既见林花落，須防木葉飞。","楚從何地尽，淮隔數峯微。","迴首餘霞失，斜陽照客衣。"]', '诗', 'shi', '', NULL, '留別光州王使君建 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c420df8-b8d3-4f50-ba05-b1c71c5898d3', '宿姚合宅寄張司業籍', '宿姚合宅寄張司業籍', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["閑宵因集會，柱史話先生。","身愛無一事，心期往四明。","松枝影搖動，石磬響寒清。","誰伴南齋宿，月高霜滿城。"]', '["闲宵因集會，柱史話先生。","身愛無一事，心期往四明。","松枝影搖动，石磬响寒清。","誰伴南斋宿，月高霜满城。"]', '诗', 'shi', '', NULL, '宿姚合宅寄張司業籍 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f0b26f-4ce1-4088-b232-24d7d8ee9912', '哭張籍', '哭張籍', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["精靈歸恍惚，石磬韻曾聞。","即日是前古，誰人耕此墳。","舊遊孤櫂遠，故域九江分。","本欲蓬瀛去，餐芝御白雲。"]', '["精靈归恍惚，石磬韻曾闻。","即日是前古，誰人耕此墳。","旧游孤櫂远，故域九江分。","本欲蓬瀛去，餐芝御白云。"]', '诗', 'shi', '', NULL, '哭張籍 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b75e5e-2cb4-45dd-90df-90dd1d4761c5', '靈準上人院', '靈準上人院', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["掩扉當太白，臘數等松椿。","禁漏來遙夜，山泉落近鄰。","經聲終卷曉，草色幾芽春。","海內知名士，交遊準上人。"]', '["掩扉當太白，臘數等松椿。","禁漏来遙夜，山泉落近鄰。","經声終卷晓，草色幾芽春。","海內知名士，交游準上人。"]', '诗', 'shi', '', NULL, '靈準上人院 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f74cbbed-a885-4613-b7b0-8a23ab34a20e', '寄柳舍人宗元', '寄柳舍人宗元', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["格與功俱造，何人意不降。","一宵三夢柳，孤泊九秋江。","擢第名重列，沖天字幾雙。","誓爲仙者僕，側執馭風幢。"]', '["格與功俱造，何人意不降。","一宵三梦柳，孤泊九秋江。","擢第名重列，沖天字幾雙。","誓爲仙者僕，側執馭风幢。"]', '诗', 'shi', '', NULL, '寄柳舍人宗元 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a83207b-e8dd-4245-adb9-a6005f2dc5df', '送玄巖上人歸西蜀', '送玄巖上人归西蜀', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["玉壘山中寺，幽深勝概多。","藥成彭祖擣，頂受七輪摩。","去臘催今夏，流光等逝波。","會當依糞掃，五嶽徧頭陀。"]', '["玉壘山中寺，幽深勝概多。","藥成彭祖擣，頂受七輪摩。","去臘催今夏，流光等逝波。","會當依糞掃，五嶽徧头陀。"]', '诗', 'shi', '', NULL, '送玄巖上人歸西蜀 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd67561-debc-4c38-9e15-d8d3bb72dbec', '寄宋州田中丞', '寄宋州田中丞', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["古郡近南徐，關河萬里餘。","相思深夜後，未荅去秋書。","自別知音少，難忘識面初。","舊山期已久，門掩數畦蔬。"]', '["古郡近南徐，关河万里餘。","相思深夜後，未荅去秋书。","自別知音少，难忘識面初。","旧山期已久，门掩數畦蔬。"]', '诗', 'shi', '', NULL, '寄宋州田中丞 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4764556-41b7-4093-aebb-b4141332c3b5', '送朱休歸劒南', '送朱休归劒南', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["劒南歸受賀，太學賦聲雄。","山路長江岸，朝陽十月中。","芽新抽雪茗，枝重集猨楓。","卓氏琴臺廢，深蕪想徑通。"]', '["劒南归受賀，太学賦声雄。","山路长江岸，朝陽十月中。","芽新抽雪茗，枝重集猨楓。","卓氏琴台廢，深蕪想徑通。"]', '诗', 'shi', '', NULL, '送朱休歸劒南 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15ba07c8-5a9f-4f8a-b11c-1beed25a1460', '寄長武朱尚書', '寄长武朱尚书', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["不日即登壇，槍旗一萬竿。","角吹邊月沒，鼓絕爆雷殘。","中國今如此，西荒可取難。","白衣思請謁，徒步在長安。"]', '["不日即登壇，槍旗一万竿。","角吹邊月沒，鼓絕爆雷殘。","中国今如此，西荒可取难。","白衣思請謁，徒步在长安。"]', '诗', 'shi', '', NULL, '寄長武朱尚書 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818cb93f-6549-4f55-adc9-23a230235068', '送皇甫侍御', '送皇甫侍御', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["曉鐘催早朝，自是赴嘉招。","舟泊湘江闊，田收楚澤遙。","雁驚起衰草，猨渴下寒條。","來使黔南日，時應問寂寥。"]', '["晓鐘催早朝，自是赴嘉招。","舟泊湘江闊，田收楚澤遙。","雁驚起衰草，猨渴下寒條。","来使黔南日，时應问寂寥。"]', '诗', 'shi', '', NULL, '送皇甫侍御 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4448bd3-4924-4a82-b58a-6532d93002a0', '郊居即事', '郊居即事', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["住此園林久，其如未是家。","葉書傳野意，簷溜煮胡茶。","雨後逢行鷺，更深聽遠蛙。","自然還往裏，多是愛煙霞。"]', '["住此园林久，其如未是家。","葉书傳野意，簷溜煮胡茶。","雨後逢行鷺，更深听远蛙。","自然還往裏，多是愛煙霞。"]', '诗', 'shi', '', NULL, '郊居即事 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c303b7c-4c33-4208-821d-8a57ae49c7d9', '夜集姚合宅期可公不至', '夜集姚合宅期可公不至', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["公堂秋雨夜，已是念園林。","何事疾病日，重論山水心。","孤燈明臘後，微雪下更深。","釋子乖來約，泉西寒磬音。"]', '["公堂秋雨夜，已是念园林。","何事疾病日，重論山水心。","孤灯明臘後，微雪下更深。","釋子乖来約，泉西寒磬音。"]', '诗', 'shi', '', NULL, '夜集姚合宅期可公不至 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcab20ce-9b61-4b69-9ecb-a648e51baa74', '喜李餘自蜀至', '喜李餘自蜀至', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["迢遰岷峨外，西南驛路高。","幾程尋嶮棧，獨宿聽寒濤。","白鳥飛還立，青猨斷更號。","往來從此過，詞體近風騷。"]', '["迢遰岷峨外，西南驛路高。","幾程尋嶮棧，独宿听寒濤。","白鸟飞還立，青猨斷更號。","往来從此過，词體近风騷。"]', '诗', 'shi', '', NULL, '喜李餘自蜀至 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2137c50c-26f6-4461-8547-7428ecc86434', '王侍御南原莊', '王侍御南原莊', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["買得足雲地，新栽藥數窠。","峰頭盤一徑，原下注雙河。","春寺閑眠久，晴臺獨上多。","南齋宿雨後，仍許重來麽。"]', '["買得足云地，新栽藥數窠。","峰头盤一徑，原下注雙河。","春寺闲眠久，晴台独上多。","南斋宿雨後，仍許重来麽。"]', '诗', 'shi', '', NULL, '王侍御南原莊 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29114c1-6de0-47b5-89a0-44a3902c1263', '送康秀才', '送康秀才', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["俱爲落第年，相識落花前。","酒瀉兩三盞，詩吟十數篇。","行岐逢塞雨，嘶馬上津船。","樹影高堂下，迴時應有蟬。"]', '["俱爲落第年，相識落花前。","酒瀉兩三盞，诗吟十數篇。","行岐逢塞雨，嘶马上津船。","樹影高堂下，迴时應有蟬。"]', '诗', 'shi', '', NULL, '送康秀才 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dae3361-74c2-4ec2-b55b-ea27029a9082', '送僧', '送僧', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["此生披衲過，在世得身閑。","日午遊都市，天寒往華山。","言歸文字外，意出有無間。","仙掌雲邊樹，巢禽時出關。"]', '["此生披衲過，在世得身闲。","日午游都市，天寒往华山。","言归文字外，意出有無间。","仙掌云邊樹，巢禽时出关。"]', '诗', 'shi', '', NULL, '送僧 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab67bab7-77e3-46d8-bd48-2bd2f58e76e1', '寄魏少府', '寄魏少府', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["來時乖面別，終日使人慙。","易記卷中句，難忘燈下談。","溼苔黏樹癭，瀑布濺房庵。","音信如相惠，移居古井南。"]', '["来时乖面別，終日使人慙。","易記卷中句，难忘灯下談。","溼苔黏樹癭，瀑布濺房庵。","音信如相惠，移居古井南。"]', '诗', 'shi', '', NULL, '寄魏少府 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6696fd47-adb8-4309-9f4d-23981e95d037', '原居即事言懷贈孫員外', '原居即事言懷贈孫員外', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["出入土門偏，秋深石色泉。","徑通原上草，地接水中蓮。","採菌依餘枿，拾薪逢刈田。","鑷撏白髮斷，兵阻尺書傳。","避路來華省，抄詩上彩牋。","高齋久不到，猶喜未經年。"]', '["出入土门偏，秋深石色泉。","徑通原上草，地接水中蓮。","採菌依餘枿，拾薪逢刈田。","鑷撏白髮斷，兵阻尺书傳。","避路来华省，抄诗上彩牋。","高斋久不到，猶喜未經年。"]', '诗', 'shi', '', NULL, '原居即事言懷贈孫員外 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b90fd66-eab6-46c7-9469-47c1a317de65', '登樓', '登楼', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["秋日登高望，涼風吹海初。","山川明已久，河漢沒無餘。","遠近涯寥敻，高低中太虛。","賦因王閣筆，思比謝遊疎。"]', '["秋日登高望，涼风吹海初。","山川明已久，河漢沒無餘。","远近涯寥敻，高低中太虛。","賦因王閣笔，思比謝游疎。"]', '诗', 'shi', '', NULL, '登樓 賈島 shi');
